// Package grant is moul's personal grant board.
//
// It is small on purpose. moul funds it out of his own pocket, moul is the
// only member, and it exists mainly so the coding agents working on his repos
// and the people he already works with have a way to ask for money against
// work they can prove they did: a request, a milestone, a link to the merged
// PR, a tranche. It is open to anyone, not only to agents, and nothing here is
// privileged to a bot.
//
// # What this is NOT
//
// It is not a faucet, and it is not an official gno.land grant program. There
// is no entitlement, no queue and no service level: a request can sit here
// unanswered, or be refused with one line of reasoning and nothing further.
// The official thing, where anyone asks for tokens and a DAO decides, is a
// separate program that does not exist yet, at a path this realm deliberately
// does not name: naming one would read as a commitment nobody has made. This
// realm is moul's own money and a proof of concept for the library under it.
//
// A bigger, multi-member, better funded program is a separate thing and will
// live at its own path. This one stays personal, and its limits are on the
// page rather than in a comment: one member means "a majority of the board" is
// one signature, and the board page says so.
//
// # What is here versus in the library
//
// Almost nothing. Every rule, every tally, every markdown page comes from
// gno.land/p/moul/grants/v0, which is pure and has no idea coins exist. This
// file is the chain-facing half: it turns the caller into an address and the
// block into a height, holds the one Program, moves ugnot through the banker,
// and emits events. That is deliberate, so the next board (multi-member,
// differently funded, maybe a different denom) is another file this short and
// not a fork of this one.
//
// # Who the caller is
//
// Every actor is PreviousRealm().Address(), the immediate caller. Called
// through another realm that is the calling REALM, not the user behind it.
// An agent holding a gno.land account session scoped to this path applies and
// submits proofs as its own address, which is exactly what makes an agent's
// track record on this board its own and not moul's.
package grant

import (
	"strconv"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/grants/v0"
)

const (
	// Denom is the only coin this board holds or pays.
	Denom = "ugnot"
	// Path is this realm's package path; its treasury is derived from it.
	Path = "gno.land/r/moul/grant/v0"
	// Link is Path as a gnoweb route.
	Link = "/r/moul/grant/v0"
)

// Owner is the founding and, for now, only member.
//
// Hardcoded rather than taken from the deployer: inside a plain
// `func Test(t *testing.T)` the gno test runner reports OriginCaller() as the
// EMPTY address, so a board seeded from it is empty in every test and
// something else on chain. That divergence is exactly where an authorization
// bug hides, so the address is written down.
const Owner = address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")

var program *grants.Program

func init() { reset() }

// reset installs a fresh, empty board. Also called by the tests: realm globals
// persist for a whole test binary and examples run after every Test, so a
// pinned Render has to start from a known state.
func reset() { program = grants.NewProgram(Denom, Owner) }

// Address is the treasury: this realm's own package address. Fund it by
// sending ugnot to it, or by calling Fund with `-send`.
func Address() address { return chain.PackageAddress(Path) }

// Balance is what the treasury actually holds.
func Balance() int64 {
	return banker.NewReadonlyBanker().GetCoins(Address()).AmountOf(Denom)
}

// Committed is what approved grants can still claim, Available is the balance
// minus that, and it can go negative. See the library for why.
func Committed() int64 { return program.Committed() }
func Available() int64 { return program.Available(Balance()) }

// Raised is everything donated through Fund, Disbursed everything paid out.
func Raised() int64    { return program.Raised() }
func Disbursed() int64 { return program.Disbursed() }

// Members lists the board.
func Members() []address { return program.Board.Members() }

// Requests is how many requests have ever been filed.
func Requests() int { return program.Board.Size() }

// Fund credits the ugnot sent with the call to the treasury and puts the donor
// on the record. Coins sent to the realm address directly still land in the
// treasury; they just do not get a name next to them.
func Fund(cur realm) {
	if !cur.IsCurrent() {
		panic("grant: spoofed realm")
	}
	// OriginSend is what the SIGNER attached, not what reached this realm. A
	// realm the user called keeps those coins and could call Fund any number of
	// times, booking each as a donation, so only a user call may read it.
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("grant: Fund must be called directly by an account, with -send")
	}
	from := prev.Address()
	amount := unsafe.OriginSend().AmountOf(Denom)
	if err := program.Fund(from, amount, runtime.ChainHeight()); err != nil {
		panic(err)
	}
	chain.Emit("Fund", "from", from.String(), "amount", strconv.FormatInt(amount, 10))
}

// Apply files a grant request for the caller. milestones reads
// "title:amount,title:amount", amounts in ugnot, paid in the order given.
// Returns the request id.
func Apply(cur realm, title, body, milestones string) int {
	if !cur.IsCurrent() {
		panic("grant: spoofed realm")
	}
	applicant := cur.Previous().Address()
	return file(applicant, applicant, "", title, body, milestones)
}

// ApplyFor files a grant request whose tranches pay beneficiary rather than
// the caller, with a reason for the detour that goes on the request page.
//
// This is the call that makes the board usable at all for the case it exists
// to serve. An account with nothing in it cannot pay the gas to ask for its
// first coins, so without someone else filing on its behalf the people who
// most need a small grant are exactly the people who cannot ask for one.
// Either address may then submit the proofs, and neither may vote.
func ApplyFor(cur realm, beneficiary, reason, title, body, milestones string) int {
	if !cur.IsCurrent() {
		panic("grant: spoofed realm")
	}
	applicant := cur.Previous().Address()
	return file(applicant, address(beneficiary), reason, title, body, milestones)
}

func file(applicant, beneficiary address, reason, title, body, milestones string) int {
	r, err := program.ApplyFor(applicant, beneficiary, reason, title, body, milestones,
		runtime.ChainHeight())
	if err != nil {
		panic(err)
	}
	chain.Emit("Apply", "id", strconv.Itoa(r.ID), "applicant", applicant.String(),
		"beneficiary", r.Payee().String(), "total", strconv.FormatInt(r.Total(), 10))
	return r.ID
}

// ProposeMember asks the board to add or remove a member. Members only.
func ProposeMember(cur realm, addr string, add bool, body string) int {
	if !cur.IsCurrent() {
		panic("grant: spoofed realm")
	}
	proposer := cur.Previous().Address()
	r, err := program.Board.SubmitMemberChange(proposer, address(addr), add, body, runtime.ChainHeight())
	if err != nil {
		panic(err)
	}
	chain.Emit("ProposeMember", "id", strconv.Itoa(r.ID), "subject", addr,
		"add", strconv.FormatBool(add))
	return r.ID
}

// Retract pulls the caller's own request before it is decided.
func Retract(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("grant: spoofed realm")
	}
	caller := cur.Previous().Address()
	if err := program.Board.Withdraw(caller, id, runtime.ChainHeight()); err != nil {
		panic(err)
	}
	chain.Emit("Retract", "id", strconv.Itoa(id))
}

// Vote records a member's ballot. The reason is stored and rendered next to
// the vote: it is the only part of a decision that tells an applicant what to
// do about it.
func Vote(cur realm, id int, approve bool, reason string) {
	if !cur.IsCurrent() {
		panic("grant: spoofed realm")
	}
	voter := cur.Previous().Address()
	st, err := program.Board.Vote(voter, id, approve, reason, runtime.ChainHeight())
	if err != nil {
		panic(err)
	}
	chain.Emit("Vote", "id", strconv.Itoa(id), "voter", voter.String(),
		"approve", strconv.FormatBool(approve), "status", st.String())
}

// SubmitProof offers evidence for the next milestone of an approved grant.
// kind is "url", "hash" or "text"; ref is the link, digest or statement.
func SubmitProof(cur realm, id, milestone int, kind, ref, note string) {
	if !cur.IsCurrent() {
		panic("grant: spoofed realm")
	}
	caller := cur.Previous().Address()
	p := grants.Proof{Kind: kind, Ref: ref, Note: note, Height: runtime.ChainHeight()}
	if err := program.Board.SubmitProof(caller, id, milestone, p); err != nil {
		panic(err)
	}
	chain.Emit("SubmitProof", "id", strconv.Itoa(id),
		"milestone", strconv.Itoa(milestone), "kind", kind)
}

// Review records a member's verdict on the proof under review. The verdict
// that carries also pays the tranche, in this same transaction. A verdict the
// treasury cannot cover is refused outright and changes nothing.
func Review(cur realm, id, milestone int, accept bool, reason string) {
	if !cur.IsCurrent() {
		panic("grant: spoofed realm")
	}
	voter := cur.Previous().Address()
	out, pay, err := program.Review(voter, id, milestone, accept, reason, runtime.ChainHeight(), Balance())
	if err != nil {
		panic(err)
	}
	chain.Emit("Review", "id", strconv.Itoa(id), "milestone", strconv.Itoa(milestone),
		"voter", voter.String(), "accept", strconv.FormatBool(accept), "outcome", out.String())
	if pay == nil {
		return
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).
		SendCoins(Address(), pay.To, chain.NewCoins(chain.NewCoin(Denom, pay.Amount)))
	chain.Emit("Release", "id", strconv.Itoa(id), "milestone", strconv.Itoa(milestone),
		"to", pay.To.String(), "amount", strconv.FormatInt(pay.Amount, 10))
}

package grant

// ExampleRender pins the board as it is at deploy: one member, no requests,
// an empty treasury. That IS the shipped state, since nothing is seeded here.
// For a board mid-flight, with ballots, refused proofs and a paid tranche,
// see the pinned pages in p/moul/grants/v0's render_test.gno; the markdown is
// generated by the same Renderer.
//
// It calls reset() first: realm globals persist for the whole test binary and
// examples run after every Test. The treasury BALANCE is not a realm global
// and reset() cannot clear it, so the tests are written to be balance-neutral
// (TestApplyApproveProveGetPaid pays out exactly what it funds). A test that
// issues coins and does not spend them shows up as a diff here, which is the
// point.
func ExampleRender() {
	reset()
	print(Render(""))
	// Output:
	// # moul's grant board
	//
	// A small, personal grant board. moul funds it out of his own pocket, and it
	// exists mainly so the coding agents working on his repos, and the people he
	// already works with, can ask for money against work they can prove they did: a
	// request, a milestone, a link to the merged PR, a tranche. It is open to anyone.
	// Nothing here is privileged to a bot.
	//
	// **This is not a faucet and it is not an official grant program.** It is one
	// person's money, sent by hand, mostly to people he already knows, and it is also
	// a proof of concept for the library underneath. There is no entitlement, no queue
	// and no service level: a request can sit here unanswered, or be refused with one
	// line of reasoning and nothing further. An official programme, where anyone asks
	// for tokens and a DAO decides, is a separate thing that does not exist yet, and
	// this page deliberately does not name a path for it: naming one would read as a
	// commitment nobody has made.
	//
	// **One member, and the page says so.** A majority of a one-member board is one
	// signature, so today this is moul deciding in public rather than a DAO deciding.
	// What makes it worth reading is the record: every ballot carries its reason,
	// every proof stays up including the refused ones, and every coin out is on the
	// ledger. A bigger multi-member program is a separate thing and will live at its
	// own path.
	//
	// **You can ask for someone else.** `ApplyFor` takes the address the money goes
	// to and a reason for the detour, and prints both on the request. That is not a
	// convenience: an account with nothing in it cannot pay the gas to ask for its
	// first coins, so on a board meant to fund empty accounts, someone else filing is
	// the only path that works. Either address may then submit the proofs, and neither
	// may vote on the request.
	//
	// **For agents.** A gno.land account session scoped to this path lets an agent
	// `Apply` and `SubmitProof` under its own address, so its track record here is
	// its own and not its operator's. A session cannot be given a board seat by
	// scoping alone: voting is membership, and membership is a request the board
	// decides.
	//
	// ## Treasury
	//
	// | Field | Value |
	// |---|---|
	// | Address | `g1uah596w03ufkslrjfg8erxszvjq3zra6avs37n` |
	// | Balance | 0 ugnot |
	// | Promised | 0 ugnot |
	// | Unpromised | 0 ugnot |
	// | Donated | 0 ugnot |
	// | Paid out | 0 ugnot |
	//
	// ## Board
	//
	// A decision needs a majority of the members eligible to cast a ballot on it,
	// recomputed every time: the party a decision is about never votes on it, so an
	// applicant who sits on the board shrinks the room rather than packing it.
	//
	// | Member | Joined at height |
	// |---|---|
	// | `g1manfred47kzduec920z88wfr64ylksmdcedlf5` | 0 |
	//
	// ## Requests
	//
	// Nothing has been asked of this board yet. `Apply` is open to anyone.
	//
	// ## Where the money went
	//
	// [The ledger](/r/moul/grant/v0:ledger) lists every donation in and every tranche
	// out, with the height, the payee and the milestone it paid for.
	//
	// ## Calling it
	//
	// ```sh
	// # put money in
	// gnokey maketx call -pkgpath gno.land/r/moul/grant/v0 -func Fund -send 5000000ugnot ...
	// # ask for some
	// gnokey maketx call -pkgpath gno.land/r/moul/grant/v0 -func Apply \
	//   -args 'Port the thing' -args 'why it matters' -args 'design:100,ship:400' ...
	// # ask on behalf of someone who cannot pay the gas to ask
	// gnokey maketx call -pkgpath gno.land/r/moul/grant/v0 -func ApplyFor \
	//   -args g1... -args 'their account is empty' \
	//   -args 'Port the thing' -args 'why it matters' -args 'design:100,ship:400' ...
	// # decide (members only)
	// gnokey maketx call -pkgpath gno.land/r/moul/grant/v0 -func Vote -args 1 -args true -args 'reason' ...
	// # show your work, then get paid for it
	// gnokey maketx call -pkgpath gno.land/r/moul/grant/v0 -func SubmitProof \
	//   -args 1 -args 0 -args url -args 'https://...' -args 'what it is' ...
	// gnokey maketx call -pkgpath gno.land/r/moul/grant/v0 -func Review -args 1 -args 0 -args true -args 'looks done' ...
	// ```
	//
	// Built on [p/moul/grants/v0](/p/moul/grants/v0), which holds every rule, every
	// tally and this page's markdown, and has no idea coins exist.
}

// ExampleRenderLedger pins the money trail of a board nobody has funded yet.
func ExampleRenderLedger() {
	reset()
	print(Render("ledger"))
	// Output:
	// # moul's grant board: the ledger
	//
	// Every coin in and every coin out, in the order it happened. Coins sent
	// straight to `g1uah596w03ufkslrjfg8erxszvjq3zra6avs37n` land in the treasury
	// without appearing here, which is why `Fund` exists: it is the same transfer
	// with a name attached.
	//
	// ## In
	//
	// Nothing donated through `Fund` yet.
	//
	// ## Out
	//
	// No tranche has been released yet.
	//
	// Balance now: 0 ugnot. [Back to the board](/r/moul/grant/v0).
}

// Package reactions is a reaction block any realm can embed, keyed on the page
// it appears on rather than on the realm that stores it.
//
// It is the shape the web settled on for this in 2010: one hosted widget, the
// same snippet pasted everywhere, deciding what to show from the page
// identifier it is handed. Here the snippet is two lines of gno:
//
//	import "gno.land/r/moul/reactions/v0"
//
//	func Render(path string) string {
//		return body + reactions.RenderBlock()
//	}
//
// [RenderBlock] takes no argument because it does not need one: a plain read
// exported by a realm and called by another opens no realm frame, so
// unsafe.CurrentRealm() inside it reports the CALLER. The host realm's own path
// is the page key, and nothing has to be configured, registered or passed.
// [RenderBlockFor] is the explicit form, for a realm that renders more than one
// page or already holds its path as a constant.
//
// The host realm stores nothing. Every tally lives here, so a realm can add
// reactions without a redeploy the next time it wants to change them, and a
// reader's reaction survives the host realm being replaced.
//
// # What it is not
//
// Not a comment system. There is no text field anywhere, which is what makes
// it possible to run with no moderation at all: six emoji, one reaction per
// address per page, changeable and removable. The page shows the tally and who
// reacted last. That is the whole feature.
package reactions

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	rx "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/reactions/v0"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from unsafe.CurrentRealm(),
// which reports the CALLER in every read this realm exports and would therefore
// build every link against whichever realm embedded the block.
const realmPath = "gno.land/r/moul/reactions/v0"

// board holds every page's tally.
//
// A redeploy would wipe it, which is why this realm is not private (see
// gnomod.toml): the state here belongs to everyone who reacted, and the only
// honest way to change this realm is a v1 beside it.
var board = rx.NewBoard()

// React records the caller's reaction to page.
//
// page is a package path, the full one: "gno.land/r/moul/home". It does not
// have to be a realm that embeds the block, and nothing checks that it exists.
// A page is just a name, which is what lets a realm key the block on something
// finer than itself.
//
// key is one of the palette names, not a glyph: "up", "heart", "fire", "party",
// "rocket", "eyes". Render("") lists them with their emoji.
//
// One reaction per address per page. Reacting again with a different key moves
// it; reacting with the same key changes nothing but the "last reaction" line.
func React(cur realm, page, key string) {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !rx.Valid(key) {
		panic("reactions: no such reaction: " + key)
	}
	if !rx.ValidPage(page) {
		panic("reactions: not a page key: " + page)
	}

	who := unsafe.PreviousRealm().Address()
	board.React(page, who, key, runtime.ChainHeight())
	chain.Emit("React", "page", page, "key", key, "who", who.String())
}

// Unreact removes the caller's reaction from page. It aborts when there is
// none, rather than succeeding silently, so a misspelled page key is visible
// instead of looking like a no-op.
func Unreact(cur realm, page string) {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	who := unsafe.PreviousRealm().Address()
	if !board.Unreact(page, who) {
		panic("reactions: nothing to remove on " + page)
	}
	chain.Emit("Unreact", "page", page, "who", who.String())
}

// RenderBlock returns the block for the realm CALLING it, which is the form a
// host realm embeds.
//
// It has no cur realm parameter on purpose. A plain read is borrowed: gno opens
// no realm frame for it, so unsafe.CurrentRealm() reports the caller's path and
// the block keys itself with no argument. Adding a cur realm here would
// silently reverse that and key every embed to this realm instead.
//
// Calling it from inside this realm therefore keys on this realm, which is
// never what a caller wants; the views below use the unexported blockFor.
func RenderBlock() string {
	return blockFor(unsafe.CurrentRealm().PkgPath())
}

// RenderBlockFor is [RenderBlock] for a named page. Use it from a crossing
// function, where there is no caller to read off the stack, or when one realm
// renders several pages.
func RenderBlockFor(page string) string { return blockFor(page) }

// blockFor is the shared body, so no exported read of this realm calls another
// and picks up the wrong path.
func blockFor(page string) string {
	return rx.Block(realmPath, page, board.Page(page))
}

// Count reports how many addresses have a reaction on page.
func Count(page string) int { return board.Page(page).Total() }

// CountOf reports how many addresses hold one particular reaction on page.
func CountOf(page, key string) int { return board.Page(page).Count(key) }

// ReactionOf returns who's current reaction key on page, or "" when they have
// none. A host realm can use it to say "you reacted" without reading the tree.
func ReactionOf(page string, who address) string { return board.Page(page).Of(who) }

// Last returns the most recent reaction on page: the palette key, the address,
// and the height. The key is "" when the page has never been reacted to.
func Last(page string) (key string, who address, height int64) {
	return board.Page(page).Last()
}

// Pages reports how many pages have ever been reacted to.
func Pages() int { return board.Pages() }

package reactions

import (
	"strconv"
	"strings"
	"testing"

	rx "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/reactions/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const homePage = "gno.land/r/moul/home"

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
)

// reset clears realm state. Realm globals live for the whole test binary, and
// the Example runs after every Test, so everything that renders starts here.
func reset() { board = rx.NewBoard() }

func TestReactAndUnreact(cur realm, t *testing.T) {
	reset()

	testing.SetRealm(testing.NewUserRealm(alice))
	React(cross(cur), homePage, rx.KeyUp)
	testing.SetRealm(testing.NewUserRealm(bob))
	React(cross(cur), homePage, rx.KeyFire)

	uassert.Equal(t, 2, Count(homePage))
	uassert.Equal(t, 1, CountOf(homePage, rx.KeyUp))
	uassert.Equal(t, rx.KeyUp, ReactionOf(homePage, alice))
	uassert.Equal(t, 1, Pages())

	key, who, _ := Last(homePage)
	uassert.Equal(t, rx.KeyFire, key)
	uassert.Equal(t, bob, who)

	testing.SetRealm(testing.NewUserRealm(alice))
	Unreact(cross(cur), homePage)
	uassert.Equal(t, 1, Count(homePage))
	uassert.Equal(t, "", ReactionOf(homePage, alice))
}

func TestReadsOnAnUntouchedPageAreZero(t *testing.T) {
	reset()
	uassert.Equal(t, 0, Count("gno.land/r/nobody/here"))
	uassert.Equal(t, 0, CountOf("gno.land/r/nobody/here", rx.KeyUp))
	uassert.Equal(t, "", ReactionOf("gno.land/r/nobody/here", alice))
	key, _, _ := Last("gno.land/r/nobody/here")
	uassert.Equal(t, "", key)
}

func TestReactRefusals(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "reactions: no such reaction: poop", func() {
		React(cross(cur), homePage, "poop")
	})

	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "reactions: not a page key: not a path", func() {
		React(cross(cur), "not a path", rx.KeyUp)
	})

	uassert.Equal(t, 0, Pages(), "a refused reaction creates no page")
}

// TestUnreactAbortsRatherThanNoOp is the deliberate asymmetry: a misspelled
// page key on Unreact has to be visible, or a reader thinks they removed
// something they did not.
func TestUnreactAbortsRatherThanNoOp(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "reactions: nothing to remove on "+homePage, func() {
		Unreact(cross(cur), homePage)
	})
}

// TestRenderBlockForIsWhatTheBlockLinksTo pins the property a host realm
// depends on: every link in the embedded block points at THIS realm, not at
// the realm that embedded it, and carries the page key as an argument.
func TestRenderBlockForIsWhatTheBlockLinksTo(t *testing.T) {
	reset()
	got := RenderBlockFor(homePage)
	uassert.True(t, strings.Contains(got, "(/r/moul/reactions/v0$help&func=React&"),
		"the txlink targets this realm")
	uassert.True(t, strings.Contains(got, "page=gno.land%2Fr%2Fmoul%2Fhome"),
		"and carries the host page as the parameter")
	uassert.False(t, strings.Contains(got, "/r/moul/home$help"),
		"never the host realm, which has no React to call")
}

// TestRenderBlockKeysOnTheCaller is the borrowed-read rule this realm's whole
// ergonomics rest on: RenderBlock has no cur realm parameter, so gno opens no
// frame for it and unsafe.CurrentRealm() reports whoever called.
//
// In-package there is no other realm to call from, so what this pins is the
// half that can be pinned here: RenderBlock agrees with RenderBlockFor when
// the caller IS this realm. The cross-realm half is measured in AGENTS.md
// (2026-09-22) and is the same mechanism r/moul/config's TopBlock uses.
func TestRenderBlockKeysOnTheCaller(t *testing.T) {
	reset()
	uassert.Equal(t, RenderBlockFor(realmPath), RenderBlock())
	uassert.NotEqual(t, RenderBlockFor(homePage), RenderBlock(),
		"and a different page is a different block")
}

func TestRenderPageView(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	React(cross(cur), homePage, rx.KeyUp)

	got := Render(homePage)
	uassert.True(t, strings.HasPrefix(got, "# gno\\.land/r/moul/home\n"),
		"the heading is the page key, escaped: ui.Inline backslashes the dot")
	uassert.True(t, strings.Contains(got, "Last reaction: \U0001F44D by "))
	uassert.True(t, strings.Contains(got, "Remove my reaction"))
	uassert.True(t, strings.Contains(got, "[The board](/r/moul/reactions/v0)"))
}

func TestRenderRejectsAPathThatIsNotAPageKey(t *testing.T) {
	reset()
	got := Render("[click](http://e.vil)")
	uassert.True(t, strings.HasPrefix(got, "# Not a page\n"))
	uassert.False(t, strings.Contains(got, "](http://e.vil)"),
		"a render path is escaped before it is shown back")
}

// TestRenderHomeShowsTheBoard uses uassert rather than an Example because the
// page contains consecutive blank lines, which gno collapses inside an
// // Output: block.
func TestRenderHomeShowsTheBoard(cur realm, t *testing.T) {
	reset()
	uassert.True(t, strings.Contains(Render(""), "*No page has been reacted to yet.*"))

	testing.SetRealm(testing.NewUserRealm(alice))
	React(cross(cur), homePage, rx.KeyParty)

	got := Render("")
	uassert.True(t, strings.Contains(got,
		"| [gno\\.land/r/moul/home](/r/moul/reactions/v0:gno.land/r/moul/home) | 1 |"),
		"the cell text is escaped, the URL is not: they are different contexts")
	uassert.True(t, strings.Contains(got, "import \"gno.land/r/moul/reactions/v0\""),
		"the homepage is the getting-started doc, and the snippet is copy-pasteable")
	for _, k := range rx.Keys() {
		uassert.True(t, strings.Contains(got, "| `"+k+"` | "+rx.Emoji(k)+" |"), k)
	}
}

// TestBoardIndexIsCapped: the number of pages is unbounded, the index is not.
func TestBoardIndexIsCapped(cur realm, t *testing.T) {
	reset()
	for i := 0; i < maxListed+3; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		// Zero-padded, because avl keys sort as strings and ufmt has no width
		// flags: "p9" would otherwise sort between "p10" and "p11".
		n := strconv.Itoa(i)
		if len(n) < 2 {
			n = "0" + n
		}
		React(cross(cur), "gno.land/r/spam/p"+n, rx.KeyUp)
	}
	uassert.Equal(t, maxListed+3, Pages())

	got := Render("")
	uassert.Equal(t, maxListed, strings.Count(got, "(/r/moul/reactions/v0:gno.land/r/spam/"))
	uassert.True(t, strings.Contains(got, "28 pages in total, 25 shown."))
}

package reactions

import (
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	rx "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/reactions/v0"
)

// maxListed caps the board index. The number of pages is unbounded (anyone can
// react to any key), and a Render that grows with it would eventually be too
// expensive to serve. The cap is on the INDEX only: every page keeps its own
// view at /r/moul/reactions/v0:<page>, whether or not it is listed here.
const maxListed = 25

// Render serves two views:
//
//	""       the getting-started page: how to embed the block, plus the board
//	"<page>" one page's tally, where <page> is a package path
//
// The page view's path is the key itself, so the link under any embedded block
// is just this realm's path, a colon, and the page. That is why a page key may
// contain a colon of its own: "gno.land/r/you/blog:hello" reads back whole.
func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if !rx.ValidPage(path) {
		return "# Not a page\n\n" + ui.Inline(path) + " is not a page key: a key is a " +
			"package path, lowercase ASCII, at most " + strconv.Itoa(rx.MaxPageLen) +
			" bytes.\n\n[Back to the board](" + selfURL() + ")\n"
	}
	return renderPage(path)
}

// selfURL is this realm's own gnoweb path, derived from realmPath the same way
// every link in the block is, so there is one rule and not two. A function and
// not a package-level var: a package-level var in a realm is realm STATE,
// persisted and re-read on every call, which is a strange thing for a string
// the compiler could have folded.
func selfURL() string { return rx.RealmURL(realmPath) }

func renderHome() string {
	var b strings.Builder

	b.WriteString("# Reactions\n\n")
	b.WriteString("A reaction block any realm can embed. One line in your `Render`, no state ")
	b.WriteString("on your side, and readers get one-click reactions keyed on the page they ")
	b.WriteString("are looking at.\n\n")
	b.WriteString("It is not a comment system, on purpose. There is no text field anywhere, ")
	b.WriteString("which is what lets it run with no moderation: a closed palette, one ")
	b.WriteString("reaction per address per page, changeable and removable.\n\n")

	b.WriteString("## It looks like this\n\n")
	b.WriteString(blockFor(realmPath))
	b.WriteString("\nThat block is live and it is this realm's own page. Click one.\n\n")

	b.WriteString("## Add it to your realm\n\n")
	b.WriteString("```go\n")
	b.WriteString("import \"" + realmPath + "\"\n\n")
	b.WriteString("func Render(path string) string {\n")
	b.WriteString("\treturn body + reactions.RenderBlock()\n")
	b.WriteString("}\n")
	b.WriteString("```\n\n")
	b.WriteString("That is the whole integration. `RenderBlock` takes no argument because it ")
	b.WriteString("does not need one: a plain read exported by one realm and called by ")
	b.WriteString("another opens no realm frame, so it sees YOUR path and uses it as the ")
	b.WriteString("page key. Nothing to register, nothing to configure.\n\n")
	b.WriteString("For one block per article rather than one per realm, name the page ")
	b.WriteString("yourself with the path you already serve:\n\n")
	b.WriteString("```go\n")
	b.WriteString("return body + reactions.RenderBlockFor(\"gno.land/r/you/blog:\" + path)\n")
	b.WriteString("```\n\n")
	b.WriteString("Reactions are recorded here, not in your realm, so redeploying yours ")
	b.WriteString("never loses them.\n\n")

	b.WriteString("## The palette\n\n")
	t := ui.NewTable("key", "")
	for _, k := range rx.Keys() {
		t.Row("`"+k+"`", rx.Emoji(k))
	}
	b.WriteString(t.String())
	b.WriteString("\nSix, and the set is closed. `React` aborts on anything else, which is ")
	b.WriteString("the entire moderation policy.\n\n")

	b.WriteString("## The board\n\n")
	b.WriteString(renderBoard())

	return b.String()
}

// renderBoard lists pages in key order, not by activity. Key order is the order
// the tree already walks, so the listing is stable between identical calls;
// ranking would need a second index maintained on every write, which is a lot
// of machinery for a table nobody navigates by.
func renderBoard() string {
	n := board.Pages()
	if n == 0 {
		return ui.Empty("No page has been reacted to yet.")
	}

	t := ui.NewTable("page", "reactions", "last")
	board.Each(func(page string, p *rx.Page) bool {
		key, who, _ := p.Last()
		last := "-"
		if key != "" {
			last = rx.Emoji(key) + " " + ui.Addr(who)
		}
		t.Row(
			"["+ui.Cell(page)+"]("+rx.PageURL(realmPath, page)+")",
			strconv.Itoa(p.Total()),
			last,
		)
		return t.Len() >= maxListed
	})

	out := t.String()
	if n > maxListed {
		out += "\n" + strconv.Itoa(n) + " pages in total, " + strconv.Itoa(maxListed) +
			" shown. Every page has its own view at `" + selfURL() + ":<page>`.\n"
	}
	return out
}

func renderPage(page string) string {
	p := board.Page(page)

	var b strings.Builder
	b.WriteString("# " + ui.Inline(page) + "\n\n")
	b.WriteString(blockFor(page))
	b.WriteString("\n")

	if p.Total() == 0 {
		b.WriteString(ui.Empty("Nobody is reacting to this page right now."))
	} else {
		t := ui.NewTable("", "reaction", "addresses")
		for _, k := range rx.Keys() {
			if c := p.Count(k); c > 0 {
				t.Row(rx.Emoji(k), "`"+k+"`", strconv.Itoa(c))
			}
		}
		b.WriteString(t.String())
	}

	if key, who, height := p.Last(); key != "" {
		b.WriteString("\nLast reaction: " + rx.Emoji(key) + " by " + ui.Addr(who) +
			" at height " + strconv.FormatInt(height, 10) + ".\n")
	}

	b.WriteString("\n" + ui.ActionIn(realmPath, "Remove my reaction", "Unreact", "page", page))
	b.WriteString(" · [The board](" + selfURL() + ")\n")
	return b.String()
}

package toolbox

import (
	"net/url"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/realmpath/v0"
	tb "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/toolbox/v0"
)

// Render routes gnoweb paths:
//
//	/                 the directory
//	/?tag=identity    the directory, filtered to one tag
//	/<slug>           one tool
func Render(path string) string {
	req := realmpath.Parse(path)
	parts := req.PathParts()

	if len(parts) == 0 || parts[0] == "" {
		return renderIndex(req.Query.Get("tag"))
	}
	if len(parts) > 1 {
		return renderUnknown(parts[0] + "/" + parts[1])
	}
	t, ok := catalog.Get(parts[0])
	if !ok {
		return renderUnknown(parts[0])
	}
	return renderTool(t)
}

func renderIndex(tag string) string {
	var b strings.Builder
	b.WriteString(md.H1("Toolbox"))
	b.WriteString("\nSmall utilities on gno.land. Each one is its own realm, composing contracts that are already on chain and showing the answer as a page instead of as a query you have to compose.\n")

	list := catalog.List()
	if tag != "" {
		list = catalog.ByTag(tag)
		b.WriteString("\nFiltered to " + md.InlineCode(tag) + ". " +
			md.Link("Show all", hubURL) + "\n")
	}
	b.WriteString("\n" + tb.Index(list))

	if tag == "" {
		if links := tagLinks(catalog, hubURL); links != "" {
			b.WriteString("\nTags: " + links + "\n")
		}
	}

	b.WriteString("\n" + md.H2("What a tool is"))
	b.WriteString("\n" + md.BulletList([]string{
		"A realm at " + md.InlineCode("gno.land/r/moul/toolbox/<slug>") + ", reachable on its own.",
		"Read-only unless it says otherwise: a page you open, not a transaction you sign.",
		"Composed from contracts already on chain, so the toolbox adds the view and not the data.",
	}))
	return b.String()
}

// tagLinks renders the tag filter row, or "" when nothing is tagged.
//
// QueryEscape, not plain concatenation: a tag is an arbitrary string on Tool,
// and "a&b" would otherwise become a second query parameter while "a#b" would
// become a fragment, in both cases linking to a filter nobody asked for.
func tagLinks(c *tb.Catalog, base string) string {
	tags := c.Tags()
	if len(tags) == 0 {
		return ""
	}
	links := make([]string, 0, len(tags))
	for _, name := range tags {
		links = append(links, md.Link(name, base+"?tag="+url.QueryEscape(name)))
	}
	return strings.Join(links, " · ")
}

func renderTool(t tb.Tool) string {
	var b strings.Builder
	b.WriteString(tb.Nav(hubURL, "Toolbox"))
	b.WriteString("\n" + tb.Card(t))
	return b.String()
}

func renderUnknown(slug string) string {
	var b strings.Builder
	b.WriteString(md.H1("Not found"))
	b.WriteString("\nNo tool called " + md.InlineCode(slug) + ".\n")
	b.WriteString("\n" + md.Link("Back to the toolbox", hubURL) + "\n")
	return b.String()
}

package toolbox

// ExampleRender pins the directory page. The catalog is compiled in, so this
// output changes only when a tool is added or re-described, which is exactly
// when a reviewer should see the diff.
func ExampleRender() {
	print(Render(""))
	// Output:
	// # Toolbox
	//
	// Small utilities on gno.land. Each one is its own realm, composing contracts that are already on chain and showing the answer as a page instead of as a query you have to compose.
	//
	// | Tool | What it does | Tags |
	// | --- | --- | --- |
	// | [Usernames](/r/moul/toolbox/usernames) | Resolve a gno\.land username to an address, or an address to a username\. | identity, read |
	//
	// Tags: [identity](/r/moul/toolbox?tag=identity) · [read](/r/moul/toolbox?tag=read)
	//
	// ## What a tool is
	//
	// - A realm at `gno.land/r/moul/toolbox/<slug>`, reachable on its own.
	// - Read-only unless it says otherwise: a page you open, not a transaction you sign.
	// - Composed from contracts already on chain, so the toolbox adds the view and not the data.
}

// Package toolbox is the directory of moul's small gno.land utilities: one
// page listing every tool, each tool a realm of its own at
// `r/moul/toolbox/<slug>`.
//
// It holds no logic. A tool composes other contracts (resolve a username,
// read a DAO, decode a denom) and renders the answer; this realm only says
// which tools exist and where they are. The model, the rendering and the
// query-form builder are
// [p/moul/toolbox](/p/moul/toolbox/v0).
//
// # Why the catalog is compiled in and not registered
//
// The obvious design is the opposite one: each tool calls `Register` on this
// realm from its own init, and the directory assembles itself. That design is
// unavailable here, and the reason is worth stating because it is not a
// preference.
//
// `private = true` buys redeploy-in-place at the same path and costs the
// ability to be imported: the type checker refuses any realm importing a
// private one (`ImportPrivateError`, `gnovm/pkg/gnolang/gotypecheck.go`). So a
// private hub cannot be imported by its tools, and a hub that accepts
// registration has to be public. A public realm can never be redeployed, which
// would freeze this path at v0 and move the directory's URL on the first bug
// in it.
//
// A stable URL is the whole point of a directory, so the trade goes the other
// way: everything here is private and redeployable, and adding a tool is one
// entry in [tools] plus a redeploy. The catalog is rebuilt from source every
// time, so the redeploy wipe costs nothing: there is no state to lose.
//
// [p/moul/toolbox.Catalog] stays mutable for whoever wants the other trade.
package toolbox

import "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/toolbox/v0"

// hubPath is this realm's own path. A realm can ask the chain for it, but a
// constant is what [p/moul/toolbox.SlugOf] is checked against in tests, where
// there is no chain frame to ask.
const hubPath = "gno.land/r/moul/toolbox"

// hubURL is the gnoweb path of this realm, which every tool page links back
// to. A tool cannot import this realm to read it, so each one repeats it; this
// is the copy that is authoritative.
const hubURL = "/r/moul/toolbox"

// tools is the directory. Adding one here and redeploying is how the toolbox
// grows; see the package doc for why it is not a registration call.
//
// Every entry must be a realm under this one: [buildCatalog] refuses an entry
// whose slug does not match its path, so a copy-paste that keeps the wrong
// path fails the deploy rather than publishing a dead link.
var tools = []toolbox.Tool{
	{
		Slug:  "usernames",
		Path:  "gno.land/r/moul/toolbox/usernames",
		Title: "Usernames",
		Desc:  "Resolve a gno.land username to an address, or an address to a username.",
		Tags:  []string{"identity", "read"},
	},
}

// catalog is the directory, sorted and checked once at deploy.
var catalog = buildCatalog()

func buildCatalog() *toolbox.Catalog {
	c := &toolbox.Catalog{}
	for _, t := range tools {
		if err := c.Set(t); err != nil {
			panic(err)
		}
		if got := toolbox.SlugOf(hubPath, t.Path); got != t.Slug {
			panic("toolbox: " + t.Slug + " is declared at " + t.Path +
				", which is not gno.land/r/moul/toolbox/" + t.Slug)
		}
	}
	return c
}

// Count is how many tools the directory holds.
func Count() int { return catalog.Len() }

// Slugs lists every tool's slug, in directory order.
//
//	gnokey query vm/qeval -data 'gno.land/r/moul/toolbox.Slugs()'
func Slugs() []string {
	out := make([]string, 0, catalog.Len())
	for _, t := range catalog.List() {
		out = append(out, t.Slug)
	}
	return out
}

// PathOf returns the package path of one tool, or "" when there is no such
// tool. Flat strings rather than the struct: a nested value inside a persisted
// object prints as an opaque `ref(...)` over `vm/qeval`, so a read API that is
// meant to be queried returns scalars.
//
//	gnokey query vm/qeval -data 'gno.land/r/moul/toolbox.PathOf("usernames")'
func PathOf(slug string) string {
	t, ok := catalog.Get(slug)
	if !ok {
		return ""
	}
	return t.Path
}

// TitleOf returns the human name of one tool, or "".
func TitleOf(slug string) string {
	t, ok := catalog.Get(slug)
	if !ok {
		return ""
	}
	return t.Title
}

// DescOf returns the one-line description of one tool, or "".
func DescOf(slug string) string {
	t, ok := catalog.Get(slug)
	if !ok {
		return ""
	}
	return t.Desc
}

// Has reports whether a tool with that slug is listed.
func Has(slug string) bool { return catalog.Has(slug) }

// Tags lists every tag any tool carries, each once.
func Tags() []string { return catalog.Tags() }

package toolbox

import (
	"strings"
	"testing"

	tb "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/toolbox/v0"
	"gno.land/p/nt/uassert/v0"
)

// TestEveryToolIsNested is the check that makes the compiled-in catalog safe:
// a copy-pasted entry that kept the wrong path would publish a dead link, and
// buildCatalog panics on it at deploy rather than at read.
func TestEveryToolIsNested(t *testing.T) {
	uassert.True(t, len(tools) > 0)
	for _, tool := range tools {
		uassert.NoError(t, tool.Validate())
		uassert.Equal(t, tool.Slug, tb.SlugOf(hubPath, tool.Path))
	}
}

func TestReadAPI(t *testing.T) {
	uassert.Equal(t, len(tools), Count())
	uassert.True(t, Has("usernames"))
	uassert.False(t, Has("nope"))
	uassert.Equal(t, "gno.land/r/moul/toolbox/usernames", PathOf("usernames"))
	uassert.Equal(t, "Usernames", TitleOf("usernames"))
	uassert.True(t, strings.Contains(DescOf("usernames"), "address"))

	uassert.Equal(t, "", PathOf("nope"))
	uassert.Equal(t, "", TitleOf("nope"))
	uassert.Equal(t, "", DescOf("nope"))
}

func TestSlugsAreSorted(t *testing.T) {
	got := Slugs()
	uassert.Equal(t, Count(), len(got))
	for i := 1; i < len(got); i++ {
		uassert.True(t, got[i-1] < got[i])
	}
}

func TestTags(t *testing.T) {
	got := Tags()
	uassert.True(t, len(got) > 0)
	found := false
	for _, tag := range got {
		if tag == "identity" {
			found = true
		}
	}
	uassert.True(t, found)
}

func TestRenderIndex(t *testing.T) {
	got := Render("")
	uassert.True(t, strings.Contains(got, "# Toolbox"))
	uassert.True(t, strings.Contains(got, "[Usernames](/r/moul/toolbox/usernames)"))
	uassert.True(t, strings.Contains(got, "Tags:"))
}

func TestRenderTagFilter(t *testing.T) {
	kept := Render("?tag=identity")
	uassert.True(t, strings.Contains(kept, "[Usernames](/r/moul/toolbox/usernames)"))
	uassert.True(t, strings.Contains(kept, "Show all"))

	empty := Render("?tag=nope")
	uassert.True(t, strings.Contains(empty, "No tools yet."))
	uassert.False(t, strings.Contains(empty, "[Usernames]"))
}

// TestTagLinkIsURLEscaped: a tag is an arbitrary string on Tool, and
// concatenating one into a query string unescaped turns "a&b" into two
// parameters and "a#b" into a fragment, so the link filters by something
// nobody asked for. Values copied from what QueryEscape actually emits.
func TestTagLinkIsURLEscaped(t *testing.T) {
	var c tb.Catalog
	uassert.NoError(t, c.Set(tb.Tool{
		Slug:  "weird",
		Path:  "gno.land/r/moul/toolbox/weird",
		Title: "Weird",
		Tags:  []string{"a&b c"},
	}))

	got := tagLinks(&c, hubURL)
	uassert.True(t, strings.Contains(got, "?tag=a%26b+c"))
	uassert.False(t, strings.Contains(got, "?tag=a&b c"))
}

func TestTagLinksEmpty(t *testing.T) {
	var c tb.Catalog
	uassert.Equal(t, "", tagLinks(&c, hubURL))
}

func TestRenderTool(t *testing.T) {
	got := Render("usernames")
	uassert.True(t, strings.Contains(got, "[toolbox](/r/moul/toolbox)"))
	uassert.True(t, strings.Contains(got, "## Usernames"))
	uassert.True(t, strings.Contains(got, "`gno.land/r/moul/toolbox/usernames`"))
}

func TestRenderUnknown(t *testing.T) {
	for _, path := range []string{"nope", "a/b", "usernames/extra"} {
		got := Render(path)
		uassert.True(t, strings.Contains(got, "# Not found"))
		uassert.True(t, strings.Contains(got, "Back to the toolbox"))
	}
}

// TestRenderNeverEmitsTwoBlankLines: gno collapses them in an Output block, so
// a Render that produces one can never be pinned by an example. Checked here
// rather than discovered later.
func TestRenderNeverEmitsTwoBlankLines(t *testing.T) {
	for _, path := range []string{"", "?tag=identity", "usernames", "nope"} {
		uassert.False(t, strings.Contains(Render(path), "\n\n\n"))
	}
}

package usernames

import (
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/realmpath/v0"
	tb "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/toolbox/v0"
	"gno.land/r/sys/users"
)

// hubURL is the toolbox this tool belongs to. A private realm cannot import
// the hub, so the link is a constant on this side; `r/moul/toolbox` holds the
// authoritative copy and its tests check that the tool path matches.
const hubURL = "/r/moul/toolbox"

// maxInput bounds what is echoed back into the page. A render that reflects an
// unbounded query parameter is a page anyone can make arbitrarily large.
const maxInput = 64

// Render routes gnoweb paths:
//
//	/                the form, and what the tool answers
//	/lookup?q=moul   the result, which is where the form submits
//	/moul            the same result, addressable directly
//	/g1manfred...    the same, by address
func Render(path string) string {
	req := realmpath.Parse(path)
	parts := req.PathParts()

	input := req.Query.Get("q")
	if input == "" && len(parts) == 1 && parts[0] != "" && parts[0] != "lookup" {
		input = parts[0]
	}
	if len(parts) > 1 {
		return header() + "\n" + notFound(strings.Join(parts, "/"))
	}
	if input == "" {
		return header() + "\n" + renderHome()
	}
	return header() + "\n" + renderResult(input)
}

func header() string {
	return tb.Nav(hubURL, "Usernames")
}

func renderHome() string {
	var b strings.Builder
	b.WriteString(md.H1("Usernames"))
	b.WriteString("\nWho holds a name, and what name an address holds. Type either one.\n")
	b.WriteString("\n" + form())
	b.WriteString("\n" + md.H2("What this answers"))
	b.WriteString("\n" + md.BulletList([]string{
		"The address behind a username, and the username behind an address.",
		"Whether the name you typed is their **current** name or one they renamed away from.",
		"The canonical key the name collapses to, and who already holds that key.",
	}))
	b.WriteString("\n" + md.H2("The same thing from a terminal"))
	b.WriteString("\nThis page is " + md.InlineCode("r/sys/users") +
		" read through " + md.InlineCode("vm/qeval") + ", with the follow-up questions already asked:\n")
	b.WriteString("\n" + md.LanguageCodeBlock("sh", qevalCommand("moul")))
	b.WriteString("\nTry " + md.Link("moul", "/r/moul/toolbox/usernames:moul") +
		", or paste an address into the box above.\n")
	return b.String()
}

func renderResult(input string) string {
	var b strings.Builder
	b.WriteString(md.H1("Usernames"))
	b.WriteString("\n" + form())

	data := lookup(input)
	if data == nil {
		b.WriteString("\n" + notFound(input))
		return b.String()
	}

	t := ui.NewTable("Field", "Value")
	// RenderLink builds `[@name](/u/name)` with no escaping of its own, which
	// is safe only because r/sys/users validates a name against
	// ^[a-z][a-z0-9]*([_-][a-z0-9]+)*$ before storing it: no pipe, no bracket,
	// nothing a table cell or a link would notice.
	t.Row("Username", data.RenderLink(""))
	t.Row("Address", ui.AddrFull(data.Addr()))
	if current := CurrentName(input); current != "" {
		// One ui.Cell over the whole sentence, not a code span per name: a
		// code span escapes for running prose and leaves the `|` that would
		// split the row, and wrapping an already-escaped string again is the
		// double-wrap sanitize refuses to be idempotent about.
		t.Row("Note", ui.Cell("You asked for "+trim(input)+
			", which is an earlier name. The current one is "+current+"."))
	}
	t.Row("Canonical", ui.Cell(users.Canonicalize(data.Name())))
	b.WriteString("\n" + t.String())

	if cmd := qevalCommand(input); cmd != "" {
		b.WriteString("\n" + md.LanguageCodeBlock("sh", cmd))
	}
	return b.String()
}

func notFound(input string) string {
	var b strings.Builder
	b.WriteString("Nothing registered under " + md.InlineCode(trim(input)) + ".\n")
	b.WriteString("\n" + md.BulletList(notFoundHints(input)))
	return b.String()
}

// notFoundHints says what "not found" means for this particular input, which
// is three different things.
func notFoundHints(input string) []string {
	trimmed := trim(input)
	if address(trimmed).IsValid() {
		return []string{
			"That is a valid address, so it exists on chain. It has no username.",
			"Register one at " + md.Link("r/gnoland/users", "/r/gnoland/users"),
		}
	}
	hints := []string{
		"Nobody holds it, or the account was deleted: a deleted name keeps its tombstone and resolves to nothing.",
	}
	if owner := CanonicalOwner(trimmed); owner != "" {
		hints = append(hints, "A lookalike is taken: "+md.InlineCode(owner)+
			" already holds the canonical key "+md.InlineCode(users.Canonicalize(trimmed))+".")
	} else if Taken(trimmed) {
		hints = append(hints, "The name IS taken, by an account that was deleted or renamed. Registering it would still fail.")
	}
	return hints
}

func form() string {
	return tb.NewQuery("lookup").Field("q", "username or g1 address").String()
}

// qevalCommand is the CLI call this page is the equivalent of, with the input
// substituted. It returns "" for an input that cannot be put inside a fenced
// code block safely: nothing escapes inside a fence, so the only safe move is
// not to print one.
func qevalCommand(input string) string {
	arg := trim(input)
	if !safeArg(arg) {
		return ""
	}
	return "gnokey query vm/qeval -remote https://rpc.gno.land \\\n" +
		"  -data 'gno.land/r/moul/toolbox/usernames.Resolve(\"" + arg + "\")'"
}

// safeArg reports whether s can be interpolated into a shell single-quoted
// string inside a markdown code fence. Usernames and addresses are both well
// inside this set, so a refusal only ever hides the hint, never an answer.
func safeArg(s string) bool {
	if s == "" || len(s) > maxInput {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z':
		case c >= 'A' && c <= 'Z':
		case c >= '0' && c <= '9':
		case c == '_' || c == '-' || c == '.':
		default:
			return false
		}
	}
	return true
}

// trim bounds an echoed input. Everything downstream escapes it; this only
// stops one query from rendering a page of arbitrary size.
//
// Cut on a rune boundary, not a byte one: s[:maxInput] on a multi-byte
// character leaves half of it, and half a rune is not a character the escapers
// downstream can do anything sensible with. Counting runes also makes the cap
// mean the same thing for every alphabet.
func trim(s string) string {
	n := 0
	for i := range s {
		if n == maxInput {
			return s[:i] + "…"
		}
		n++
	}
	return s
}

