// TestRenderEscapesInput: the query parameter is attacker-chosen and a live
// realm can never be fixed, so this is the test that must be seen to fail
// before it is believed.
//
// The property is that the echo is INERT, not that particular bytes are
// absent. A code span makes link syntax inert without removing it, so an
// assertion that the substring is gone would pass for the wrong reason under
// one escaper and fail for the wrong reason under the other.
func TestRenderEscapesInput(cur realm, t *testing.T) {
	seed(cur, t)

	const link = "[x](javascript:alert(1))"
	got := Render("lookup?q=" + "%5Bx%5D%28javascript%3Aalert%281%29%29")
	uassert.True(t, strings.Contains(got, "`"+link+"`"))
	uassert.False(t, strings.Contains(got, " "+link+" "))

	// A backtick in the input cannot close the span early: the fence widens.
	tick := Render("lookup?q=a%60b")
	uassert.True(t, strings.Contains(tick, "``"))
	uassert.False(t, strings.Contains(tick, "under `a`b`."))

	// A heading marker cannot open a block of its own: the echo stays on the
	// line it was put on.
	head := Render("lookup?q=%0A%23%20pwned")
	uassert.False(t, strings.Contains(head, "\n# pwned"))
}

// TestRenderOmitsTheCommandForUnsafeInput: nothing escapes inside a fenced
// code block, so an input that cannot go in one does not get one.
func TestRenderOmitsTheCommandForUnsafeInput(cur realm, t *testing.T) {
	seed(cur, t)

	uassert.True(t, strings.Contains(Render("moul"), "gnokey query vm/qeval"))
	uassert.False(t, strings.Contains(Render("lookup?q=a%60b"), "gnokey query vm/qeval"))
}

func TestRenderNeverEmitsTwoBlankLines(cur realm, t *testing.T) {
	seed(cur, t)

	for _, path := range []string{"", "moul", "nobodyholdsthis", moulAddr.String(), "a/b"} {
		uassert.False(t, strings.Contains(Render(path), "\n\n\n"))
	}
}

// Package usernames is the toolbox tool for gno.land identities: it turns a
// username into an address, an address into a username, and tells you which
// of the two you are actually holding.
//
// It is the page form of
//
//	gnokey query vm/qeval --data 'gno.land/r/sys/users.ResolveName("akkadia")' -remote https://rpc.gno.land
//
// with the three things that query does not tell you: whether the name you
// asked about is the user's CURRENT name or an alias they renamed away from,
// what canonical key it collapses to, and whether a lookalike of it is already
// taken.
//
// # Why not r/sys/users.ResolveAny
//
// `ResolveAny` returns `(*UserData, bool)` and the bool does not mean "found".
// For an input that parses as an address it returns `(ResolveAddress(addr),
// true)` whatever the lookup produced, so an unregistered address comes back
// as `(nil, true)`. Every caller that reads the bool and dereferences the
// pointer panics on the first address nobody claimed. [lookup] branches on the
// input itself and checks the pointer instead.
//
// Part of [r/moul/toolbox](/r/moul/toolbox).
package usernames

import "gno.land/r/sys/users"

// lookup resolves any input to a user record, or nil.
//
// An input that parses as a gno.land address is only ever looked up as an
// address, and anything else only as a name: a bech32 address is not a legal
// username, so trying both would only widen what a typo can hit.
func lookup(input string) *users.UserData {
	if input == "" {
		return nil
	}
	if addr := address(input); addr.IsValid() {
		return users.ResolveAddress(addr)
	}
	data, _ := users.ResolveName(input)
	return data
}

// Resolve returns the current username and the address behind any input, a
// username or a `g1` address.
//
// found is false when nobody holds it, which is also the answer for a deleted
// user: `r/sys/users` keeps the tombstone and resolves it to nothing.
//
//	gnokey query vm/qeval -data 'gno.land/r/moul/toolbox/usernames.Resolve("moul")'
func Resolve(input string) (name string, addr string, found bool) {
	data := lookup(input)
	if data == nil {
		return "", "", false
	}
	return data.Name(), data.Addr().String(), true
}

// AddressOf returns the address behind a username or an address, or "" when
// nobody holds it.
//
// It is the call another realm would want, and the one it cannot have: this
// realm is `private = true`, so nothing can import it. Over `vm/qeval` it is
// the whole point.
//
//	gnokey query vm/qeval -data 'gno.land/r/moul/toolbox/usernames.AddressOf("moul")'
func AddressOf(input string) string {
	_, addr, found := Resolve(input)
	if !found {
		return ""
	}
	return addr
}

// NameOf returns the current username behind a username or an address, or ""
// when nobody holds it.
func NameOf(input string) string {
	name, _, found := Resolve(input)
	if !found {
		return ""
	}
	return name
}

// Display returns what a page should print for an input: "@name" when there is
// a username, and the input unchanged when there is not.
//
// So it is total over every input a page actually has, and a caller never has
// to branch on "not found" the way [NameOf] makes it. The one input it has
// nothing to say about is "", which it returns unchanged: an empty answer to an
// empty question, rather than a placeholder a page would then have to special
// case anyway.
func Display(input string) string {
	if name := NameOf(input); name != "" {
		return "@" + name
	}
	return input
}

// CurrentName reports the user's current name when input is an alias they
// renamed away from, and "" otherwise.
//
// `r/sys/users` keeps old names resolving on purpose, so an address looked up
// by a name that is no longer current is not an error and nothing in the
// resolve result says so. This is the one call that does.
func CurrentName(input string) string {
	if input == "" {
		return ""
	}
	if addr := address(input); addr.IsValid() {
		return ""
	}
	data, isCurrent := users.ResolveName(input)
	if data == nil || isCurrent {
		return ""
	}
	return data.Name()
}

// Canonical returns the canonical key a name collapses to. Two names with the
// same canonical form cannot both be registered, which is how `r/sys/users`
// refuses a lookalike of an existing account.
//
//	gnokey query vm/qeval -data 'gno.land/r/moul/toolbox/usernames.Canonical("M0ul")'
func Canonical(name string) string { return users.Canonicalize(name) }

// Taken reports whether the exact name is registered, including names that
// were deleted or renamed away from: it answers "would registering this
// fail", not "is somebody using this".
func Taken(name string) bool {
	if name == "" {
		return false
	}
	return users.IsNameTaken(name)
}

// CanonicalOwner returns the name that already holds this name's canonical
// key, or "" when the key is free. A non-empty answer that is not the name
// itself is a lookalike collision.
func CanonicalOwner(name string) string {
	if name == "" {
		return ""
	}
	existing, taken := users.IsCanonicalTaken(name)
	if !taken {
		return ""
	}
	return existing
}

package usernames

import (
	"strings"
	"testing"
	"unicode/utf8"

	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
	"gno.land/r/sys/users"
)

const (
	moulAddr  = address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")
	plainAddr = address("g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5")
)

// controllerPath is the realm r/sys/users whitelists in its own init when the
// chain id is "dev", which is what `gno test` runs as. Registering a fixture
// means borrowing that identity: this package is not a controller and
// AddControllerAtGenesis cannot be reached from here, since its `_ realm`
// first parameter is the non-crossing threaded form and an external realm
// refuses a cur-call to one.
const controllerPath = "gno.land/r/sys/users/init"

// seed registers the fixtures every test in this file reads.
//
// The SetRealm is immediately followed by a crossing call, which is the only
// shape that works: in a helper that does not itself cross, the switch is
// silently dropped and the caller stays whoever it was.
func seed(cur realm, t *testing.T) {
	t.Helper()
	if users.IsNameTaken("moul") {
		return
	}
	testing.SetRealm(testing.NewCodeRealm(controllerPath))
	urequire.NoError(t, users.RegisterUser(cross(cur), "moul", moulAddr))
}

func TestResolveByName(cur realm, t *testing.T) {
	seed(cur, t)

	name, addr, found := Resolve("moul")
	uassert.True(t, found)
	uassert.Equal(t, "moul", name)
	uassert.Equal(t, moulAddr.String(), addr)
}

func TestResolveByAddress(cur realm, t *testing.T) {
	seed(cur, t)

	name, addr, found := Resolve(moulAddr.String())
	uassert.True(t, found)
	uassert.Equal(t, "moul", name)
	uassert.Equal(t, moulAddr.String(), addr)
}

func TestResolveMisses(cur realm, t *testing.T) {
	seed(cur, t)

	cases := []struct {
		name  string
		input string
	}{
		{"empty", ""},
		{"unknown name", "nobodyholdsthis"},
		{"valid address with no name", plainAddr.String()},
		{"not an address and not a name", "g1notanaddress"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, _, found := Resolve(tc.input)
			uassert.False(t, found)
		})
	}
}

// TestResolveAnyTrap is the defect this tool exists not to repeat: for an
// input that parses as an address, r/sys/users.ResolveAny reports true
// whatever the lookup produced, so the pointer it returns can be nil. Pinned
// against the vendored copy so a later upstream fix is visible here.
func TestResolveAnyTrap(cur realm, t *testing.T) {
	seed(cur, t)

	data, ok := users.ResolveAny(plainAddr.String())
	uassert.True(t, ok)
	uassert.True(t, data == nil)

	_, _, found := Resolve(plainAddr.String())
	uassert.False(t, found)
}

func TestAccessors(cur realm, t *testing.T) {
	seed(cur, t)

	uassert.Equal(t, moulAddr.String(), AddressOf("moul"))
	uassert.Equal(t, "moul", NameOf(moulAddr.String()))
	uassert.Equal(t, "@moul", Display("moul"))
	uassert.Equal(t, "@moul", Display(moulAddr.String()))

	uassert.Equal(t, "", AddressOf("nobodyholdsthis"))
	uassert.Equal(t, "", NameOf("nobodyholdsthis"))
	uassert.Equal(t, "nobodyholdsthis", Display("nobodyholdsthis"))
}

func TestCanonicalAndTaken(cur realm, t *testing.T) {
	seed(cur, t)

	uassert.Equal(t, users.Canonicalize("moul"), Canonical("moul"))
	uassert.True(t, Taken("moul"))
	uassert.False(t, Taken("nobodyholdsthis"))
	uassert.False(t, Taken(""))

	uassert.Equal(t, "moul", CanonicalOwner("moul"))
	uassert.Equal(t, "", CanonicalOwner("nobodyholdsthis"))
	uassert.Equal(t, "", CanonicalOwner(""))
}

// TestCurrentNameOnAlias: r/sys/users keeps an old name resolving after a
// rename and nothing in the resolve result says it is old. CurrentName is the
// only call that does.
func TestCurrentNameOnAlias(cur realm, t *testing.T) {
	seed(cur, t)

	const old = "aliasfixture"
	const now = "renamedfixture"

	if !users.IsNameTaken(old) {
		testing.SetRealm(testing.NewCodeRealm(controllerPath))
		urequire.NoError(t, users.RegisterUser(cross(cur), old, plainAddr))
	}

	data := users.ResolveAddress(plainAddr)
	urequire.True(t, data != nil)
	if data.Name() == old {
		testing.SetRealm(testing.NewCodeRealm(controllerPath))
		urequire.NoError(t, data.UpdateName(0, cur, now))
	}

	uassert.Equal(t, now, CurrentName(old))
	uassert.Equal(t, "", CurrentName(now))
	uassert.Equal(t, "", CurrentName(plainAddr.String()))
	uassert.Equal(t, "", CurrentName("nobodyholdsthis"))
	uassert.Equal(t, "", CurrentName(""))

	// The old name still resolves, to the current one.
	name, _, found := Resolve(old)
	uassert.True(t, found)
	uassert.Equal(t, now, name)
}

func TestSafeArg(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"username", "moul", true},
		{"address", "g1manfred47kzduec920z88wfr64ylksmdcedlf5", true},
		{"dashes and dots", "a-b.c_d", true},
		{"empty", "", false},
		{"quote", "a'b", false},
		{"backtick", "a`b", false},
		{"fence", "```", false},
		{"dollar", "$(id)", false},
		{"too long", strings.Repeat("a", maxInput+1), false},
		{"exactly max", strings.Repeat("a", maxInput), true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			uassert.Equal(t, tc.want, safeArg(tc.in))
		})
	}
}

func TestTrim(t *testing.T) {
	uassert.Equal(t, "moul", trim("moul"))
	long := strings.Repeat("a", maxInput+10)
	uassert.Equal(t, strings.Repeat("a", maxInput)+"…", trim(long))
}

// TestTrimCutsOnARuneBoundary: a byte cut at maxInput lands inside the
// multi-byte character here and leaves half of it, which no escaper
// downstream can do anything sensible with.
func TestTrimCutsOnARuneBoundary(t *testing.T) {
	in := strings.Repeat("a", maxInput-1) + "é" + "tail"
	got := trim(in)
	uassert.Equal(t, strings.Repeat("a", maxInput-1)+"é"+"…", got)
	uassert.True(t, utf8.ValidString(got))

	// And the cap counts characters, not bytes, so an all-multibyte input
	// keeps maxInput of them rather than half as many.
	accents := strings.Repeat("é", maxInput+5)
	uassert.Equal(t, strings.Repeat("é", maxInput)+"…", trim(accents))
}

// TestDisplayOnEmpty pins the one input Display has nothing to say about.
func TestDisplayOnEmpty(t *testing.T) {
	uassert.Equal(t, "", Display(""))
}

// Package eightball is a Magic 8-Ball realm: ask a yes/no question and the
// block height decides your fate. Deterministic (no real randomness on-chain).
package eightball

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
)

// The 20 classic Magic 8-Ball answers.
var answers = []string{
	"It is certain.", "It is decidedly so.", "Without a doubt.",
	"Yes definitely.", "You may rely on it.", "As I see it, yes.",
	"Most likely.", "Outlook good.", "Yes.", "Signs point to yes.",
	"Reply hazy, try again.", "Ask again later.", "Better not tell you now.",
	"Cannot predict now.", "Concentrate and ask again.",
	"Don't count on it.", "My reply is no.", "My sources say no.",
	"Outlook not so good.", "Very doubtful.",
}

type shake struct {
	asker    string
	question string
	answer   string
	height   int64
}

var history []shake

// answerIndex maps (block height, prior shakes) to an answer slot. Pure and
// deterministic so it can be tested without touching realm state.
func answerIndex(height int64, n int) int {
	i := (height + int64(n)) % int64(len(answers))
	if i < 0 {
		i += int64(len(answers))
	}
	return int(i)
}

// Ask poses a question to the Magic 8-Ball and returns its answer. Crossing
// function: it mutates persistent state, so it takes `cur realm` (gno 0.9).
func Ask(cur realm, question string) string {
	question = strings.TrimSpace(question)
	if question == "" {
		panic("question must not be empty")
	}
	if len(question) > 200 {
		panic("question too long (max 200 chars)")
	}
	h := runtime.ChainHeight()
	ans := answers[answerIndex(h, len(history))]
	history = append(history, shake{
		asker:    unsafe.PreviousRealm().Address().String(),
		question: question,
		answer:   ans,
		height:   h,
	})
	chain.Emit("Shaken", "answer", ans, "height", strconv.FormatInt(h, 10))
	return ans
}

// Asked returns how many questions have been asked. Read-only.
func Asked() int { return len(history) }

// Render is the gnoweb Markdown view.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# 🎱 Magic 8-Ball\n\n")
	b.WriteString("> ⚠️ Experimental, auto-generated with no human supervision (MCP test corpus). ")
	b.WriteString("Not audited. See [r/moul/x/daily](https://github.com/moul/gno-contracts/blob/main/r/moul/x/daily/README.md).\n\n")
	b.WriteString("Ask a yes/no question — the block height decides your fate.\n\n")
	b.WriteString("**Questions asked:** ")
	b.WriteString(strconv.Itoa(len(history)))
	b.WriteString("\n\n")

	if len(history) == 0 {
		b.WriteString("_No questions yet. Call `Ask(\"will it rain tomorrow?\")`._\n")
		return b.String()
	}

	last := history[len(history)-1]
	b.WriteString("Last shake: 🎱 _")
	b.WriteString(last.answer)
	b.WriteString("_\n\n| # | asker | question | answer | height |\n")
	b.WriteString("|---|---|---|---|---|\n")

	start := len(history) - 1
	end := start - 14
	if end < 0 {
		end = 0
	}
	for i := start; i >= end; i-- {
		e := history[i]
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(i + 1))
		b.WriteString(" | ")
		b.WriteString(ui.AddrOf(e.asker))
		b.WriteString(" | ")
		b.WriteString(e.question)
		b.WriteString(" | ")
		b.WriteString(e.answer)
		b.WriteString(" | ")
		b.WriteString(strconv.FormatInt(e.height, 10))
		b.WriteString(" |\n")
	}
	return b.String()
}

