package escrow

import (
	"chain"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/nt/avl/v0"
)

// State constants for a deal's lifecycle.
const (
	StateOpen     = "Open"
	StateSettled  = "Settled"
	StateCanceled = "Canceled"
)

// Deal is a 2-party escrow record. Accounting only: no funds move,
// this tracks agreement and mutual confirmation between two parties.
type Deal struct {
	ID           int
	Creator      address
	Counterparty address
	Terms        string
	State        string
	CreatorOK    bool
	CounterOK    bool
}

var (
	deals  = avl.NewTree() // id (string) -> *Deal
	nextID int
)

var (
	errNotFound   = errors.New("escrow: deal not found")
	errNotParty   = errors.New("escrow: caller is not a party to this deal")
	errNotOpen    = errors.New("escrow: deal is not open")
	errNotCreator = errors.New("escrow: only the creator can cancel")
	errBadAddr    = errors.New("escrow: invalid counterparty address")
	errSelfDeal   = errors.New("escrow: counterparty must differ from creator")
)

// Create opens a new escrow deal between the caller (creator) and the
// given counterparty, governed by a free-form terms string. Returns the
// new deal id. Panics on invalid input (cross-realm abort).
func Create(cur realm, counterparty address, terms string) int {
	if !cur.IsCurrent() {
		panic("escrow: spoofed realm")
	}
	if !counterparty.IsValid() {
		panic(errBadAddr)
	}
	creator := cur.Previous().Address()
	if counterparty == creator {
		panic(errSelfDeal)
	}

	id := nextID
	nextID++

	d := &Deal{
		ID:           id,
		Creator:      creator,
		Counterparty: counterparty,
		Terms:        terms,
		State:        StateOpen,
	}
	deals.Set(strconv.Itoa(id), d)

	chain.Emit("Created", "id", strconv.Itoa(id),
		"creator", creator.String(), "counterparty", counterparty.String())
	return id
}

// Confirm records confirmation by whichever party is calling. Once both
// parties have confirmed, the deal transitions to Settled.
func Confirm(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("escrow: spoofed realm")
	}
	d := mustGet(id)
	if d.State != StateOpen {
		panic(errNotOpen)
	}
	caller := cur.Previous().Address()

	switch caller {
	case d.Creator:
		d.CreatorOK = true
	case d.Counterparty:
		d.CounterOK = true
	default:
		panic(errNotParty)
	}

	chain.Emit("Confirmed", "id", strconv.Itoa(id), "party", caller.String())

	if d.CreatorOK && d.CounterOK {
		d.State = StateSettled
		chain.Emit("Settled", "id", strconv.Itoa(id))
	}
}

// Cancel voids an open deal. Only the creator may cancel, and only
// before the deal has settled.
func Cancel(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("escrow: spoofed realm")
	}
	d := mustGet(id)
	if d.State != StateOpen {
		panic(errNotOpen)
	}
	caller := cur.Previous().Address()
	if caller != d.Creator {
		panic(errNotCreator)
	}
	d.State = StateCanceled
	chain.Emit("Canceled", "id", strconv.Itoa(id))
}

func mustGet(id int) *Deal {
	v := deals.Get(strconv.Itoa(id))
	if v == nil {
		panic(errNotFound)
	}
	return v.(*Deal)
}

// Render lists all escrow deals with their parties, terms, and state.
// When path is a numeric id, renders just that deal.
func Render(path string) string {
	path = strings.TrimSpace(strings.Trim(path, "/"))
	if path != "" {
		if id, err := strconv.Atoi(path); err == nil {
			v := deals.Get(strconv.Itoa(id))
			if v == nil {
				return "# Escrow\n\nDeal " + md.InlineCode(path) + " not found.\n"
			}
			return renderOne(v.(*Deal))
		}
	}

	var b strings.Builder
	b.WriteString("# Escrow\n\n")
	b.WriteString("2-party escrow deals (accounting only — no funds move).\n\n")

	if deals.Size() == 0 {
		b.WriteString("_No deals yet._\n")
		return b.String()
	}

	b.WriteString("| ID | Creator | Counterparty | State | Confirmations | Terms |\n")
	b.WriteString("|----|---------|--------------|-------|---------------|-------|\n")
	deals.Iterate("", "", func(_ string, v interface{}) bool {
		d := v.(*Deal)
		b.WriteString("| " + strconv.Itoa(d.ID) +
			" | " + ui.Addr(d.Creator) +
			" | " + ui.Addr(d.Counterparty) +
			" | " + d.State +
			" | " + confs(d) +
			" | " + ui.Cell(d.Terms) + " |\n")
		return false
	})
	return b.String()
}

func renderOne(d *Deal) string {
	var b strings.Builder
	b.WriteString("# Escrow Deal #" + strconv.Itoa(d.ID) + "\n\n")
	b.WriteString("- **State:** " + d.State + "\n")
	b.WriteString("- **Creator:** " + d.Creator.String() + " (" + yn(d.CreatorOK) + ")\n")
	b.WriteString("- **Counterparty:** " + d.Counterparty.String() + " (" + yn(d.CounterOK) + ")\n")
	b.WriteString("- **Terms:** " + ui.Inline(d.Terms) + "\n")
	return b.String()
}

func confs(d *Deal) string {
	n := 0
	if d.CreatorOK {
		n++
	}
	if d.CounterOK {
		n++
	}
	return strconv.Itoa(n) + "/2"
}

func yn(b bool) string {
	if b {
		return "confirmed"
	}
	return "pending"
}

package escrow

import (
	"strconv"
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
)

func resetState() {
	deals = avl.NewTree()
	nextID = 0
}

func TestCreateAndConfirmSettles(cur realm, t *testing.T) {
	resetState()

	// Alice creates a deal with Bob.
	testing.SetRealm(testing.NewUserRealm(alice))
	id := Create(cross(cur), bob, "swap NFT for 100 GNOT")
	uassert.Equal(t, 0, id)

	// Alice confirms (1/2, still open).
	Confirm(cross(cur), id)
	out := Render("0")
	uassert.True(t, strings.Contains(out, "State:** Open"), "expected still open after one confirm")

	// Bob confirms -> settles.
	testing.SetRealm(testing.NewUserRealm(bob))
	Confirm(cross(cur), id)

	out = Render("0")
	uassert.True(t, strings.Contains(out, "Settled"), "expected Settled state")
	uassert.True(t, strings.Contains(out, "swap NFT for 100 GNOT"), "expected terms")
}

func TestCancelByCreator(cur realm, t *testing.T) {
	resetState()

	testing.SetRealm(testing.NewUserRealm(alice))
	id := Create(cross(cur), bob, "rent payment")

	Cancel(cross(cur), id)

	out := Render("")
	uassert.True(t, strings.Contains(out, "Canceled"), "expected Canceled state")
}

func TestNonPartyCannotConfirm(cur realm, t *testing.T) {
	resetState()

	testing.SetRealm(testing.NewUserRealm(alice))
	id := Create(cross(cur), bob, "consulting")

	// Carol is not a party.
	testing.SetRealm(testing.NewUserRealm(carol))
	uassert.AbortsWithMessage(t, cur, "escrow: caller is not a party to this deal", func() {
		Confirm(cross(cur), id)
	})
}

func TestOnlyCreatorCancels(cur realm, t *testing.T) {
	resetState()

	testing.SetRealm(testing.NewUserRealm(alice))
	id := Create(cross(cur), bob, "loan")

	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "escrow: only the creator can cancel", func() {
		Cancel(cross(cur), id)
	})
}

// The list view escaped Terms and the deal page did not, so a caller's terms
// rendered as live markdown on the realm's own page.
func TestDealPageEscapesTerms(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))
	id := Create(cross(cur), bob, "[claim](https://evil.example)")
	out := Render(strconv.Itoa(id))
	uassert.False(t, strings.Contains(out, "[claim](https://evil.example)"), out)
}

// Package fenwickdemo is a small gnoweb demo of the Binary Indexed Tree
// provided by the [p/moul/x/daily/fenwick](/p/moul/x/daily/fenwick/v0)
// library: prefix sums, range queries, the internal ranges that make the
// structure legible, and the weighted draw that is the reason to use one.
//
// It contains no tree logic of its own. Stateless, so Render is deterministic:
// every figure below is computed from the fixed tables at the top of this file,
// never from chain state, which is what lets an example test pin the page.
package fenwickdemo

import (
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/fenwick/v0"
)

// scores is the worked example: eight slots, small enough to check by hand.
var scores = []int64{3, 1, 4, 1, 5, 9, 2, 6}

// stakes is the weighted-draw example. The zero is the interesting entry: a
// holder with no stake must never be drawn, and that is a property of the
// search, not of the caller remembering to skip them.
var (
	holders = []string{"alice", "bob", "carol", "dave", "erin"}
	stakes  = []int64{30, 0, 45, 5, 20}
)

// Render renders the demo for gnoweb.
//
//	Render("") / Render("/") -> the full demo
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Fenwick tree\n\n")
	b.WriteString("A Binary Indexed Tree: prefix sums and point updates both in ")
	b.WriteString("`O(log n)`, demoing the ")
	b.WriteString("[`p/moul/x/daily/fenwick`](/p/moul/x/daily/fenwick/v0) library.\n\n")

	tr := fenwick.FromSlice(scores)

	b.WriteString("## The values\n\n")
	b.WriteString("`" + joinInts(scores) + "` — " + strconv.Itoa(tr.Len()))
	b.WriteString(" slots totalling `" + strconv.FormatInt(tr.Total(), 10) + "`.\n\n")

	b.WriteString("## Prefix sums\n\n")
	pt := ui.NewTable("i", "value", "Prefix(i+1)")
	for i := 0; i < tr.Len(); i++ {
		pt.Row(strconv.Itoa(i),
			strconv.FormatInt(tr.At(i), 10),
			strconv.FormatInt(tr.Prefix(i+1), 10))
	}
	b.WriteString(pt.String() + "\n")

	b.WriteString("## Range queries\n\n")
	rt := ui.NewTable("call", "meaning", "result")
	rt.Row("`Range(2, 5)`", "slots 2, 3, 4", strconv.FormatInt(tr.Range(2, 5), 10))
	rt.Row("`Range(0, 8)`", "everything", strconv.FormatInt(tr.Range(0, 8), 10))
	rt.Row("`Range(5, 5)`", "empty", strconv.FormatInt(tr.Range(5, 5), 10))
	rt.Row("`Range(-9, 99)`", "clamped to the ends", strconv.FormatInt(tr.Range(-9, 99), 10))
	b.WriteString(rt.String() + "\n")
	b.WriteString("Reads clamp instead of panicking. A realm cannot be redeployed on ")
	b.WriteString("the same path, so a `Render` that panics on an out-of-range index ")
	b.WriteString("is a page that is broken for good. Writes do panic: a bad `Add` is ")
	b.WriteString("a transaction, and aborting it is the useful answer.\n\n")

	b.WriteString("## What the tree actually stores\n\n")
	b.WriteString("The array is not a copy of the values. Each internal slot holds the ")
	b.WriteString("sum of a run of them, and the run lengths are the powers of two in ")
	b.WriteString("the index. That is the whole trick, and `Covers` makes it visible.\n\n")
	ct := ui.NewTable("node", "covers slots", "sum")
	for i := 1; i <= tr.Len(); i++ {
		lo, hi := tr.Covers(i)
		ct.Row(strconv.Itoa(i),
			"`["+strconv.Itoa(lo)+", "+strconv.Itoa(hi)+")`",
			strconv.FormatInt(tr.Range(lo, hi), 10))
	}
	b.WriteString(ct.String() + "\n")
	b.WriteString("A prefix walk visits one node per set bit of the index, and those ")
	b.WriteString("nodes tile the prefix exactly: no gap, no overlap. Eight slots ")
	b.WriteString("means at most three nodes per query.\n\n")

	b.WriteString("## The weighted draw\n\n")
	b.WriteString("`SearchPrefix(target)` names the slot that owns a target drawn ")
	b.WriteString("below `Total`, in `O(log n)`. Each holder is picked in proportion ")
	b.WriteString("to their stake, and a zero stake can never be picked at all.\n\n")
	st := fenwick.FromSlice(stakes)
	wt := ui.NewTable("holder", "stake", "owns targets", "share")
	for i, h := range holders {
		lo := st.Prefix(i)
		hi := st.Prefix(i + 1)
		owns := "none"
		if hi > lo {
			owns = "`[" + strconv.FormatInt(lo, 10) + ", " + strconv.FormatInt(hi, 10) + ")`"
		}
		wt.Row(ui.Cell(h),
			strconv.FormatInt(stakes[i], 10),
			owns,
			pct(stakes[i], st.Total()))
	}
	b.WriteString(wt.String() + "\n")

	dt := ui.NewTable("target", "SearchPrefix", "holder")
	for _, target := range []int64{0, 29, 30, 74, 99} {
		i := st.SearchPrefix(target)
		dt.Row(strconv.FormatInt(target, 10), strconv.Itoa(i), ui.Cell(holders[i]))
	}
	b.WriteString(dt.String() + "\n")
	b.WriteString("Note target `30`: it is the first one past alice's share, and it ")
	b.WriteString("skips bob entirely rather than landing on a holder with nothing ")
	b.WriteString("staked. The search steps over zero-weight slots because their ")
	b.WriteString("prefix does not advance, not because anything checks for them.\n\n")

	b.WriteString("## Why not a plain slice\n\n")
	b.WriteString("Two obvious implementations each win one column and lose another. ")
	b.WriteString("A realm whose scoreboard is written by every player and read by ")
	b.WriteString("every page view pays both costs, which is where the middle row ")
	b.WriteString("earns its keep.\n\n")
	xt := ui.NewTable("structure", "point update", "prefix sum", "weighted draw")
	xt.Row("plain slice", "`O(1)`", "`O(n)`", "`O(n)`")
	xt.Row("**Fenwick tree**", "`O(log n)`", "`O(log n)`", "`O(log n)`")
	xt.Row("running totals", "`O(n)`", "`O(1)`", "`O(log n)`")
	b.WriteString(xt.String() + "\n")
	b.WriteString("The tree also carries no storage overhead: it is exactly `n` ")
	b.WriteString("values, rearranged.\n")

	return b.String()
}

// joinInts formats a slice for display. Written out rather than reached for
// from a library because there is no sensible shared home for it yet.
func joinInts(vals []int64) string {
	parts := make([]string, len(vals))
	for i, v := range vals {
		parts[i] = strconv.FormatInt(v, 10)
	}
	return strings.Join(parts, ", ")
}

// pct renders part/whole as a whole-number percentage.
//
// Integer arithmetic throughout: Render output has to be byte-identical on
// every validating node, and floating point is the usual way that stops being
// true.
func pct(part, whole int64) string {
	if whole == 0 {
		return "0%"
	}
	return strconv.FormatInt(part*100/whole, 10) + "%"
}

