}

// Package lastwords is one string, on chain, forever.
//
// There is a single message slot. Pay more than the last writer paid and the
// slot is yours; when the clock finally runs out, whatever is in it stays there
// permanently. The artefact at the end is the point, so the game is a bidding
// war over an epitaph rather than over a prize.
//
// The three rules exist because the obvious version of this game does not end
// and does not pay:
//
//  1. THE CLOCK TERMINATES. Every write pushes the deadline a fifth of the way
//     to a hard end fixed when the slot opened, and no write can push it past
//     that. A constant extension per action has no end: the pot grows faster
//     than the price of the next write, so there is always a rational next
//     write and the game runs until everyone is bored or broke.
//  2. THE LAST WRITER DOES NOT TAKE THE POT. They take the slot, which is what
//     they were bidding for. The pot is split among everyone ELSE who wrote,
//     pro rata to what they paid. Winner-takes-all makes the second-to-last
//     writer the mark and everyone knows it, which is why nobody joins.
//  3. HALF OF EVERY PAYMENT GOES TO THE WRITER BEING DISPLACED, immediately.
//     A zero-sum game minus gas has no reason for a second player. Overwriting
//     somebody pays them, so being overwritten early is not a loss.
//
// Nothing is ever pushed: payouts are credited to an internal ledger and swept
// by Withdraw. A realm that pays inside a loop over its roster is a gas bomb
// that eventually bricks, and the bigger the game gets the more certain that
// is.
//
// The pieces are libraries, and the realm is the wiring:
// [p/moul/x/games/clock](/p/moul/x/games/clock/v0) owns the deadline and its
// guards, [p/moul/x/games/prorata](/p/moul/x/games/prorata/v0) owns the split,
// and [p/moul/x/daily/pullpayment](/p/moul/x/daily/pullpayment/v0) owns the
// credit ledger.
package lastwords

import (
	"strconv"
	"strings"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/pullpayment/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/games/clock/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/games/prorata/v0"
	"gno.land/p/nt/avl/v0"
)

const denom = "ugnot"

// The rules, fixed at deploy. Times are block heights.
const (
	// Window is how long the slot stays open with nobody writing.
	Window = int64(2000)
	// Floor is the minimum a write leaves on the clock, so the last stretch
	// stays long enough for a transaction to land in. Without it a decaying
	// extension shrinks to nothing and whoever holds at that moment wins by
	// being unreachable rather than by paying.
	Floor = int64(300)
	// Life is the hard end. No write can push the deadline past start+Life.
	Life = int64(100000)
	// BumpPct is how much of the gap to the hard end a write buys.
	BumpPct = int64(20)
	// DividendPct is the share of a payment credited to the writer being
	// displaced; the rest goes to the pot.
	DividendPct = int64(50)

	// MinWrite is the base price of the slot, in ugnot.
	MinWrite = int64(1000000)
	// PerByte is charged on top, in ugnot per byte of the message. The chain's
	// own storage deposit is 100 ugnot per byte, so this is that plus a premium
	// for occupying the only slot there is.
	PerByte = int64(1000)
	// MaxLen caps the message in bytes, because the message IS the storage
	// cost and an uncapped one is an unbounded write priced at a constant.
	MaxLen = 280
)

var (
	clk     *clock.Clock
	ledger  = pullpayment.New()
	message string
	author  address
	paid    int64    // what the current holder paid
	pot     int64    // what settlement will split
	writers avl.Tree // address string -> int64 total paid
	order   []string // writers in first-write order, so the split is deterministic
	writes  int64
	settled bool
)

func init() {
	open(runtime.ChainHeight())
}

// open resets the game to a fresh slot at height h. It is the only place the
// clock is built, so tests and init cannot disagree about the rules.
func open(h int64) {
	c, err := clock.New(h, Window, Floor, Life)
	if err != nil {
		panic("lastwords: " + err.Error())
	}
	clk = c
	ledger = pullpayment.New()
	message = ""
	author = ""
	paid = 0
	pot = 0
	writers = avl.Tree{}
	order = nil
	writes = 0
	settled = false
}

// Price returns what msg costs to write right now, in ugnot: a base, plus a
// charge per byte, and always at least one ugnot more than the current holder
// paid. Query it before sending; an underpaying write is refused, not refunded.
func Price(msg string) int64 {
	price := MinWrite + int64(len(msg))*PerByte
	if next := paid + 1; next > price {
		price = next
	}
	return price
}

// Write puts msg in the slot and makes the caller its holder. The caller must
// send at least Price(msg) ugnot with the transaction.
//
// Half of the payment is credited to the writer being displaced and the rest
// joins the pot. The deadline is pushed a fifth of the way toward the hard end,
// never past it, and never to less than Floor from now.
//
// Only a direct user transaction may write, so the payment envelope cannot be
// spoofed by an ephemeral MsgRun realm.
func Write(cur realm, msg string) {
	if !cur.Previous().IsUserCall() {
		panic("lastwords: write must be a direct user transaction")
	}
	h := runtime.ChainHeight()
	if clk.Expired(h) {
		panic("lastwords: the slot is closed, these are somebody's last words now")
	}
	if msg == "" {
		panic("lastwords: message must not be empty")
	}
	if len(msg) > MaxLen {
		panic("lastwords: message must be at most " + strconv.Itoa(MaxLen) + " bytes")
	}
	if strings.ContainsAny(msg, "\n\r") {
		panic("lastwords: message must be a single line")
	}

	price := Price(msg)
	sent := unsafe.OriginSend().AmountOf(denom)
	if sent < price {
		panic("lastwords: sent " + strconv.FormatInt(sent, 10) +
			" ugnot, price is " + strconv.FormatInt(price, 10))
	}

	caller := cur.Previous().Address()

	// The displaced writer is paid first, out of the payment that displaced
	// them. Credited, never sent: see the package doc.
	dividend := int64(0)
	if author != "" {
		dividend = sent * DividendPct / 100
		if err := ledger.Credit(author.String(), dividend); err != nil {
			panic("lastwords: " + err.Error())
		}
	}
	pot += sent - dividend

	key := caller.String()
	if _, seen := writers.Get(key).(int64); !seen {
		order = append(order, key)
	}
	writers.Set(key, totalPaid(key)+sent)

	message = msg
	author = caller
	paid = sent
	writes++

	deadline, err := clk.BumpShare(h, BumpPct)
	if err != nil {
		panic("lastwords: " + err.Error())
	}

	chain.Emit("Write",
		"author", key,
		"paid", strconv.FormatInt(sent, 10),
		"dividend", strconv.FormatInt(dividend, 10),
		"deadline", strconv.FormatInt(deadline, 10),
	)
}

// Settle closes the game once the clock has run out, splitting the pot among
// every writer EXCEPT the one holding the slot, pro rata to what each paid.
//
// Anyone may call it: leaving settlement to an interested party is how a pot
// stays unclaimed. It moves no coins, it credits the ledger; Withdraw is what
// pays. If the holder is the only writer there is nobody else to split with,
// so the pot returns to them.
func Settle(cur realm) {
	h := runtime.ChainHeight()
	if !clk.Expired(h) {
		panic("lastwords: still open until height " + strconv.FormatInt(clk.Deadline(), 10))
	}
	if settled {
		panic("lastwords: already settled")
	}
	settled = true
	if pot == 0 {
		return
	}

	holder := author.String()
	payees := []string{}
	weights := []int64{}
	for _, k := range order {
		if k == holder {
			continue
		}
		payees = append(payees, k)
		weights = append(weights, totalPaid(k))
	}
	if len(payees) == 0 {
		// The holder wrote every word there is. Nobody to share with.
		payees = []string{holder}
		weights = []int64{1}
	}

	shares, err := prorata.Split(pot, weights)
	if err != nil {
		panic("lastwords: " + err.Error())
	}

	// A zero share is dropped: CreditMany refuses a non-positive amount, and
	// crediting nothing is not a payment anyway.
	dst := []string{}
	amounts := []int64{}
	for i, s := range shares {
		if s > 0 {
			dst = append(dst, payees[i])
			amounts = append(amounts, s)
		}
	}
	if len(dst) > 0 {
		if err := ledger.CreditMany(dst, amounts); err != nil {
			panic("lastwords: " + err.Error())
		}
	}
	pot = 0

	chain.Emit("Settle",
		"holder", holder,
		"writes", strconv.FormatInt(writes, 10),
		"payees", strconv.Itoa(len(dst)),
	)
}

// Withdraw pays the caller everything credited to them and returns the amount.
// Dividends are claimable while the game runs; settlement shares only after
// Settle.
func Withdraw(cur realm) int64 {
	caller := cur.Previous().Address()
	amount, err := ledger.Withdraw(caller.String())
	if err != nil {
		panic("lastwords: " + err.Error())
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amount)))

	chain.Emit("Withdraw", "payee", caller.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Message returns the slot's current contents, raw. Render is what escapes it.
func Message() string { return message }

// Author returns who holds the slot.
func Author() address { return author }

// Pot returns what settlement will split.
func Pot() int64 { return pot }

// Deadline returns the height the slot closes at.
func Deadline() int64 { return clk.Deadline() }

// Owed returns what an address can Withdraw right now.
func Owed(addr address) int64 { return ledger.Balance(addr.String()) }

// totalPaid returns what an address has paid in total, zero if it never wrote.
func totalPaid(key string) int64 {
	v, ok := writers.Get(key).(int64)
	if !ok {
		return 0
	}
	return v
}

func gnot(ugnot int64) string {
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	s := strconv.FormatInt(whole, 10)
	if frac == 0 {
		return s
	}
	f := strconv.FormatInt(frac, 10)
	for len(f) < 6 {
		f = "0" + f
	}
	for len(f) > 1 && f[len(f)-1] == '0' {
		f = f[:len(f)-1]
	}
	return s + "." + f
}

package lastwords

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
)

// Render shows the slot, the clock and the money. The message is caller-typed
// text, so it goes through ui.Inline: a stored string that renders as markdown
// is a phishing link on a page nobody can edit, and this realm's whole product
// is a string somebody else wrote.
func Render(path string) string {
	h := runtime.ChainHeight()
	var b strings.Builder

	b.WriteString("# Last Words\n\n")

	if message == "" {
		b.WriteString("_The slot is empty. Whoever writes last, writes forever._\n\n")
	} else {
		b.WriteString("> " + ui.Inline(message) + "\n\n")
		b.WriteString("by " + ui.AddrOf(author.String()) + ", for " + gnot(paid) + " GNOT\n\n")
	}

	closed := clk.Expired(h)
	b.WriteString("## The clock\n\n")
	if closed {
		b.WriteString("**Closed** at height " + strconv.FormatInt(clk.Deadline(), 10) + ". ")
		if settled {
			b.WriteString("Settled: the pot has been credited, call `Withdraw` to sweep yours.\n\n")
		} else {
			b.WriteString("Anyone may call `Settle` to split the pot.\n\n")
		}
	} else {
		b.WriteString("Open for another **" + strconv.FormatInt(clk.Remaining(h), 10) +
			"** blocks, until height " + strconv.FormatInt(clk.Deadline(), 10) + ".\n\n")
		if clk.Final() {
			b.WriteString("This is the **last stretch**: the deadline has reached the hard end at " +
				strconv.FormatInt(clk.HardEnd(), 10) + " and no write can move it again.\n\n")
		} else {
			b.WriteString("Hard end at height " + strconv.FormatInt(clk.HardEnd(), 10) +
				". A write buys " + strconv.FormatInt(BumpPct, 10) +
				"% of the gap to it, never less than " + strconv.FormatInt(Floor, 10) + " blocks.\n\n")
		}
	}

	b.WriteString("## The money\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Pot | " + gnot(pot) + " GNOT |\n")
	b.WriteString("| Price of the next write | " + gnot(Price("")) + " GNOT, plus " +
		strconv.FormatInt(PerByte, 10) + " ugnot per byte |\n")
	b.WriteString("| Writes | " + strconv.FormatInt(writes, 10) + " |\n")
	b.WriteString("| Writers | " + strconv.Itoa(len(order)) + " |\n")
	b.WriteString("| Owed, unswept | " + gnot(ledger.TotalOwed()) + " GNOT |\n\n")

	b.WriteString("The holder does **not** take the pot. It goes to everyone else who wrote, ")
	b.WriteString("pro rata to what they paid. Half of every payment is credited to the writer ")
	b.WriteString("it displaced, immediately.\n\n")

	if !ledger.IsEmpty() {
		b.WriteString("## Owed\n\n| address | ugnot |\n|---|---|\n")
		shown := 0
		ledger.Iterate(func(payee string, amount int64) bool {
			b.WriteString("| " + ui.AddrOf(payee) + " | " + strconv.FormatInt(amount, 10) + " |\n")
			shown++
			return shown >= 20
		})
		b.WriteString("\nCall `Withdraw` to sweep yours.\n")
	}

	return b.String()
}

// Package gsdash renders one address's whole GnoSwap footprint on chain, with
// no indexer and no off-chain query: balances, liquidity positions, what each
// one is worth right now, and what it has earned but not collected.
//
// It reads GnoSwap through the unversioned proxy paths (r/gnoswap/position and
// friends) rather than their /vN implementations, so a GnoSwap implementation
// upgrade does not reach this realm.
package gsdash

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/gnft"
	"gno.land/r/gnoswap/gns"
	"gno.land/r/gnoswap/gov/xgns"
	"gno.land/r/gnoswap/position"
	"gno.land/r/gnoswap/staker"
)

// scanWindow is how many stored position records one page walks.
//
// There is no address-to-positions index anywhere in GnoSwap: gnft is a plain
// grc721 with no enumerable extension, so the only way to find an address's
// positions is to walk the records and ask each one who owns it. GnoSwap's own
// position realm renders a keyed lookup and says out loud that it "does not
// enumerate positions", which is the same ceiling talking. Queries get
// 3,000,000,000 gas (maxGasQuery, gno.land/pkg/sdk/vm/keeper.go), so the walk
// is paged rather than unbounded, and the page footer links the next one.
const scanWindow = 250

// stakerPath is the realm that custodies a staked position's NFT. Staking
// transfers the token to it, so for anything staked the grc721 owner is this
// address and not a person: see resolveOwner.
const stakerPath = "gno.land/r/gnoswap/staker"

// Render serves three routes: the index, an address page, and the next page of
// an address whose records did not fit in one scan window.
//
//	""                  the index
//	"g1..."             that address, scanning from record 0
//	"g1.../from/500"    the same, scanning from record 500
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}

	addrPart, offset, ok := parsePath(path)
	if !ok {
		return ui.Empty("Not a route. Try `" + shortSelf + ":g1...`.")
	}
	addr := address(addrPart)
	if !addr.IsValid() {
		// Escaped rather than echoed: the path is whatever the reader typed.
		return ui.Empty("Not a valid address: " + ui.Inline(addrPart))
	}
	return renderAddress(addr, offset)
}

// shortSelf is this realm's own render prefix, used in the links it prints.
const shortSelf = "/r/moul/x/gsdash/v0"

func renderIndex() string {
	s := "# GnoSwap dashboard\n\n"
	s += "Everything one address has on GnoSwap, read live from the chain: GNS and xGNS " +
		"balances, every liquidity position with what it holds right now, the fees it has " +
		"accrued, and the emission rewards waiting to be collected.\n\n"
	s += ufmt.Sprintf("Open an address: `%s:g1...`\n\n", shortSelf)

	t := ui.NewTable("What", "Now")
	t.Row("Stored position records", ufmt.Sprintf("%d", position.GetPositions().Size()))
	t.Row("Position NFTs in circulation", ufmt.Sprintf("%d", gnft.TotalSupply()))
	t.Row("Records walked per page", ufmt.Sprintf("%d", scanWindow))
	s += t.String()

	s += "\nRecords include burned positions, so the count is not a count of live liquidity.\n"
	return s
}

func renderAddress(addr address, offset int) string {
	s := ufmt.Sprintf("# %s\n\n", ui.AddrFull(addr))

	nfts, err := gnft.BalanceOf(addr)
	if err != nil {
		nfts = 0
	}
	t := ui.NewTable("GNS", "xGNS", "Position NFTs held")
	t.Row(
		ufmt.Sprintf("%d", gns.BalanceOf(addr)),
		ufmt.Sprintf("%d", xgns.BalanceOf(addr)),
		ufmt.Sprintf("%d", nfts),
	)
	s += t.String() + "\n"

	// The offset comes from the path, so it reaches maxInt for free, and
	// offset+scanWindow would wrap negative. Clamp it to what exists first.
	size := position.GetPositions().Size()
	if offset > size {
		offset = size
	}
	end := offset + scanWindow
	if end > size {
		end = size
	}
	s += ufmt.Sprintf("## Positions\n\nRecords %d to %d of %d.\n\n", offset, end, size)
	s += renderPositions(addr, offset)

	if next := offset + scanWindow; next < size {
		s += ufmt.Sprintf("\n[Next %d records](%s:%s/from/%d)\n", scanWindow, shortSelf, addr.String(), next)
	}
	return s
}

// renderPositions walks one window of the position records and prints the rows
// belonging to addr.
//
// The walk is deliberately cheap per record and expensive per hit: identifying
// the owner is one or two tree lookups, while the price math behind IsInRange,
// the token balances and the unclaimed fees costs far more. Only a row that is
// actually printed pays for it.
func renderPositions(addr address, offset int) string {
	t := ui.NewTable("ID", "Pool", "Ticks", "Liquidity", "In range", "Holds", "Uncollected fees", "Staked", "Reward")

	position.GetPositions().IterateByOffset(offset, scanWindow, func(key string, _ any) bool {
		id, err := strconv.ParseUint(key, 10, 64)
		if err != nil {
			return false
		}
		owner, staked, ok := resolveOwner(id)
		if !ok || owner != addr {
			return false
		}
		t.Row(row(id, staked)...)
		return false
	})

	return t.OrEmpty("No positions in this window.")
}

// row is the expensive half: everything here reads pool price state or recomputes
// a fee, so it runs for a matched position and never for a scanned one.
func row(id uint64, staked bool) []string {
	poolKey, _ := position.GetPositionPoolKey(id)
	lower, upper, _ := position.GetPositionTicks(id)
	liquidity, _ := position.GetPositionLiquidity(id)
	inRange, _ := position.IsInRange(id)
	amount0, amount1, _ := position.GetPositionTokenBalances(id)
	fee0, fee1, _ := position.GetUnclaimedFee(id)

	reward := "-"
	if staked {
		if r, err := staker.CollectableEmissionReward(id); err == nil {
			reward = ufmt.Sprintf("%d", r)
		}
	}

	return []string{
		ufmt.Sprintf("%d", id),
		ui.Cell(shortPool(poolKey)),
		ufmt.Sprintf("%d to %d", lower, upper),
		ui.Cell(liquidity),
		yesNo(inRange),
		ufmt.Sprintf("%d / %d", amount0, amount1),
		ui.Cell(fee0) + " / " + ui.Cell(fee1),
		yesNo(staked),
		reward,
	}
}

// resolveOwner answers who a position really belongs to, and whether it is staked.
//
// Staking transfers the position NFT to the staker realm, so for every staked
// position the grc721 owner is that realm's address and not the person's. A
// dashboard that trusts the NFT owner alone shows an empty page to everyone who
// staked, which is most of them. The deposit record is what still names the
// person.
func resolveOwner(id uint64) (owner address, staked bool, ok bool) {
	held, err := position.GetPositionOwner(id)
	if err != nil {
		return "", false, false
	}
	if held != chain.PackageAddress(stakerPath) {
		return held, false, true
	}
	deposited, err := staker.GetDepositOwner(id)
	if err != nil {
		// Custodied by the staker with no deposit behind it: in flight, or a
		// record this realm does not understand. Better to say nothing than to
		// attribute it to the staker realm as if it were a user.
		return "", true, false
	}
	return deposited, true, true
}

// parsePath splits an address route from its optional scan offset.
func parsePath(path string) (addr string, offset int, ok bool) {
	addr, rest, found := strings.Cut(path, "/")
	if !found {
		return addr, 0, true
	}
	after, found := strings.CutPrefix(rest, "from/")
	if !found {
		return "", 0, false
	}
	n, err := strconv.Atoi(after)
	if err != nil || n < 0 {
		return "", 0, false
	}
	return addr, n, true
}

// shortPool turns a pool key ("<token0 path>.<symbol>:<token1 path>.<symbol>:<fee>")
// into something that fits a table cell.
func shortPool(poolKey string) string {
	parts := strings.Split(poolKey, ":")
	if len(parts) != 3 {
		return poolKey
	}
	return symbolOf(parts[0]) + "/" + symbolOf(parts[1]) + " " + parts[2]
}

// symbolOf takes the symbol off a GnoSwap token key, which is the grc20 registry
// form "<pkgpath>.<Symbol>".
func symbolOf(tokenKey string) string {
	if i := strings.LastIndex(tokenKey, "."); i >= 0 {
		return tokenKey[i+1:]
	}
	return tokenKey
}

func yesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

package gsdash

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"

	// GnoSwap's unversioned paths are proxies: the facade holds no logic and
	// panics with "implementation is not initialized" until some version has
	// registered itself. On chain that happened long ago; in a test VM nothing
	// has, so these blank imports run each implementation's init, which calls
	// RegisterInitializer, and the version manager activates the first one it
	// sees. Importing them here rather than from the realm keeps them out of
	// what gets deployed: the realm only ever names the proxy.
	_ "gno.land/r/gnoswap/pool/v1"
	_ "gno.land/r/gnoswap/position/v1"
	_ "gno.land/r/gnoswap/staker/v1"
)

// someone is a well-formed address with nothing on GnoSwap, which is what every
// address looks like in a fresh test VM.
const someone = "g1manfred47kzduec920z88wfr64ylksmdcedlf5"

func TestRenderIndexReadsTheProxies(t *testing.T) {
	out := Render("")
	uassert.True(t, len(out) > 0, "index renders")
	uassert.True(t, strings.Contains(out, "# GnoSwap dashboard"), "index has its heading")
	// Reaching this line at all is the point: Size() and TotalSupply() are
	// cross-realm reads through two different GnoSwap proxies, so an index that
	// renders proves both resolved to a live implementation.
	uassert.True(t, strings.Contains(out, "Stored position records"), "index read the position proxy")
	uassert.True(t, strings.Contains(out, "Position NFTs in circulation"), "index read the gnft realm")
}

func TestRenderAddressWithNothing(t *testing.T) {
	out := Render(someone)
	uassert.True(t, strings.Contains(out, someone), "the page names the address in full")
	uassert.True(t, strings.Contains(out, "No positions in this window."), "an empty window says so")
}

func TestRenderRejectsAMalformedAddress(t *testing.T) {
	out := Render("not-an-address")
	uassert.True(t, strings.Contains(out, "Not a valid address"), "a bad address is refused")
	uassert.False(t, strings.Contains(out, "## Positions"), "and no scan is run for it")
}

func TestRenderEscapesWhatTheReaderTyped(t *testing.T) {
	// The path is attacker-controlled: whatever is after the colon in the URL.
	// It must come back inert, never as a live link.
	out := Render("[click](https://evil.example)")
	uassert.False(t, strings.Contains(out, "](https://evil.example)"), "no live link survives")
}

func TestParsePath(t *testing.T) {
	tests := []struct {
		name       string
		path       string
		wantAddr   string
		wantOffset int
		wantOK     bool
	}{
		{"bare address", someone, someone, 0, true},
		{"with offset", someone + "/from/250", someone, 250, true},
		{"zero offset", someone + "/from/0", someone, 0, true},
		{"unknown segment", someone + "/nope", "", 0, false},
		{"offset not a number", someone + "/from/abc", "", 0, false},
		{"negative offset", someone + "/from/-1", "", 0, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			addr, offset, ok := parsePath(tt.path)
			uassert.Equal(t, tt.wantOK, ok)
			if !tt.wantOK {
				return
			}
			uassert.Equal(t, tt.wantAddr, addr)
			uassert.Equal(t, tt.wantOffset, offset)
		})
	}
}

func TestShortPool(t *testing.T) {
	tests := []struct {
		name string
		key  string
		want string
	}{
		{
			"a real pool key",
			"gno.land/r/gnoland/wugnot.wugnot:gno.land/r/gnoswap/gns.GNS:3000",
			"wugnot/GNS 3000",
		},
		{"not a pool key", "whatever", "whatever"},
		{"no symbol on a side", "a:b:100", "a/b 100"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			uassert.Equal(t, tt.want, shortPool(tt.key))
		})
	}
}

// ExampleRender pins the index as a fresh chain renders it: no positions, no
// NFTs, and the two proxy reads resolving to zero rather than panicking.
