package kitindexdemo

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// seed builds a fixed board without crossing anything, so an example can set up
// its own state.
//
// An Example has no realm token, so it cannot call Post, and the state the
// tests happen to leave is not a contract. Writing the globals directly is the
// escape hatch AGENTS.md names: same package, no crossing, fully deterministic.
func seed() {
	reset()
	add := func(who address, tag, body string, height int64) {
		id := notes.Add(&note{Author: who, Tag: tag, Body: body, Height: height})
		if err := byTag.Add(tag, id); err != nil {
			panic(err)
		}
		if err := byAuthor.Add(who.String(), id); err != nil {
			panic(err)
		}
	}
	add(alice, "gno", "the index is two containers and one function", 123)
	add(bob, "gno", "and the function is where the correctness is", 124)
	add(alice, "storage", "you are charged for objects, not for data", 125)
}

// The root page carries TWO consecutive blank lines, which an // Output: block
// can never pin: gno collapses them, exactly as Go does. So the root is
// asserted with uassert.Equal and a backtick literal, which preserves them,
// and only the pages without that shape get an Example.
//
// This is the order of preference AGENTS.md names, and the root page is the
// case that forces the second rung.
func TestRenderRoot(t *testing.T) {
	seed()
	want := `# Notes by tag

3 note(s) under 2 tag(s), by 2 author(s).


| tag | notes |
| --- | --- |
| [gno](/r/moul/x/kitindexdemo/v0:tag/gno) | 2 |
| [storage](/r/moul/x/kitindexdemo/v0:tag/storage) | 1 |

[Post a note](/r/moul/x/kitindexdemo/v0$help&func=Post&body=&tag=)

`
	uassert.Equal(t, want, Render(""))
}

// ExampleRender_tag pins one tag's page, which is the lookup the library is for.
func ExampleRender_tag() {
	seed()
	print(Render("tag/gno"))
	// Output:
	// # #gno
	// | # | author | tag | note | height |
	// | --- | --- | --- | --- | --- |
	// | 1 | `g1v9kxjc…40gh` | `gno` | the index is two containers and one function | 123 |
	// | 2 | `g1vfhkyh…vdhu` | `gno` | and the function is where the correctness is | 124 |
}

// untrusted-render: the tag is charset-checked to [a-z0-9-] at write time and
// is the only stored string interpolated raw; the body is a caller's text and
// goes through ui.Cell at every call site that renders it.

// Package kitindexdemo is a notes board whose only job is to show
// gno.land/p/moul/kit/index doing the thing a realm with a store always ends
// up needing: answering "every note tagged gno" as cheaply as it answers
// "note 7".
//
// There is no logic of its own here. The records are a kit/store, the two
// lookups are kit/index, the page is kit/ui, and what is worth reading is the
// shape: every write touches the store and both indexes in ONE function, which
// is the entire correctness argument for keeping them in separate containers.
//
// Demo of the p/moul/kit/index library.
package kitindexdemo

import (
	"chain/markdown"
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/index/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
)

// MaxBody is the longest note this realm accepts, in bytes.
//
// A bound rather than none: every byte stored here locks a storage deposit,
// paid by whoever signs the write and refunded to whoever signs the delete
// (EFFECTIVE_GNO.md section 9.2), and an unbounded write is an unbounded
// state the realm carries forever.
const MaxBody = 280

// MaxTagLen bounds the index key for the same reason, and small because a tag
// is a label rather than a sentence.
const MaxTagLen = 24

// PageSize is how many tags the root page shows.
const PageSize = 20

// MaxNotes and MaxPerAuthor bound the WHOLE board, which MaxBody does not.
//
// A per-call length limit bounds one write and nothing else: a caller posting
// one-byte notes in a loop grows the store and both indexes without limit. "An unbounded container a third party can grow is an
// unbounded storage deposit someone is paying for" is a rule this realm exists
// to demonstrate, so it had better obey it.
//
// Two caps rather than one, and what each buys is narrower than it looks.
// MaxNotes bounds the state, which is the property this realm promises.
// MaxPerAuthor stops one ADDRESS, not one actor: addresses are free, so fifty
// fresh ones at twenty notes each still fill the board and lock everyone else
// out until somebody retracts. Keeping a board open to strangers needs
// something a griefer cannot mint for free, a deposit or an expiry, which this
// demo does not carry. Retracting frees a slot, so neither cap is a one-way door.
//
// MaxPerAuthor is answered by byAuthor.Count, which is the index doing the job
// it was added for.
const (
	MaxNotes     = 1000
	MaxPerAuthor = 20
)

type note struct {
	Author address
	Tag    string
	Body   string
	Height int64
}

var (
	notes    = store.Named("note")
	byTag    index.Index
	byAuthor index.Index
)

// Post files a note under a tag and returns its id.
//
// The store write and both index writes happen here, in this order, in one
// frame. An abort anywhere in it leaves none of them applied, which is what
// makes three containers safe to keep apart.
func Post(cur realm, tag, body string) int64 {
	who := caller(cur)
	tag = normaliseTag(tag)
	assertBody(body)
	assertRoom(who)

	id := notes.Add(&note{
		Author: who,
		Tag:    tag,
		Body:   body,
		Height: runtime.ChainHeight(),
	})
	mustIndex(byTag.Add(tag, id))
	mustIndex(byAuthor.Add(who.String(), id))
	return int64(id)
}

// Retract removes a note. Only its author may, and the store and both indexes
// are unwound together.
func Retract(cur realm, id int64) {
	who := caller(cur)
	sid, ok := store.ParseID(strconv.FormatInt(id, 10))
	if !ok {
		panic("kitindexdemo: not an id: " + strconv.FormatInt(id, 10))
	}
	n, ok := notes.Get(sid)
	if !ok {
		panic("kitindexdemo: note #" + sid.String() + " not found")
	}
	rec := n.(*note)
	if rec.Author != who {
		panic("kitindexdemo: note #" + sid.String() + " is not yours")
	}
	notes.Remove(sid)
	byTag.Remove(rec.Tag, sid)
	byAuthor.Remove(rec.Author.String(), sid)
}

// caller is the one place this realm decides who is acting: the realm token is
// checked before it is walked, because an unchecked token is not a caller.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("kitindexdemo: spoofed realm")
	}
	return cur.Previous().Address()
}

func mustIndex(err error) {
	if err != nil {
		panic(err)
	}
}

// normaliseTag lowercases and validates the tag.
//
// Validated at WRITE time rather than escaped at render time, deliberately: a
// tag is also an index key and a path segment, so a tag that could carry a
// pipe or a slash would break the table and the URL as well as the page. The
// charset is the narrowest thing that still reads as a label.
func normaliseTag(tag string) string {
	tag = strings.ToLower(strings.TrimSpace(tag))
	if tag == "" || len(tag) > MaxTagLen {
		panic("kitindexdemo: a tag is 1 to " + strconv.Itoa(MaxTagLen) + " characters")
	}
	for _, r := range tag {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-':
		default:
			panic("kitindexdemo: a tag is [a-z0-9-], got " + strconv.Quote(tag))
		}
	}
	return tag
}

// assertRoom refuses a write the board has no room for, globally or for this
// address. Checked before the store write, so a refusal costs the caller the
// gas of three reads and nothing is half-applied.
func assertRoom(who address) {
	if notes.Len() >= MaxNotes {
		panic("kitindexdemo: the board is full at " + strconv.Itoa(MaxNotes) +
			" notes; retract one to free a slot")
	}
	if n := byAuthor.Count(who.String()); n >= MaxPerAuthor {
		panic("kitindexdemo: " + who.String() + " already has " + strconv.Itoa(n) +
			" notes, the limit is " + strconv.Itoa(MaxPerAuthor))
	}
}

func assertBody(body string) {
	if strings.TrimSpace(markdown.StripBidiAndZeroWidth(body)) == "" {
		panic("kitindexdemo: the body is empty")
	}
	if len(body) > MaxBody {
		panic("kitindexdemo: the body is " + strconv.Itoa(len(body)) +
			" bytes, the limit is " + strconv.Itoa(MaxBody))
	}
}

package kitindexdemo

import (
	"strconv"
	"strings"
	"testing"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/index/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
)

// reset puts the realm back to its init() state.
//
// Realm globals persist for the whole test binary and examples run after every
// Test, so without this an ExampleRender's pinned output depends silently on
// which tests ran before it. Assigning the globals directly is allowed here:
// same package, and it crosses nothing.
func reset() {
	notes = store.Named("note")
	byTag = index.Index{}
	byAuthor = index.Index{}
}

func TestPostIndexesInBothDirections(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	id := Post(cross(cur), "gno", "first")

	uassert.Equal(t, 1, notes.Len())
	uassert.Equal(t, 1, byTag.Count("gno"))
	uassert.Equal(t, 1, byAuthor.Count(alice.String()))

	got := byTag.Lookup("gno")
	urequire.Equal(t, 1, len(got))
	uassert.Equal(t, store.ID(id).String(), got[0].String())
}

func TestTagIsNormalisedAtWriteTime(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "  GNO  ", "mixed case and spaces")

	uassert.Equal(t, 1, byTag.Count("gno"))
	uassert.Equal(t, 1, byTag.Keys())
}

// The tag is an index key AND a path segment, so it is validated rather than
// escaped: a tag carrying a pipe or a slash breaks the table and the URL, not
// only the sentence.
func TestTagRefusals(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))

	for _, tc := range []struct {
		name string
		tag  string
		want string
	}{
		{"empty", "", "a tag is 1 to 24 characters"},
		{"blank", "   ", "a tag is 1 to 24 characters"},
		{"too long", "aaaaaaaaaaaaaaaaaaaaaaaaa", "a tag is 1 to 24 characters"},
		{"a pipe", "a|b", "a tag is [a-z0-9-]"},
		{"a slash", "a/b", "a tag is [a-z0-9-]"},
		{"markdown", "a]b", "a tag is [a-z0-9-]"},
		{"a space inside", "a b", "a tag is [a-z0-9-]"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			uassert.AbortsContains(t, cur, tc.want, func() {
				Post(cross(cur), tc.tag, "body")
			})
		})
	}
	uassert.Equal(t, 0, notes.Len())
}

func TestBodyRefusals(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))

	uassert.AbortsContains(t, cur, "the body is empty", func() {
		Post(cross(cur), "gno", "   ")
	})

	long := ""
	for i := 0; i <= MaxBody; i++ {
		long += "x"
	}
	uassert.AbortsContains(t, cur, "the limit is 280", func() {
		Post(cross(cur), "gno", long)
	})
	uassert.Equal(t, 0, notes.Len())
}

func TestOnlyTheAuthorMayRetract(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	id := Post(cross(cur), "gno", "alice's note")

	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsContains(t, cur, "is not yours", func() {
		Retract(cross(cur), id)
	})
	uassert.Equal(t, 1, notes.Len())

	testing.SetRealm(testing.NewUserRealm(alice))
	Retract(cross(cur), id)
	uassert.Equal(t, 0, notes.Len())
}

// The store and both indexes have to come apart together, or a later Render
// walks ids the store no longer holds.
func TestRetractUnwindsEveryContainer(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	id := Post(cross(cur), "gno", "one")
	Post(cross(cur), "gno", "two")

	Retract(cross(cur), id)

	uassert.Equal(t, 1, notes.Len())
	uassert.Equal(t, 1, byTag.Count("gno"))
	uassert.Equal(t, 1, byAuthor.Count(alice.String()))
}

func TestRetractRefusals(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))

	uassert.AbortsContains(t, cur, "not found", func() { Retract(cross(cur), 99) })
	uassert.AbortsContains(t, cur, "not an id", func() { Retract(cross(cur), 0) })
	uassert.AbortsContains(t, cur, "not an id", func() { Retract(cross(cur), -1) })
}

// A body is a caller's markdown and must not be able to write the page around
// it. ui.Cell is what stops a pipe from opening a column.
func TestARenderedBodyCannotBreakTheTable(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "gno", "a | b [x](http://evil)")

	got := Render("tag/gno")
	uassert.False(t, strings.Contains(got, "| a | b ["),
		"the raw body must not reach the table")
	uassert.True(t, strings.Contains(got, "\\|"),
		"the pipe must be escaped")
}

func TestRenderOfAnUnknownPage(t *testing.T) {
	reset()
	uassert.True(t, strings.Contains(Render("nope"), "Not found"))
	uassert.True(t, strings.Contains(Render("tag"), "No tag given."))
	uassert.True(t, strings.Contains(Render("author"), "No author given."))
}

// MaxBody bounds one write. These bound the bill, which is the thing the realm
// actually pays.
func TestPerAuthorCap(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i < MaxPerAuthor; i++ {
		Post(cross(cur), "gno", "note "+strconv.Itoa(i))
	}
	uassert.AbortsContains(t, cur, "the limit is 20", func() {
		Post(cross(cur), "gno", "one too many")
	})

	// Another address is unaffected, which is the whole reason the cap is
	// per author and not only global.
	testing.SetRealm(testing.NewUserRealm(bob))
	Post(cross(cur), "gno", "bob still fits")
	uassert.Equal(t, MaxPerAuthor+1, notes.Len())
}

// Retracting frees a slot, so the cap is not a one-way door.
func TestRetractingFreesASlot(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	first := Post(cross(cur), "gno", "note 0")
	for i := 1; i < MaxPerAuthor; i++ {
		Post(cross(cur), "gno", "note "+strconv.Itoa(i))
	}
	uassert.AbortsContains(t, cur, "the limit is 20", func() {
		Post(cross(cur), "gno", "blocked")
	})

	Retract(cross(cur), first)
	Post(cross(cur), "gno", "now it fits")
	uassert.Equal(t, MaxPerAuthor, notes.Len())
}

// The page number is user input on the Render path. One outside 1..Pages is
// clamped into it, so it never renders an empty board under a footer that
// says "page -1 of 2".
func TestRenderClampsThePageNumber(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i < PageSize; i++ {
		Post(cross(cur), "t"+strconv.Itoa(i), "x")
	}
	testing.SetRealm(testing.NewUserRealm(bob))
	Post(cross(cur), "t-last", "x")
	urequire.Equal(t, 2, byTag.Pages(PageSize))

	first, last := Render("?page=1"), Render("?page=2")
	uassert.Equal(t, first, Render("?page=-1"))
	uassert.Equal(t, first, Render("?page=0"))
	uassert.Equal(t, last, Render("?page=999"))
	uassert.True(t, strings.Contains(last, "page 2 of 2"))
}

// Links are absolute. gnoweb serves this realm at .../kitindexdemo/v0, so a
// "./kitindexdemo:tag/x" link resolves to .../kitindexdemo/kitindexdemo:tag/x,
// a package that does not exist.
func TestRenderLinksAreAbsolute(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i <= PageSize; i++ {
		if i == MaxPerAuthor {
			testing.SetRealm(testing.NewUserRealm(bob))
		}
		Post(cross(cur), "t"+strconv.Itoa(i), "x")
	}
	out := Render("")
	uassert.True(t, strings.Contains(out, "](/r/moul/x/kitindexdemo/v0:tag/t0)"), out)
	uassert.True(t, strings.Contains(out, "](/r/moul/x/kitindexdemo/v0:?page=2)"), out)
	uassert.False(t, strings.Contains(out, "](./"), out)
}

// realmURL must follow the module line, or a version bump ships dead links.
func TestRealmURLMatchesTheModule(cur realm, t *testing.T) {
	uassert.Equal(t, "gno.land"+realmURL, cur.PkgPath())
}

// The global cap is what bounds the realm's whole storage bill, so its
// refusal is pinned, and pinned as refusing BEFORE any write: the store and
// both indexes are exactly as full as they were.
func TestTheBoardIsFull(cur realm, t *testing.T) {
	reset()
	for i := 0; i < MaxNotes; i++ {
		notes.Add(&note{Author: bob, Tag: "gno", Body: "x"})
	}
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "the board is full", func() {
		Post(cross(cur), "gno", "one too many")
	})
	uassert.Equal(t, MaxNotes, notes.Len())
	uassert.Equal(t, 0, byTag.Len())
	uassert.Equal(t, 0, byAuthor.Count(alice.String()))
}

package kitindexdemo

import (
	"strconv"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/realmpath/v0"
)

// realmURL is this realm as gnoweb serves it. Links are absolute because the
// path ends in /v0: a relative "./kitindexdemo:tag/x" resolves against the
// parent directory to .../kitindexdemo/kitindexdemo:tag/x, which does not
// exist. Not derived at runtime: a Render has no cur, and CurrentRealm there
// is the caller. TestRealmURLMatchesTheModule pins it to the module line.
const realmURL = "/r/moul/x/kitindexdemo/v0"

// Render is the whole public surface. Three pages: the tag list, one tag, one
// author.
//
// Every row goes through ui.NewTable rather than concatenated pipes, and every
// caller string through ui.Cell, because a public path is immutable and a
// Render that ships wrong ships forever.
func Render(path string) string {
	req := realmpath.Parse(path)
	switch req.PathPart(0) {
	case "":
		return renderIndex(req)
	case "tag":
		return renderTag(req.PathPart(1))
	case "author":
		return renderAuthor(req.PathPart(1))
	default:
		return md.H1("Not found") + ui.Empty("No such page.")
	}
}

func renderIndex(req *realmpath.Request) string {
	// The page number is user input: clamp it into 1..pages, or ?page=-1
	// renders an empty board under a footer saying "page -1 of 2".
	pages := byTag.Pages(PageSize)
	page := 1
	if n, err := strconv.Atoi(req.Query.Get("page")); err == nil {
		page = n
	}
	if page < 1 {
		page = 1
	}
	if page > pages {
		page = pages
	}

	t := ui.NewTable("tag", "notes")
	for _, e := range byTag.Page(page, PageSize) {
		t.Row(
			md.Link(e.Key, realmURL+":tag/"+e.Key),
			strconv.Itoa(len(e.IDs)),
		)
	}

	return ui.Join("\n",
		md.H1("Notes by tag"),
		md.Paragraph(strconv.Itoa(notes.Len())+" note(s) under "+
			strconv.Itoa(byTag.Keys())+" tag(s), by "+
			strconv.Itoa(byAuthor.Keys())+" author(s)."),
		t.OrEmpty("Nothing posted yet."),
		pager(page, pages),
		md.Paragraph(ui.Action("Post a note", "Post", "tag", "", "body", "")),
	)
}

func renderTag(tag string) string {
	if tag == "" {
		return md.H1("Not found") + ui.Empty("No tag given.")
	}
	return md.H1("#"+ui.Cell(tag)) + notesTable(byTag.Lookup(tag), "No notes under this tag.")
}

func renderAuthor(addr string) string {
	if addr == "" {
		return md.H1("Not found") + ui.Empty("No author given.")
	}
	return md.H1("Notes by "+ui.AddrOf(addr)) +
		notesTable(byAuthor.Lookup(addr), "This address has posted nothing.")
}

// notesTable renders a set of ids as rows, skipping any id the store no longer
// holds.
//
// Skipping rather than panicking: an index and a store are two containers, and
// a reader should see the records that exist rather than a page that aborts.
// Retract keeps the two in step, so a miss here means a bug worth surviving,
// not worth hiding.
func notesTable(hits []store.ID, empty string) string {
	t := ui.NewTable("#", "author", "tag", "note", "height")
	for _, id := range hits {
		v, ok := notes.Get(id)
		if !ok {
			continue
		}
		n := v.(*note)
		t.Row(
			id.String(),
			ui.Addr(n.Author),
			md.InlineCode(n.Tag),
			ui.Cell(n.Body),
			strconv.FormatInt(n.Height, 10),
		)
	}
	return t.OrEmpty(empty)
}

// pager renders the previous/next links, or nothing when there is one page.
func pager(page, pages int) string {
	if pages < 2 {
		return ""
	}
	out := ""
	if page > 1 {
		out += md.Link("previous", realmURL+":?page="+strconv.Itoa(page-1)) + " "
	}
	out += "page " + strconv.Itoa(page) + " of " + strconv.Itoa(pages)
	if page < pages {
		out += " " + md.Link("next", realmURL+":?page="+strconv.Itoa(page+1))
	}
	return out
}

// Package moultest issues `moultest`, a NATIVE coin, and gives it away.
//
// Native here means the chain's own bank holds it, exactly as it holds GNOT.
// It is not a GRC20: there is no ledger in this realm's storage, no balance
// map, no Transfer function, no allowance. A realm with the right banker calls
// IssueCoin once and from that moment the coin is a first-class chain object,
// and this realm has no further say in who holds it.
//
// # What that buys, and what it costs
//
// The interesting half is what disappears. Moving moultest needs no code here
// at all: a plain bank send does it, from any wallet, with no realm call and no
// approval dance, because the transfer is a tm2 bank message rather than a
// function call. It can also RIDE a transaction: the `-send` envelope of a call
// carries it into the realm being called, which is the one thing no GRC20 can
// do, and [Tip] exists to show it. The account page of any explorer lists it
// beside GNOT with nothing registered anywhere.
//
// The half that is worse is the authority. A GRC20's mint and burn live behind
// a PrivateLedger this realm chooses to guard; a native coin's live in a banker
// minted from a realm handle, and banker.RemoveCoin takes an ARBITRARY address.
// Nothing in the chain stops the issuing realm from deleting anybody's balance
// at any time. This realm does not expose that (see [Burn], which is scoped to
// the caller and to nobody else), but "does not expose it" is the only
// protection there is, and it lasts exactly as long as the deployed code. That
// is the real asymmetry against a GRC20, not the ergonomics.
//
// There is no decimals field either, nor a name, nor a symbol: a native denom
// is a string and nothing else. 1000 moultest is a thousand moultest.
//
// # Why it is capped
//
// Free money with no ceiling is a spam vector rather than a faucet, so [Claim]
// is bounded four ways, and the caps are the point of the experiment as much as
// the coin is:
//
//   - [ClaimAmount] per call, to the CALLER only, never to an address the
//     caller names, so nobody can dust a stranger with it.
//   - [ClaimEvery] blocks of cooldown between two claims by one account.
//   - [MaxPerAccount] over that account's lifetime.
//   - [MaxSupply] over the realm's lifetime.
//
// [Burn] does not give any of it back. Issuance is counted monotonically, so
// claim-burn-claim cannot walk around the per-account cap; what burning moves
// is the circulating supply, which is why the two numbers are reported
// separately.
//
// # It is a private realm
//
// gnomod.toml declares private = true, so this path can be redeployed with
// corrected code instead of being abandoned for a v1. The price is measured
// elsewhere in this repo and applies here too: the coins survive a redeploy
// (they are bank state, held at their owners' addresses, and the denom embeds
// the package path, which does not move), and everything on this page does not.
// Claim history, caps consumed and the tip board all return to their init
// values, which would hand every account a fresh [MaxPerAccount]. For a coin
// that is worthless by construction that is an acceptable trade; it would not
// be for one that is not.
package moultest

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// Name is the coin's base denom: the part after the colon. The chain caps
	// it at 16 lowercase characters.
	Name = "moultest"
	// Path is this realm's package path. The denom embeds it verbatim, so the
	// coin and the code are permanently the same name.
	Path = "gno.land/r/moul/x/moultest/v0"
	// Link is Path as a gnoweb route.
	Link = "/r/moul/x/moultest/v0"
)

// Denom is the full chain denom, "/" + [Path] + ":" + [Name]. This is the
// string a wallet, an explorer or a `-send` flag needs; the bank knows nothing
// about the realm behind it.
var Denom = chain.CoinDenom(Path, Name)

const (
	// ClaimAmount is issued per successful [Claim].
	ClaimAmount = int64(10_000)
	// ClaimEvery is the cooldown, in blocks, between two claims by one account.
	ClaimEvery = int64(100)
	// MaxPerAccount is the lifetime ceiling on what one address can claim here,
	// ten claims' worth. Burning does not raise it.
	MaxPerAccount = int64(100_000)
	// MaxSupply is the lifetime ceiling on what this realm can ever issue: a
	// hundred claims' worth, all told. Nothing lowers it, so the coin cannot be
	// inflated after the fact, and the experiment has an end rather than a
	// budget. A faucet meant to serve a crowd would put the ceiling somewhere
	// else; this one is meant to run out.
	MaxSupply = int64(1_000_000)

	// MaxNote is the longest tip note kept, in bytes.
	MaxNote = 120
	// MaxTips is how many tips the board shows. Older ones fall off.
	MaxTips = 20
)

type account struct {
	lastClaim int64 // block height of the most recent claim
	claims    int64 // how many times this address has claimed
	issued    int64 // lifetime total issued to it, never decremented
}

// Tip is one entry of the public board written by [Tip].
type tip struct {
	from   address
	to     address
	amount int64
	note   string
	height int64
}

var (
	accounts = avl.NewTree() // address string -> *account

	// issued and burned are counted here rather than derived from the bank:
	// TotalCoin reports what CIRCULATES, and the caps are about what was ever
	// minted. The two differ by exactly `burned`, which a test pins.
	issued int64
	burned int64

	tips []*tip // most recent last, at most MaxTips
)

// Claim issues [ClaimAmount] of moultest to the caller and returns it.
//
// It never issues to an address the caller names. That is deliberate: a faucet
// that mints to a third party is a way to spray a denom nobody asked for into
// strangers' wallets, and their account page then carries it forever.
func Claim(cur realm) int64 {
	who := caller(cur)
	a := accountOf(who)
	now := runtime.ChainHeight()

	if a.claims > 0 && now < a.lastClaim+ClaimEvery {
		panic(ufmt.Sprintf("too soon: next claim at block %d, current %d",
			a.lastClaim+ClaimEvery, now))
	}
	if a.issued+ClaimAmount > MaxPerAccount {
		panic(ufmt.Sprintf("account cap reached: %d of %d already claimed by this address",
			a.issued, MaxPerAccount))
	}
	if issued+ClaimAmount > MaxSupply {
		panic(ufmt.Sprintf("supply cap reached: %d of %d already issued",
			issued, MaxSupply))
	}

	a.lastClaim = now
	a.claims++
	a.issued += ClaimAmount
	accounts.Set(who.String(), a)
	issued += ClaimAmount

	banker.NewBanker(banker.BankerTypeRealmIssue, cur).IssueCoin(who, Denom, ClaimAmount)
	return ClaimAmount
}

// Burn destroys `amount` of the CALLER's moultest, and only the caller's.
//
// The banker this realm holds could remove coins from any address on the chain
// without asking, so the `who` here is read from the call frame and is never a
// parameter. A clawback is what an issuing realm is always able to write; the
// choice not to is made here, once, and cannot be revisited without a redeploy.
//
// Burning lowers what circulates and does not return any cap headroom: see
// [MaxPerAccount].
func Burn(cur realm, amount int64) {
	if amount <= 0 {
		panic("burn a positive amount")
	}
	who := caller(cur)
	if bal := BalanceOf(who); bal < amount {
		panic(ufmt.Sprintf("balance is %d, cannot burn %d", bal, amount))
	}

	banker.NewBanker(banker.BankerTypeRealmIssue, cur).RemoveCoin(who, Denom, amount)
	burned += amount
}

// Tip forwards the moultest attached to THIS transaction to `to`, and writes
// the note on a public board.
//
// The coin arrives in the `-send` envelope of the call, credited to this
// realm's address before a line of this function runs, and leaves through a
// BankerTypeOriginSend banker, whose whole authority is that envelope: it can
// spend what this message paid in and not one coin more, not even out of the
// realm's own balance. So the realm can route a payment it was handed while
// being structurally unable to touch anything else.
//
// A GRC20 has no equivalent. Its tokens cannot ride a message, so the same flow
// costs an Approve, then a call, then an allowance that outlives both.
//
// Anything else in the envelope (the GNOT covering a storage deposit, say) is
// left alone and stays with the realm.
func Tip(cur realm, to address, note string) int64 {
	who := caller(cur)
	if !to.IsValid() {
		panic("tip a valid address")
	}
	if to == who {
		panic("tip somebody else")
	}
	if len(note) > MaxNote {
		panic(ufmt.Sprintf("note is %d bytes, max %d", len(note), MaxNote))
	}

	amount := unsafe.OriginSend().AmountOf(Denom)
	if amount <= 0 {
		panic("attach moultest to the transaction: -send " + Denom)
	}

	b := banker.NewBanker(banker.BankerTypeOriginSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(Denom, amount)))

	tips = append(tips, &tip{
		from:   who,
		to:     to,
		amount: amount,
		note:   note,
		height: runtime.ChainHeight(),
	})
	if len(tips) > MaxTips {
		tips = tips[len(tips)-MaxTips:]
	}
	return amount
}

// BalanceOf returns what the bank holds of moultest for `who`. It reads the
// chain, not this realm: a balance this realm never saw counts the same.
func BalanceOf(who address) int64 {
	return banker.NewReadonlyBanker().GetCoin(who, Denom)
}

// Circulating returns how much moultest exists right now, from the bank.
func Circulating() int64 {
	return banker.NewReadonlyBanker().TotalCoin(Denom)
}

// Issued returns how much this realm has ever issued. It only grows, and it is
// what [MaxSupply] caps.
func Issued() int64 { return issued }

// Burned returns how much has been destroyed through [Burn].
func Burned() int64 { return burned }

// NextClaim returns the block height at which `who` may claim again, and
// whether they have ever claimed at all.
func NextClaim(who address) (int64, bool) {
	a := accounts.Get(who.String())
	if a == nil {
		return 0, false
	}
	return a.(*account).lastClaim + ClaimEvery, true
}

// ClaimedBy returns the lifetime total issued to `who` by this realm, which is
// what [MaxPerAccount] caps.
func ClaimedBy(who address) int64 {
	a := accounts.Get(who.String())
	if a == nil {
		return 0
	}
	return a.(*account).issued
}

// Accounts returns how many addresses have ever claimed.
func Accounts() int { return accounts.Size() }

func accountOf(who address) *account {
	if v := accounts.Get(who.String()); v != nil {
		return v.(*account)
	}
	return &account{}
}

// caller is the account or realm that crossed into this one.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("moultest: stale realm token")
	}
	return cur.Previous().Address()
}

package moultest

import (
	"chain"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// testing.SetRealm governs only the crossing calls made from the frame that
// called it, so every account switch below is written inline in the test body
// rather than in a helper.

func TestDenom(t *testing.T) {
	// The denom is what a wallet, an explorer and a -send flag all type, and it
	// is immutable once the first coin exists. Pin the literal: deriving it from
	// Path would restate the code rather than check it.
	uassert.Equal(t, "/gno.land/r/moul/x/moultest/v0:moultest", Denom)
}

func TestClaimIssuesRealCoins(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mt-alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	_, ever := NextClaim(alice)
	uassert.False(t, ever, "no claim recorded before the first one")
	uassert.Equal(t, int64(0), BalanceOf(alice))

	before := Circulating()
	got := Claim(cross(cur))

	uassert.Equal(t, ClaimAmount, got)
	// The balance comes from the bank, not from realm storage: nothing in this
	// realm records who holds what.
	uassert.Equal(t, ClaimAmount, BalanceOf(alice))
	uassert.Equal(t, before+ClaimAmount, Circulating())
	uassert.Equal(t, ClaimAmount, ClaimedBy(alice))

	next, ever := NextClaim(alice)
	uassert.True(t, ever, "a cooldown is recorded")
	uassert.Equal(t, ClaimEvery, next-123, "first test block is 123, so the cooldown lands there")
}

func TestClaimCooldown(cur realm, t *testing.T) {
	bob := testutils.TestAddress("mt-bob")
	testing.SetRealm(testing.NewUserRealm(bob))

	Claim(cross(cur))
	uassert.AbortsContains(t, cur, "too soon", func() { Claim(cross(cur)) })

	testing.SkipHeights(ClaimEvery - 1)
	uassert.AbortsContains(t, cur, "too soon", func() { Claim(cross(cur)) })

	testing.SkipHeights(1)
	Claim(cross(cur))
	uassert.Equal(t, 2*ClaimAmount, BalanceOf(bob))
}

func TestAccountCap(cur realm, t *testing.T) {
	carol := testutils.TestAddress("mt-carol")
	testing.SetRealm(testing.NewUserRealm(carol))

	for ClaimedBy(carol)+ClaimAmount <= MaxPerAccount {
		Claim(cross(cur))
		testing.SkipHeights(ClaimEvery)
	}
	uassert.Equal(t, MaxPerAccount, ClaimedBy(carol))
	uassert.AbortsContains(t, cur, "account cap reached", func() { Claim(cross(cur)) })

	// Waiting does not help: the cooldown is not what stopped it.
	testing.SkipHeights(ClaimEvery * 10)
	uassert.AbortsContains(t, cur, "account cap reached", func() { Claim(cross(cur)) })
}

func TestBurnIsScopedToTheCaller(cur realm, t *testing.T) {
	dave := testutils.TestAddress("mt-dave")
	erin := testutils.TestAddress("mt-erin")

	testing.SetRealm(testing.NewUserRealm(erin))
	Claim(cross(cur))
	erinBefore := BalanceOf(erin)

	testing.SetRealm(testing.NewUserRealm(dave))
	Claim(cross(cur))

	issuedBefore, burnedBefore, circBefore := Issued(), Burned(), Circulating()
	claimedBefore := ClaimedBy(dave)

	Burn(cross(cur), 400)

	uassert.Equal(t, ClaimAmount-400, BalanceOf(dave))
	uassert.Equal(t, circBefore-400, Circulating(), "burning destroys the coin, it is not moved")
	uassert.Equal(t, burnedBefore+400, Burned())
	// Issuance is monotonic on purpose: if burning gave cap headroom back,
	// claim-burn-claim would be an unlimited faucet.
	uassert.Equal(t, issuedBefore, Issued())
	uassert.Equal(t, claimedBefore, ClaimedBy(dave))
	// Burn takes no address, so erin cannot be reached from dave's call.
	uassert.Equal(t, erinBefore, BalanceOf(erin))

	uassert.AbortsContains(t, cur, "cannot burn", func() { Burn(cross(cur), 1_000_000) })
	uassert.AbortsContains(t, cur, "positive amount", func() { Burn(cross(cur), 0) })
	uassert.AbortsContains(t, cur, "positive amount", func() { Burn(cross(cur), -5) })
}

func TestTipRidesTheEnvelope(cur realm, t *testing.T) {
	frank := testutils.TestAddress("mt-frank")
	grace := testutils.TestAddress("mt-grace")

	// On chain the -send envelope is credited to this realm's address before
	// the function runs. The test harness has no bank-send primitive, so the
	// credit is issued directly here; SetOriginSend is what the banker checks
	// against, and it is the half that bounds what Tip may spend.
	realmAddr := chain.PackageAddress(Path)
	envelope := chain.NewCoins(chain.NewCoin(Denom, 250))
	testing.IssueCoins(realmAddr, envelope)
	// Unrelated coins already sitting at the realm's address. A RealmSend
	// banker could spend these; the OriginSend one may not, and that is the
	// property being pinned.
	testing.IssueCoins(realmAddr, chain.NewCoins(chain.NewCoin(Denom, 5_000)))
	realmBefore := BalanceOf(realmAddr)

	testing.SetRealm(testing.NewUserRealm(frank))
	testing.SetOriginSend(envelope)
	sent := Tip(cross(cur), grace, "nice work")

	uassert.Equal(t, int64(250), sent)
	uassert.Equal(t, int64(250), BalanceOf(grace), "the tip landed on the recipient")
	uassert.Equal(t, realmBefore-250, BalanceOf(realmAddr),
		"exactly the envelope left the realm, and nothing else it was holding")
	uassert.Equal(t, 1, len(tips))
	uassert.Equal(t, "nice work", tips[0].note)

	testing.SetOriginSend(nil)
}

func TestTipRefusals(cur realm, t *testing.T) {
	heidi := testutils.TestAddress("mt-heidi")
	ivan := testutils.TestAddress("mt-ivan")

	testing.SetRealm(testing.NewUserRealm(heidi))
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "attach moultest", func() { Tip(cross(cur), ivan, "hi") })

	envelope := chain.NewCoins(chain.NewCoin(Denom, 10))
	testing.IssueCoins(chain.PackageAddress(Path), envelope)
	testing.SetOriginSend(envelope)
	uassert.AbortsContains(t, cur, "tip somebody else", func() { Tip(cross(cur), heidi, "me") })
	uassert.AbortsContains(t, cur, "valid address", func() { Tip(cross(cur), "nope", "hi") })
	uassert.AbortsContains(t, cur, "note is", func() {
		Tip(cross(cur), ivan, strings.Repeat("x", MaxNote+1))
	})

	testing.SetOriginSend(nil)
}

func TestSupplyCap(cur realm, t *testing.T) {
	// Fill the remaining supply with fresh accounts, each capped at
	// MaxPerAccount, then check that the next one is refused. Issuance carries
	// across tests, so the loop starts from whatever is left rather than from
	// MaxSupply.
	names := []string{"cap-a", "cap-b", "cap-c", "cap-d", "cap-e", "cap-f",
		"cap-g", "cap-h", "cap-i", "cap-j", "cap-k", "cap-l"}
	for _, name := range names {
		if Issued()+ClaimAmount > MaxSupply {
			break
		}
		who := testutils.TestAddress(name)
		testing.SetRealm(testing.NewUserRealm(who))
		for ClaimedBy(who)+ClaimAmount <= MaxPerAccount && Issued()+ClaimAmount <= MaxSupply {
			Claim(cross(cur))
			testing.SkipHeights(ClaimEvery)
		}
	}
	uassert.Equal(t, MaxSupply, Issued(), "the accounts above exhaust the supply exactly")

	late := testutils.TestAddress("cap-late")
	testing.SetRealm(testing.NewUserRealm(late))
	uassert.AbortsContains(t, cur, "supply cap reached", func() { Claim(cross(cur)) })

	// Burning does not reopen the faucet either: circulating drops, issued does
	// not, and the cap is on issued.
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("cap-a")))
	Burn(cross(cur), 500)
	uassert.Equal(t, MaxSupply, Issued())
	testing.SetRealm(testing.NewUserRealm(late))
	uassert.AbortsContains(t, cur, "supply cap reached", func() { Claim(cross(cur)) })
}

func TestRender(t *testing.T) {
	index := Render("")
	uassert.True(t, strings.Contains(index, "# moultest"), "heading:\n"+index)
	uassert.True(t, strings.Contains(index, Denom), "the denom is on the page")
	uassert.True(t, strings.Contains(index, "| issued, ever |"), "supply table:\n"+index)
	uassert.True(t, strings.Contains(index, "nice work"), "the tip board is shown:\n"+index)

	frank := testutils.TestAddress("mt-frank")
	acct := Render(frank.String())
	uassert.True(t, strings.Contains(acct, frank.String()), "the account section names it:\n"+acct)
	uassert.True(t, strings.Contains(acct, "claimed for life"), acct)

	// A path that is not an address renders the index without an account block.
	uassert.False(t, strings.Contains(Render("not-an-address"), "claimed for life"),
		"a junk path adds no account section")
}

// Package nativereg is the metadata a native coin does not have.
//
// A realm-issued coin is a string and a balance. `/gno.land/r/moul/x/moultest/v0:moultest`
// is the entire object: no name, no symbol, no decimals, no icon, no link to
// whoever issues it. The bank knows the number and nothing else, so a wallet or
// an explorer showing you a balance has only that path to print.
//
// This realm is where a denom says what it is. It is the mirror image of
// `r/nt/grc20reg`, and the two solve opposite problems: a GRC20 is an object
// that carries its own name and is hard to FIND, so the registry maps a key to
// the object; a native denom is trivial to find and carries no name, so the
// registry maps the denom to what it means.
//
// # Registration is proved, not claimed
//
// A denom embeds the package path of the realm allowed to issue it, verbatim:
// `"/" + pkgPath + ":" + baseName` (`chain.CoinDenom`). So the issuer is
// readable from the denom, and [Register] simply requires the caller to be it.
// A realm registers its own coins and nobody else's, with no allowlist, no
// owner and no signature scheme.
//
// A user account cannot register anything, not even a denom it holds all of:
// there is no package path in a user call to compare against. That is the
// intended shape, since the thing being described is the issuance, not the
// holding.
//
// # What is a hint and what is a fact
//
// `Denom` and `Issuer` are facts: the chain enforces the relation between them.
// Everything else is whatever the issuing realm chose to say, and `Decimals` in
// particular is a DISPLAY hint with nothing behind it. The bank has no notion of
// divisibility; a coin wrapped out of a 6-decimal GRC20 is still counted in
// whole units by every balance query. Rendering 1000000 as 1.000000 is a
// convention between this realm and whoever reads it.
//
// So trusting an entry means trusting the realm that wrote it, exactly as much
// as holding its coin already means trusting it not to call `RemoveCoin` on you.
package nativereg

import (
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Entry is what one denom says about itself.
type Entry struct {
	// Denom is the full chain denom, the key of this registry.
	Denom string
	// Issuer is the package path embedded in Denom: the only realm that can
	// issue, remove or re-describe this coin.
	Issuer string
	// Name, Symbol and Decimals are display metadata, chosen by the issuer.
	// Decimals is a hint; see the package doc.
	Name     string
	Symbol   string
	Decimals int
	// Doc is one line about what the coin is for.
	Doc string
	// Height is when the entry was last written.
	Height int64
	// Revisions counts how many times the issuer has rewritten it.
	Revisions int
}

const (
	// MaxName, MaxSymbol and MaxDoc bound what an issuer can store here. The
	// registry pays the storage for every byte a caller hands it, so the
	// limits are the realm's own cost control, not a style rule.
	MaxName   = 40
	MaxSymbol = 12
	MaxDoc    = 200
	// MaxDecimals matches the GRC20 ceiling, which is where a wrapped coin's
	// hint comes from in practice.
	MaxDecimals = 18
)

var (
	byDenom = avl.NewTree() // denom -> *Entry
	denoms  []string        // registration order, for a stable Render
)

// Register records or rewrites what a denom means. The caller must be the realm
// the denom names, which is the entire authorization.
//
// Calling it again overwrites the entry and bumps [Entry.Revisions]. An issuer
// can always re-describe its own coin, and can never describe anybody else's.
func Register(cur realm, denom, name, symbol string, decimals int, doc string) {
	issuer := issuerOf(denom)
	prev := cur.Previous()
	if prev.PkgPath() == "" {
		panic("only the issuing realm can register a denom; a user account has no package path to prove")
	}
	if prev.PkgPath() != issuer {
		panic(ufmt.Sprintf("%s is issued by %s, not by %s", denom, issuer, prev.PkgPath()))
	}
	assertLen("name", name, MaxName)
	assertLen("symbol", symbol, MaxSymbol)
	assertLen("doc", doc, MaxDoc)
	if decimals < 0 || decimals > MaxDecimals {
		panic(ufmt.Sprintf("decimals is %d, must be 0 to %d", decimals, MaxDecimals))
	}

	e := &Entry{
		Denom:    denom,
		Issuer:   issuer,
		Name:     name,
		Symbol:   symbol,
		Decimals: decimals,
		Doc:      doc,
		Height:   runtime.ChainHeight(),
	}
	if old := byDenom.Get(denom); old != nil {
		e.Revisions = old.(*Entry).Revisions + 1
	} else {
		denoms = append(denoms, denom)
	}
	byDenom.Set(denom, e)
}

// Get returns the entry for a denom, and whether it has one.
func Get(denom string) (Entry, bool) {
	v := byDenom.Get(denom)
	if v == nil {
		return Entry{}, false
	}
	return *v.(*Entry), true
}

// MustGet is [Get] for a caller that treats an unregistered denom as a bug.
func MustGet(denom string) Entry {
	e, ok := Get(denom)
	if !ok {
		panic("no entry for " + denom)
	}
	return e
}

// IsRegistered reports whether a denom has said anything about itself.
func IsRegistered(denom string) bool {
	return byDenom.Get(denom) != nil
}

// List returns every entry, in registration order.
func List() []Entry {
	out := make([]Entry, 0, len(denoms))
	for _, d := range denoms {
		out = append(out, MustGet(d))
	}
	return out
}

// ByIssuer returns every entry issued by one realm, in registration order.
func ByIssuer(pkgPath string) []Entry {
	out := []Entry{}
	for _, d := range denoms {
		if e := MustGet(d); e.Issuer == pkgPath {
			out = append(out, e)
		}
	}
	return out
}

// Count returns how many denoms are registered.
func Count() int { return byDenom.Size() }

// IssuerOf returns the package path embedded in a denom, without consulting the
// registry: the relation is in the string itself. It aborts on anything that is
// not a realm denom, which includes `ugnot`.
//
// It is exported because it is useful to anybody handling a denom, registered or
// not: given a balance, this is how you find the code that can take it away.
func IssuerOf(denom string) string { return issuerOf(denom) }

func issuerOf(denom string) string {
	if !strings.HasPrefix(denom, "/") {
		panic("not a realm denom (it must start with /): " + denom)
	}
	i := strings.LastIndex(denom, ":")
	if i < 0 {
		panic("not a realm denom (it must contain :): " + denom)
	}
	issuer := denom[1:i]
	if issuer == "" || denom[i+1:] == "" {
		panic("malformed denom: " + denom)
	}
	return issuer
}

func assertLen(what, s string, max int) {
	if len(s) > max {
		panic(ufmt.Sprintf("%s is %d bytes, max %d", what, len(s), max))
	}
}

package nativereg

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const (
	issuerPath = "gno.land/r/test/coiner"
	issuerCoin = "/gno.land/r/test/coiner:testcoin"
	otherPath  = "gno.land/r/test/stranger"
	otherCoin  = "/gno.land/r/test/stranger:othercoin"
)

// testing.SetRealm governs only the crossing calls made from the frame that
// called it, so each switch below is inline in the test body.

func TestOnlyTheIssuerRegisters(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewCodeRealm(issuerPath))
	Register(cross(cur), issuerCoin, "Test Coin", "TEST", 6, "a coin for a test")

	e := MustGet(issuerCoin)
	uassert.Equal(t, issuerPath, e.Issuer, "the issuer is read out of the denom, not supplied")
	uassert.Equal(t, "TEST", e.Symbol)
	uassert.Equal(t, 6, e.Decimals)
	uassert.Equal(t, 0, e.Revisions)

	// The same realm cannot describe somebody else's coin.
	uassert.AbortsContains(t, cur, "is issued by "+otherPath, func() {
		Register(cross(cur), otherCoin, "Not Mine", "NOPE", 0, "")
	})
}

func TestAUserAccountCannotRegister(cur realm, t *testing.T) {
	alice := testutils.TestAddress("nr-alice")
	testing.SetRealm(testing.NewUserRealm(alice))
	// Even for a denom she holds every unit of: what is being described is the
	// issuance, and a wallet has no package path to prove.
	uassert.AbortsContains(t, cur, "no package path to prove", func() {
		Register(cross(cur), issuerCoin, "Mine Now", "MINE", 0, "")
	})
}

func TestReregisteringBumpsRevisions(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewCodeRealm(issuerPath))
	before := Count()
	Register(cross(cur), issuerCoin, "Test Coin v2", "TEST2", 4, "renamed")

	e := MustGet(issuerCoin)
	uassert.Equal(t, "TEST2", e.Symbol, "an issuer can always re-describe its own coin")
	uassert.Equal(t, 1, e.Revisions)
	uassert.Equal(t, before, Count(), "a rewrite is not a second entry")
	uassert.Equal(t, 1, len(ByIssuer(issuerPath)))
	uassert.Equal(t, 0, len(ByIssuer(otherPath)))
}

func TestBounds(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewCodeRealm(issuerPath))
	uassert.AbortsContains(t, cur, "name is", func() {
		Register(cross(cur), issuerCoin, strings.Repeat("x", MaxName+1), "T", 0, "")
	})
	uassert.AbortsContains(t, cur, "symbol is", func() {
		Register(cross(cur), issuerCoin, "n", strings.Repeat("x", MaxSymbol+1), 0, "")
	})
	uassert.AbortsContains(t, cur, "doc is", func() {
		Register(cross(cur), issuerCoin, "n", "T", 0, strings.Repeat("x", MaxDoc+1))
	})
	uassert.AbortsContains(t, cur, "decimals is 19", func() {
		Register(cross(cur), issuerCoin, "n", "T", MaxDecimals+1, "")
	})
	uassert.AbortsContains(t, cur, "decimals is -1", func() {
		Register(cross(cur), issuerCoin, "n", "T", -1, "")
	})
}

func TestIssuerOfReadsTheDenom(cur realm, t *testing.T) {
	// The relation is in the string, so this answers for a denom nobody ever
	// registered, which is the case that matters: given a balance you did not
	// ask for, this is how you find the code that can take it away.
	uassert.Equal(t, "gno.land/r/nobody/here/v3", IssuerOf("/gno.land/r/nobody/here/v3:ghost"))
	uassert.Equal(t, issuerPath, IssuerOf(issuerCoin))

	uassert.PanicsContains(t, cur, "must start with /", func() { IssuerOf("ugnot") })
	uassert.PanicsContains(t, cur, "must contain :", func() { IssuerOf("/gno.land/r/a/v0") })
	uassert.PanicsContains(t, cur, "malformed", func() { IssuerOf("/gno.land/r/a/v0:") })
	uassert.PanicsContains(t, cur, "malformed", func() { IssuerOf("/:x") })
}

func TestUnregisteredReadsCleanly(cur realm, t *testing.T) {
	_, ok := Get("/gno.land/r/nobody/here/v3:ghost")
	uassert.False(t, ok)
	uassert.False(t, IsRegistered("/gno.land/r/nobody/here/v3:ghost"))
	uassert.PanicsContains(t, cur, "no entry for", func() { MustGet("/gno.land/r/x/y/v0:zz") })
}

func TestRender(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewCodeRealm(otherPath))
	Register(cross(cur), otherCoin, "Other Coin", "OTHER", 0, "the second one")

	index := Render("")
	uassert.True(t, strings.Contains(index, "# nativereg"), index)
	uassert.True(t, strings.Contains(index, "OTHER"), "the index lists entries:\n"+index)

	one := Render(otherCoin)
	uassert.True(t, strings.Contains(one, "the second one"), one)
	uassert.True(t, strings.Contains(one, otherPath), one)

	byIssuer := Render(issuerPath)
	uassert.True(t, strings.Contains(byIssuer, "TEST2"), byIssuer)
	uassert.False(t, strings.Contains(byIssuer, "OTHER"), "one issuer's page shows only its own")

	// A Render never aborts on a path a reader typed, registered or not.
	uassert.True(t, strings.Contains(Render("/gno.land/r/x/y/v0:nope"), "Not registered"))
	uassert.True(t, strings.Contains(Render("ugnot"), "registered nothing"),
		"a non-denom path falls through to the issuer view rather than aborting")
	uassert.True(t, strings.Contains(Render("/garbage"), "not a realm denom"))
}

func TestRenderEscapesWhatAnIssuerWrote(cur realm, t *testing.T) {
	// An issuer's own name and doc are still caller-supplied text, and a realm
	// that can register can write a table-breaking pipe as easily as a name.
	const nasty = "gno.land/r/test/nasty"
	testing.SetRealm(testing.NewCodeRealm(nasty))
	Register(cross(cur), "/gno.land/r/test/nasty:nastycoin", "a|b", "x|y", 0, "")

	index := Render("")
	uassert.False(t, strings.Contains(index, "| a|b |"), "a raw pipe would open a column:\n"+index)
	uassert.True(t, strings.Contains(index, "a\\|b"), "it is escaped instead:\n"+index)
}

package nativereg

import (
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Render lists the registry. `?<denom>` shows one entry, `?<pkgpath>` shows
// everything one realm issues.
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	if strings.HasPrefix(path, "/") {
		return renderDenom(path)
	}
	return renderIssuer(path)
}

func renderIndex() string {
	var sb strings.Builder
	sb.WriteString(md.H1("nativereg: what a native denom means"))
	sb.WriteString("\nA realm-issued coin is a string and a balance. The chain stores no name, " +
		"no symbol and no decimals for it, so this realm does. An issuer registers its own " +
		"denoms and nobody else's: the package path is embedded in the denom, and that is " +
		"the whole authorization.\n\n")

	t := ui.NewTable("denom", "symbol", "name", "decimals", "issuer")
	for _, e := range List() {
		t.Row(md.InlineCode(ui.ShortN(e.Denom, 22, 12)), ui.Cell(e.Symbol), ui.Cell(e.Name),
			ufmt.Sprintf("%d", e.Decimals), md.Link(ui.Short(e.Issuer), "/"+strings.TrimPrefix(e.Issuer, "gno.land/")))
	}
	sb.WriteString(md.H2("Registered"))
	sb.WriteString("\n" + t.OrEmpty("Nothing registered yet.") + "\n")

	sb.WriteString(md.H2("Register your own"))
	sb.WriteString("\nFrom inside the realm that issues the coin, never from a wallet:\n\n")
	sb.WriteString(md.LanguageCodeBlock("go",
		"import \"gno.land/r/moul/x/nativereg/v0\"\n\n"+
			"func init(cur realm) {\n"+
			"\tnativereg.Register(cross(cur), Denom, \"My Coin\", \"MINE\", 6,\n"+
			"\t\t\"one line about what it is for\")\n"+
			"}"))
	sb.WriteString("\n" + md.Italic("Decimals is a display hint. The bank counts whole units and "+
		"knows nothing about divisibility.") + "\n")
	return sb.String()
}

func renderDenom(denom string) string {
	e, ok := Get(denom)
	if !ok {
		return md.H1("Not registered") + "\n" + md.InlineCode(denom) +
			" has said nothing about itself.\n\nIts issuer is " +
			md.InlineCode(safeIssuer(denom)) + ", and only that realm can change it.\n"
	}

	t := ui.NewTable("", "")
	t.Row("denom", md.InlineCode(e.Denom))
	t.Row("issuer", md.InlineCode(e.Issuer))
	t.Row("name", ui.Cell(e.Name))
	t.Row("symbol", ui.Cell(e.Symbol))
	t.Row("decimals", ufmt.Sprintf("%d (display hint)", e.Decimals))
	t.Row("registered at block", ufmt.Sprintf("%d", e.Height))
	t.Row("revisions", ufmt.Sprintf("%d", e.Revisions))

	s := md.H1(ui.Inline(e.Symbol)) + "\n"
	if e.Doc != "" {
		s += ui.Inline(e.Doc) + "\n\n"
	}
	s += t.String() + "\n"
	s += md.Blockquote("The issuer can rewrite every row but the first two, and can remove "+
		"this coin from any balance at any time. That is what a realm-issued coin is.") + "\n"
	return s
}

func renderIssuer(pkgPath string) string {
	entries := ByIssuer(pkgPath)
	s := md.H1("Issued by "+ui.Inline(pkgPath)) + "\n"
	t := ui.NewTable("denom", "symbol", "name")
	for _, e := range entries {
		t.Row(md.InlineCode(ui.ShortN(e.Denom, 22, 12)), ui.Cell(e.Symbol), ui.Cell(e.Name))
	}
	return s + t.OrEmpty("This realm has registered nothing here.") + "\n"
}

// safeIssuer is IssuerOf for a Render, which must never abort on a path a reader
// typed into the URL bar.
func safeIssuer(denom string) string {
	if !strings.HasPrefix(denom, "/") {
		return "unknown (not a realm denom)"
	}
	i := strings.LastIndex(denom, ":")
	if i < 1 {
		return "unknown (not a realm denom)"
	}
	return denom[1:i]
}

// Package ns is a Plan 9 namespace server for gno.land.
//
// Every account gets a private, persistent namespace: its own RAM root plus a
// mount table it alone controls. Realms publish file trees into /srv, accounts
// bind those trees wherever they like, and a read-only rc shell renders the
// whole thing in gnoweb.
//
// This is the part of Plan 9 that gno does not otherwise have. The chain has a
// single global tree of realm paths that looks the same to everybody; here a
// name means what YOU bound it to. Composing two realms that were never
// written to work together stops being a redeploy and becomes a transaction:
//
//	gnokey maketx call -pkgpath gno.land/r/moul/x/plan9/ns/v1 -func Exec \
//	  -args 'bind -ac /srv/dev /dev; echo hello > /tmp/greeting'
//
// SECURITY. Mounted trees are READ-ONLY by construction: ninep.File has no
// mutating method, so grafting a foreign realm's tree into your namespace
// cannot be turned into a write against that realm. Writes only ever reach a
// memfs tree this realm created for you. A crossing write method would mint
// THIS realm's frame for the callee, which is the confused-deputy shape that
// r/gov/dao's Executor relies on deliberately and p/nt/grc20's Teller refuses
// deliberately; it is out of scope for v0. See moul/gno-contracts#136.
//
// NOTICE. Plan 9 from Bell Labs is the work of the Computing Science Research
// Center at Bell Labs; the name and the marks are theirs, and the copyright is
// held by the Plan 9 Foundation (https://p9f.org). This realm is not
// affiliated with, endorsed by, or sponsored by them, and contains no Plan 9
// code: it borrows the vocabulary so that the design reads without a glossary,
// and it is an homage, asking what that ecosystem's spirit looks like on a
// chain. Full attribution: NOTICE.md at the root of moul/gno-contracts.
package ns

import (
	"chain/runtime"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/realmpath/v0"

	memfs "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/plan9/memfs/v0"
	ninep "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/plan9/ninep/v0"
	nspkg "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/plan9/ns/v0"
	rc "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/plan9/rc/v0"
)

// DemoKey names the namespace gnoweb browses when no ?u= is given. It is a
// plain string rather than an address so it can never collide with one.
const DemoKey = "demo"

// The bounds on what callers can create. Any realm may Post a service and any
// account gets a namespace on its first Exec; the home page lists both.
const (
	MaxServices   = 64
	MaxNamespaces = 1000
	HomeRecent    = 50 // namespaces the home page lists
)

type service struct {
	file  ninep.File
	owner string  // pkgpath of the realm that posted it
	addr  address // that realm's address
	since int64   // block height of the posting
}

type space struct {
	fs *memfs.FS
	ns *nspkg.Ns
}

var (
	services = avl.NewTree() // name -> *service
	spaces   = avl.NewTree() // address string (or DemoKey) -> *space
)

func init() {
	seedDemo()
}

// ---------------------------------------------------------------- /srv

// srvDir is the synthetic directory that makes posted services reachable by
// name. It is written out by hand rather than built with synfs because its
// contents change as realms post, and because implementing ninep.File
// directly is meant to look easy: four methods, no state of its own.
type srvDir struct{}

func (d *srvDir) Stat() ninep.Stat {
	return ninep.Stat{
		Qid:   ninep.Qid{Type: ninep.QTDIR, Path: 1},
		Mode:  ninep.DMDIR | 0555,
		Mtime: runtime.ChainHeight(),
		Name:  "srv",
		Uid:   "sys",
		Gid:   "sys",
		Muid:  "sys",
	}
}

func (d *srvDir) Walk(name string) (ninep.File, error) {
	if !ninep.ValidName(name) {
		return nil, ninep.ErrBadName
	}
	v := services.Get(name)
	if v == nil {
		return nil, ninep.ErrNotExist
	}
	return v.(*service).file, nil
}

func (d *srvDir) Read(off, count int64) (string, error) { return "", ninep.ErrIsDir }

func (d *srvDir) ReadDir() ([]ninep.Stat, error) {
	out := []ninep.Stat{}
	services.Iterate("", "", func(k string, v any) bool {
		st := v.(*service).file.Stat()
		st.Name = k // the posted name, not whatever the server calls its root
		out = append(out, st)
		return false
	})
	return out, nil
}

var srvRoot = &srvDir{}

// ---------------------------------------------------------------- posting

// Post publishes a file tree under name in /srv, where any account can bind
// it. The posting realm is recorded and is the only one that may Unpost.
//
// Names are first come, first served, which is fine for an experiment and
// would not be for anything else.
func Post(cur realm, name string, f ninep.File) {
	if !cur.IsCurrent() {
		panic("post: cur is not the caller's live realm")
	}
	if !ninep.ValidName(name) {
		panic("post: " + ninep.ErrBadName.Error())
	}
	if f == nil {
		panic("post: nil file server")
	}
	prev := cur.Previous()
	if services.Get(name) == nil && services.Size() >= MaxServices {
		panic("post: /srv is full at " + strconv.Itoa(MaxServices) + " services")
	}
	if existing := services.Get(name); existing != nil {
		if existing.(*service).owner != prev.PkgPath() {
			panic("post: " + name + " is already posted by " + existing.(*service).owner)
		}
	}
	services.Set(name, &service{
		file:  f,
		owner: prev.PkgPath(),
		addr:  prev.Address(),
		since: runtime.ChainHeight(),
	})
}

// Unpost withdraws a service. Only the realm that posted it may do so.
func Unpost(cur realm, name string) {
	if !cur.IsCurrent() {
		panic("unpost: cur is not the caller's live realm")
	}
	v := services.Get(name)
	if v == nil {
		panic("unpost: " + ninep.ErrNotExist.Error())
	}
	if v.(*service).owner != cur.Previous().PkgPath() {
		panic("unpost: " + name + " belongs to " + v.(*service).owner)
	}
	services.Remove(name)
}

// Services lists the posted service names, in order.
func Services() []string {
	out := []string{}
	services.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

// ---------------------------------------------------------------- namespaces

// newSpace builds the default namespace, which is this chain's /lib/namespace:
// a private ram root, the mount points that Plan 9 requires to exist before
// anything can be bound onto them, /srv mounted, and /dev bound from it when a
// device server has been posted.
func newSpace(owner string) *space {
	now := runtime.ChainHeight()
	fs := memfs.New(owner, now)
	fs.MkdirAll("/srv", now)
	fs.MkdirAll("/dev", now)
	fs.MkdirAll("/tmp", now)

	n := nspkg.New(fs.Root())
	n.Mount(srvRoot, "#s", "/srv", nspkg.MREPL)
	if services.Has("dev") {
		n.Bind("/srv/dev", "/dev", nspkg.MREPL)
	}
	return &space{fs: fs, ns: n}
}

func spaceFor(key string) *space {
	if v := spaces.Get(key); v != nil {
		return v.(*space)
	}
	if spaces.Size() >= MaxNamespaces {
		panic("ns: full at " + strconv.Itoa(MaxNamespaces) + " namespaces")
	}
	sp := newSpace(key)
	spaces.Set(key, sp)
	return sp
}

func peek(key string) *space {
	if v := spaces.Get(key); v != nil {
		return v.(*space)
	}
	return nil
}

// seedDemo builds the namespace gnoweb shows by default. It is deliberately
// reproducible: an example test resets it before rendering.
func seedDemo() {
	spaces.Remove(DemoKey)
	sp := spaceFor(DemoKey)
	now := runtime.ChainHeight()
	sp.fs.WriteFile("/tmp/greeting", "hello from a namespace\n", now)
	sp.fs.MkdirAll("/usr/glenda/bin", now)
	sp.fs.WriteFile("/usr/glenda/bin/rc", "#!/bin/rc\n", now)
	sp.fs.MkdirAll("/bin", now)
	sp.fs.WriteFile("/bin/ls", "system ls\n", now)
	sp.ns.Bind("/usr/glenda/bin", "/bin", nspkg.MAFTER|nspkg.MCREATE)
	sp.ns.Cd("/usr/glenda")
}

// ResetDemo rebuilds the demo namespace. Anyone may call it: it is a demo, and
// the alternative is a demo that the first visitor ruins for everybody.
func ResetDemo(cur realm) {
	if !cur.IsCurrent() {
		panic("resetdemo: cur is not the caller's live realm")
	}
	seedDemo()
}

// ---------------------------------------------------------------- shell

// Exec runs a command line against the CALLER's namespace and returns its
// output. The namespace belongs to cur.Previous().Address(), so a user gets
// theirs and a realm gets its own.
//
// An error panics, so a half-applied command line reverts with the
// transaction rather than leaving a namespace nobody asked for.
func Exec(cur realm, line string) string {
	if !cur.IsCurrent() {
		panic("exec: cur is not the caller's live realm")
	}
	key := cur.Previous().Address().String()
	sp := spaceFor(key)
	sh := rc.New(sp.ns, rc.ReadWrite, runtime.ChainHeight)
	out, err := sh.Run(line)
	if err != nil {
		panic(err.Error())
	}
	return out
}

// Reset discards the caller's namespace, so the next use rebuilds the default.
func Reset(cur realm) {
	if !cur.IsCurrent() {
		panic("reset: cur is not the caller's live realm")
	}
	spaces.Remove(cur.Previous().Address().String())
}

// Run executes a READ-ONLY command line against key's namespace. It is the
// query side of Exec: no transaction, no writes, safe from Render.
func Run(key, line string) (string, error) {
	sp := peek(key)
	if sp == nil {
		return "", errors.New("no namespace for " + key)
	}
	sh := rc.New(sp.ns, rc.ReadOnly, runtime.ChainHeight)
	return sh.Run(line)
}

// Namespace returns key's mount table, in ns(1) format.
func Namespace(key string) string {
	sp := peek(key)
	if sp == nil {
		return ""
	}
	return sp.ns.String()
}

// Keys lists the namespaces that exist, in order.
func Keys() []string {
	out := []string{}
	spaces.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

// ---------------------------------------------------------------- render

// Render browses a namespace.
//
//	Render("")                  overview, posted services, how to drive it
//	Render("ns?u=<key>")        the mount table
//	Render("ls/bin?u=<key>")    a directory listing (ls -l)
//	Render("cat/tmp/greeting")  a file
//	Render("stat/bin")          the 9P stat, with the union width
//	Render("walk/bin/rc")       how each element of a path resolves
//	Render("rc?c=<command>")    any read-only rc command line
//
// ?u= selects the namespace; it defaults to the demo one.
func Render(path string) string {
	req := realmpath.Parse(path)
	key := req.Query.Get("u")
	if key == "" {
		key = DemoKey
	}
	// A namespace is keyed by the address that created it, or is the demo one.
	// Anything else names no namespace, and refusing it here is also what keeps
	// a crafted ?u= out of the links and code spans every page builds from it.
	if key != DemoKey && !address(key).IsValid() {
		return "# 404\n\nno namespace by that name. `?u=` takes an address.\n"
	}
	parts := req.PathParts()
	if len(parts) == 0 || parts[0] == "" {
		return renderHome(key)
	}

	cmd := parts[0]
	rest := "/" + strings.Join(parts[1:], "/")
	var line string
	switch cmd {
	case "ns":
		return renderCmd(key, "ns", "ns")
	case "ls":
		line = "ls -l " + quote(rest)
	case "cat":
		line = "cat " + quote(rest)
	case "stat":
		line = "stat " + quote(rest)
	case "walk":
		line = "walk " + quote(rest)
	case "rc":
		line = req.Query.Get("c")
		if line == "" {
			line = "help"
		}
	default:
		return "# 404\n\nunknown command " + md.InlineCode(cmd) + ". Try `ls`, `cat`, `stat`, `walk`, `ns` or `rc?c=...`.\n"
	}
	return renderCmd(key, line, cmd+" "+rest)
}

func renderCmd(key, line, title string) string {
	var b strings.Builder
	b.WriteString("# " + ui.Inline(title) + "\n\n")
	//gnovet:ignore render-path-in-code-span key is checked against address(key).IsValid() at the top of Render
	b.WriteString("namespace: `" + key + "`\n\n")
	out, err := Run(key, line)
	if err != nil {
		b.WriteString(md.CodeBlock(err.Error()))
	} else if out == "" {
		b.WriteString("_(no output)_\n")
	} else {
		// The output is a user's file contents: a line of backticks in it
		// would close a hand-written fence, and md.CodeBlock picks one it cannot.
		b.WriteString(md.CodeBlock(strings.TrimSuffix(out, "\n")))
	}
	b.WriteString("\n[namespace](/r/moul/x/plan9/ns/v1:ns?u=" + key + ") · [root](/r/moul/x/plan9/ns/v1:ls?u=" + key +
		") · [home](/r/moul/x/plan9/ns/v1)\n")
	return b.String()
}

func renderHome(key string) string {
	var b strings.Builder
	b.WriteString("# plan9: namespaces for gno\n\n")
	b.WriteString("A Plan 9 namespace server. Every account owns a private mount table over ")
	b.WriteString("[9P-shaped](https://9p.io/sys/doc/9.html) file trees: realms post trees ")
	b.WriteString("into `/srv`, you `bind` them where you want them, and a name means what ")
	b.WriteString("*you* bound it to.\n\n")

	b.WriteString("## /srv\n\n")
	if services.Size() == 0 {
		b.WriteString("_No service is posted yet._\n\n")
	} else {
		b.WriteString("| name | posted by | since |\n|---|---|---|\n")
		services.Iterate("", "", func(k string, v any) bool {
			s := v.(*service)
			//gnovet:ignore render-path-in-code-span owner is the creating caller address, recorded by the realm, not a path
			b.WriteString("| " + ui.Cell(k) + " | [`" + s.owner + "`](" +
				strings.TrimPrefix(s.owner, "gno.land") + ") | " +
				strconv.FormatInt(s.since, 10) + " |\n")
			return false
		})
		b.WriteString("\n")
	}

	b.WriteString("## The demo namespace\n\n")
	b.WriteString(md.CodeBlock(strings.TrimSuffix(Namespace(DemoKey), "\n")) + "\n")
	b.WriteString("`/bin` is a union: the system `/bin` first, then `/usr/glenda/bin`, ")
	b.WriteString("with `-c` so new files land in the second. Listing it shows both members ")
	b.WriteString("because a Plan 9 union is a concatenation, so shadowing stays visible.\n\n")
	b.WriteString("- [ns](/r/moul/x/plan9/ns/v1:ns) · [ls /](/r/moul/x/plan9/ns/v1:ls) · [ls /bin](/r/moul/x/plan9/ns/v1:ls/bin) · ")
	b.WriteString("[cat /tmp/greeting](/r/moul/x/plan9/ns/v1:cat/tmp/greeting) · [walk /bin/rc](/r/moul/x/plan9/ns/v1:walk/bin/rc)\n")
	b.WriteString("- any read-only command: [`rc?c=ls -l /srv`](/r/moul/x/plan9/ns/v1:rc?c=ls%20-l%20/srv)\n\n")

	b.WriteString("## Your own namespace\n\n")
	b.WriteString("```\n")
	b.WriteString("gnokey maketx call -pkgpath gno.land/r/moul/x/plan9/ns/v1 \\\n")
	b.WriteString("  -func Exec -args 'bind -ac /srv/dev /dev; echo hi > /tmp/f'\n")
	b.WriteString("```\n\n")
	b.WriteString("Then browse it with `?u=<your address>`. `Reset` throws it away.\n\n")

	b.WriteString("## Namespaces\n\n")
	keys := Keys()
	if len(keys) > HomeRecent {
		b.WriteString(strconv.Itoa(len(keys)) + " namespaces, the first " + strconv.Itoa(HomeRecent) + " listed.\n\n")
		keys = keys[:HomeRecent]
	}
	for _, k := range keys {
		b.WriteString("- [`" + k + "`](/r/moul/x/plan9/ns/v1:ns?u=" + k + ")\n")
	}
	b.WriteString("\nDesign and analysis: ")
	b.WriteString("[moul/gno-contracts#136](https://github.com/moul/gno-contracts/issues/136).\n")
	b.WriteString("\n_Not affiliated with Plan 9. Plan 9 from Bell Labs is the ")
	b.WriteString("work of the Computing Science Research Center at Bell Labs; the name ")
	b.WriteString("and the marks are theirs, and the copyright is held by the ")
	b.WriteString("[Plan 9 Foundation](https://p9f.org). This realm borrows the ")
	b.WriteString("vocabulary and none of the code: it is an homage, asking what that ")
	b.WriteString("ecosystem's spirit looks like on a chain._\n")
	return b.String()
}

// quote wraps a path for rc if it needs it.
func quote(s string) string {
	// Always quoted: the path comes from the URL, and a route like
	// cat/tmp/f;echo must read one file, not run a second command. The shell
	// is read-only either way, but a path is data.
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

package ns

import (
	"strconv"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"

	ninep "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/plan9/ninep/v0"
	synfs "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/plan9/synfs/v0"
)

// probe is a tiny read-only server, standing in for another realm's tree.
func probe(name, contents string) ninep.File {
	t := synfs.New(name, "sys", func() int64 { return 1 })
	t.Root().Add("value", func() string { return contents })
	return t.Root()
}

func TestDemoNamespaceIsSeeded(t *testing.T) {
	seedDemo()
	out, err := Run(DemoKey, "ls -u /bin")
	if err != nil {
		t.Fatalf("ls: %v", err)
	}
	if out != "ls\nrc\n" {
		t.Errorf("the demo /bin should be a union of two directories: %q", out)
	}
	if got := Namespace(DemoKey); !strings.Contains(got, "bind -ac /usr/glenda/bin /bin") {
		t.Errorf("mount table: %q", got)
	}
	if got, _ := Run(DemoKey, "cat /tmp/greeting"); got != "hello from a namespace\n" {
		t.Errorf("greeting: %q", got)
	}
}

func TestRunIsReadOnly(t *testing.T) {
	seedDemo()
	if _, err := Run(DemoKey, "echo x > /tmp/f"); err == nil {
		t.Fatal("Render's shell must refuse a write")
	}
	if _, err := Run(DemoKey, "rm /tmp/greeting"); err == nil {
		t.Fatal("Render's shell must refuse a remove")
	}
	if _, err := Run("nobody", "ls /"); err == nil {
		t.Fatal("an unknown namespace should not be created by a read")
	}
}

func TestPostAndBind(cur realm, t *testing.T) {
	services.Remove("probe")
	Post(cross(cur), "probe", probe("probe", "42"))

	found := false
	for _, s := range Services() {
		if s == "probe" {
			found = true
		}
	}
	if !found {
		t.Fatalf("probe is not in /srv: %v", Services())
	}

	// A fresh namespace sees it through /srv without importing anything.
	spaces.Remove("tester")
	spaceFor("tester")
	defer spaces.Remove("tester")
	out, err := Run("tester", "cat /srv/probe/value")
	if err != nil {
		t.Fatalf("cat through /srv: %v", err)
	}
	if out != "42" {
		t.Errorf("got %q, want 42", out)
	}
	services.Remove("probe")
}

func TestExecWritesToTheCallersOwnNamespace(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")
	spaces.Remove(alice.String())
	spaces.Remove(bob.String())

	testing.SetRealm(testing.NewUserRealm(alice))
	Exec(cross(cur), "echo 'alice was here' > /tmp/note")

	testing.SetRealm(testing.NewUserRealm(bob))
	Exec(cross(cur), "echo 'bob was here' > /tmp/note")

	got, err := Run(alice.String(), "cat /tmp/note")
	if err != nil {
		t.Fatalf("alice: %v", err)
	}
	if got != "alice was here\n" {
		t.Errorf("alice's namespace: %q", got)
	}
	if got, _ = Run(bob.String(), "cat /tmp/note"); got != "bob was here\n" {
		t.Errorf("bob's namespace: %q", got)
	}

	// Reset throws a namespace away; the next use rebuilds the default.
	testing.SetRealm(testing.NewUserRealm(alice))
	Reset(cross(cur))
	if _, err := Run(alice.String(), "cat /tmp/note"); err == nil {
		t.Error("the namespace should be gone after Reset")
	}
	spaces.Remove(alice.String())
	spaces.Remove(bob.String())
}

func TestExecBindsIntoTheCallersNamespace(cur realm, t *testing.T) {
	services.Remove("probe")
	Post(cross(cur), "probe", probe("probe", "42"))
	defer services.Remove("probe")

	erin := testutils.TestAddress("erin")
	spaces.Remove(erin.String())
	testing.SetRealm(testing.NewUserRealm(erin))
	Exec(cross(cur), "bind /srv/probe /dev")

	if got := mustRun(t, erin.String(), "cat /dev/value"); got != "42" {
		t.Errorf("read through the mount: %q", got)
	}
	if ns := Namespace(erin.String()); !strings.Contains(ns, "bind /srv/probe /dev") {
		t.Errorf("mount table: %q", ns)
	}
	spaces.Remove(erin.String())
}

func TestSrvListingUsesThePostedName(cur realm, t *testing.T) {
	services.Remove("aliased")
	// The server calls its own root "probe"; /srv must show it as "aliased".
	Post(cross(cur), "aliased", probe("probe", "x"))
	defer services.Remove("aliased")

	spaces.Remove("lister")
	spaceFor("lister")
	out := mustRun(t, "lister", "ls /srv")
	if !strings.Contains(out, "aliased") {
		t.Errorf("ls /srv: %q", out)
	}
	if strings.Contains(out, "probe") {
		t.Errorf("/srv leaked the server's own root name: %q", out)
	}
	spaces.Remove("lister")
}

func mustRun(t *testing.T, key, line string) string {
	t.Helper()
	out, err := Run(key, line)
	if err != nil {
		t.Fatalf("%s: %v", line, err)
	}
	return out
}

// --- the boundary. Three properties the suite would be unsafe without. -------

// A /srv name belongs to the realm that posted it: first come, first served,
// and then locked.
func TestPostRejectsASecondOwner(cur realm, t *testing.T) {
	services.Remove("taken")
	Post(cross(cur), "taken", probe("taken", "first"))
	defer services.Remove("taken")

	testing.SetRealm(testing.NewCodeRealm("gno.land/r/other/thing/v0"))
	uassert.AbortsWithMessage(t, cur,
		"post: taken is already posted by gno.land/r/moul/x/plan9/ns/v1",
		func() { Post(cross(cur), "taken", probe("taken", "second")) })
}

// Grafting another realm's tree into your namespace gives you reads and
// nothing else. ninep.File has no mutating method, so there is no route from a
// mount to a write against the realm that posted it.
func TestMountedTreesAreReadOnly(cur realm, t *testing.T) {
	services.Remove("probe")
	Post(cross(cur), "probe", probe("probe", "read me"))
	defer services.Remove("probe")

	frank := testutils.TestAddress("frank")
	spaces.Remove(frank.String())
	defer spaces.Remove(frank.String())

	testing.SetRealm(testing.NewUserRealm(frank))
	Exec(cross(cur), "bind /srv/probe /dev")
	uassert.Equal(t, "read me", mustRun(t, frank.String(), "cat /dev/value"))
	uassert.AbortsWithMessage(t, cur, "echo: read-only file server",
		func() { Exec(cross(cur), "echo nope > /dev/value") })
}

// A command line stops at the first error and the error leaves the realm as an
// abort, so a half-applied Exec reverts with its transaction instead of
// leaving a namespace nobody asked for.
func TestExecAbortsAtTheFirstError(cur realm, t *testing.T) {
	grace := testutils.TestAddress("grace")
	spaces.Remove(grace.String())
	defer spaces.Remove(grace.String())

	testing.SetRealm(testing.NewUserRealm(grace))
	uassert.AbortsWithMessage(t, cur, "cat: file does not exist",
		func() { Exec(cross(cur), "echo ok > /tmp/a; cat /absent; echo never > /tmp/b") })
}

func TestRenderUnknownCommand(t *testing.T) {
	if got := Render("nope/x"); !strings.Contains(got, "404") {
		t.Errorf("got %q", got)
	}
}

// ?u= is the only caller-controlled part of every link the pages build, so a
// value that is neither an address nor the demo key is refused outright.
func TestRenderRefusesANonAddressNamespace(t *testing.T) {
	out := Render("ns?u=x%29%20[evil](https://example)")
	uassert.True(t, strings.Contains(out, "# 404"), out)
	uassert.False(t, strings.Contains(out, "[evil](https://example)"), out)
}

// A file's contents are its owner's text. A line of backticks in one used to
// close the hand-written fence around `cat`'s output, and everything after it
// rendered as live markdown on the realm's own page.
func TestCatOutputCannotCloseItsFence(cur realm, t *testing.T) {
	who := testutils.TestAddress("fencer")
	testing.SetRealm(testing.NewUserRealm(who))
	Exec(cross(cur), "echo '```' > /tmp/f; echo '[claim](https://evil.example)' >> /tmp/f")
	out := Render("cat/tmp/f?u=" + who.String())
	// md.CodeBlock picks a fence longer than any run of backticks inside, so
	// the user's three backticks and the link after them stay inside the block.
	uassert.True(t, strings.Contains(out, "````\n```\n[claim](https://evil.example)\n````\n"), out)
}

// The command name and the rest of the path come from the URL: escaped in the
// heading and in the unknown-command page.
func TestPathDerivedTextIsEscaped(t *testing.T) {
	for _, path := range []string{"x` [claim](https://evil.example) `", "cat/x` [claim](https://evil.example) `"} {
		out := Render(path)
		uassert.False(t, strings.Contains(out, "[claim](https://evil.example)"), out)
	}
}

// A service name is chosen by whichever realm posts it, and ValidName refuses
// only "", ".", ".." and "/": the /srv table escapes it as a cell.
func TestServiceNameIsTableSafe(cur realm, t *testing.T) {
	name := "x` | [claim](https://evil.example) |"
	services.Set(name, &service{owner: "gno.land/r/someone/poster"})
	defer services.Remove(name)
	out := Render("")
	uassert.False(t, strings.Contains(out, "[claim](https://evil.example)"), out)
}

// A path route reads what it names: the rest of the path is one quoted
// argument, so a ";" in it is part of the file name and runs nothing.
func TestPathRouteIsOneArgument(t *testing.T) {
	// Unquoted, rc would cat /tmp/greeting and then run the second command;
	// quoted, it looks for one file with a ";" in its name and finds none.
	out := Render("cat/tmp/greeting;echo")
	uassert.True(t, strings.Contains(out, "cat: file does not exist"), out)
	uassert.Equal(t, "'/a;b'", quote("/a;b"))
}

// Namespaces and services are bounded, and the home page lists a fixed number.
func TestNamespacesAndServicesAreBounded(cur realm, t *testing.T) {
	var added []string
	for i := 0; spaces.Size() < MaxNamespaces; i++ {
		k := testutils.TestAddress("ns" + strconv.Itoa(i)).String()
		if spaces.Get(k) == nil {
			spaces.Set(k, newSpace(k))
			added = append(added, k)
		}
	}
	defer func() {
		for _, k := range added {
			spaces.Remove(k)
		}
	}()
	uassert.PanicsContains(t, cur, "full at", func() { spaceFor(testutils.TestAddress("one-more").String()) })
	uassert.Equal(t, HomeRecent, strings.Count(Render(""), "](/r/moul/x/plan9/ns/v1:ns?u="))
}

// /srv is bounded: once MaxServices names are posted, a new one is refused,
// and re-posting is not how a realm gets around it.
func TestServicesAreBounded(cur realm, t *testing.T) {
	var added []string
	for i := 0; services.Size() < MaxServices; i++ {
		name := "svc" + strconv.Itoa(i)
		if services.Get(name) == nil {
			services.Set(name, &service{owner: "gno.land/r/someone/poster"})
			added = append(added, name)
		}
	}
	defer func() {
		for _, n := range added {
			services.Remove(n)
		}
	}()
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/someone/late"))
	uassert.AbortsContains(t, cur, "/srv is full", func() { Post(cross(cur), "late", probe("late", "x")) })
}

package ns

