package reaper

import (
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/storagecost/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Every Example in this file is a *query*, and that is a constraint rather
// than a choice: an example function takes no arguments, so it never receives
// a `cur realm` and can never call Post, Reap or Compact. What is left is
// exactly the surface a reader of the live realm has without a key, so each
// one carries the `vm/qeval` line that produces the same answer on chain:
//
//	gnokey query vm/qeval -remote https://rpc.gno.land \
//	  -data 'gno.land/r/moul/x/reaper/v0.<expr>'
//
// The board is empty by the time these run, because every Test in this
// package drains what it posted and examples run after all of them.

// ExampleRender pins the page's skeleton: the title, the two sections that are
// always present, and the footer crediting the two packages that own the parts
// this realm does not.
//
//	vm/qrender  gno.land/r/moul/x/reaper/v0:
//
// It deliberately prints only the invariant lines. Everything interesting on
// the page is priced from the current block height and the notes outstanding,
// and an Example runs after every Test in the package and sees whatever state
// they left. The variable half is pinned by TestRenderShowsTheBountyAndTheReapLink
// instead, which controls the board first.
func ExampleRender() {
	for _, line := range strings.Split(Render(""), "\n") {
		switch {
		case strings.HasPrefix(line, "# "),
			strings.HasPrefix(line, "## "),
			strings.HasPrefix(line, "A noticeboard"),
			strings.HasPrefix(line, "The arithmetic is"):
			print(line + "\n")
		}
	}
	// Output:
	// # Reaper
	// A noticeboard whose garbage is a standing bounty. Posting a note locks a storage deposit. Once the note expires, anyone can delete it and the chain refunds that deposit **to whoever signs the deleting transaction**.
	// ## On the table right now
	// ## Board
	// The arithmetic is [p/moul/x/storagecost](/p/moul/x/storagecost/v0); the storage is [p/moul/ulist](/p/moul/ulist/v1), whose `Compact` reclaims dead nodes without moving a live index. Byte figures on this page are estimates from payload length: no stdlib call exposes a realm's real locked storage.
}

// ExampleReapable is the poll a reaping bot runs before it spends anything:
// three counters, three queries, no key and no gas.
//
//	vm/qeval  gno.land/r/moul/x/reaper/v0.Live()
//	vm/qeval  gno.land/r/moul/x/reaper/v0.Reapable()
//	vm/qeval  gno.land/r/moul/x/reaper/v0.Compactable()
//
// Reapable and Compactable are separate numbers because reaping and
// compacting are separate transactions, and compaction returns nothing at all
// while a live note still sits below the dead ones. A bot that sees
// `reapable 0, compactable 0` should not sign anything, which is the answer
// here.
func ExampleReapable() {
	print(ufmt.Sprintf("live %d, reapable %d, compactable %d\n",
		Live(), Reapable(), Compactable()))
	// Output:
	// live 0, reapable 0, compactable 0
}

// ExampleBounty is the single query that decides whether reaping is worth
// doing, and on an empty board it has to refuse to advertise a profit.
//
//	vm/qeval  gno.land/r/moul/x/reaper/v0.Bounty().String()
//
// Fee is what the reaping transaction costs at the floor gas price, and the
// chain charges it whether or not anything is freed. BreakEven turns that fee
// back into bytes: free fewer than 50 and the reaper is paying to tidy up.
// That threshold, not the size of the board, is what makes the mechanism a
// market rather than a chore.
func ExampleBounty() {
	print(Bounty().String() + "\n")
	// Output:
	// 0 bytes, refunds 0 GNOT against 0.005 GNOT of gas, break-even 50 bytes: not worth it yet
}

// ExampleBounty_worth is the same query answered by a board worth draining:
// ten expired notes of a kilobyte each.
//
// It recomputes the quote instead of posting, because an example has no
// `cur realm` to post with. The arithmetic is the one Bounty applies, so the
// numbers are the ones the live query would return with that board on it.
//
// This is the whole concept in two lines. The poster locked 1.8944 GNOT to
// occupy that space; a stranger who never posted anything spends 0.005 GNOT of
// gas to delete it and the chain hands them the deposit. Nobody minted a
// token, and no pool was funded.
func ExampleBounty_worth() {
	q := storagecost.EvaluateAtFloor(storagecost.EstimateBytes(10*1024), gasWantedReap)
	print(q.String() + "\n")
	print(ufmt.Sprintf("the reaper is paid %dx what the transaction costs\n", q.Refund/q.Fee))
	// Output:
	// 18944 bytes, refunds 1.8944 GNOT against 0.005 GNOT of gas, break-even 50 bytes: worth 1.8894 GNOT
	// the reaper is paid 378x what the transaction costs
}

// Package reaper is a noticeboard whose garbage is a standing bounty.
//
// Anyone can post a note with an expiry. Posting locks a storage deposit, paid
// by the poster. Once a note expires, anyone at all can delete it, and the
// chain refunds that deposit to whoever signed the deleting transaction. So
// the poster pays to occupy space and a stranger is paid to reclaim it.
//
// Nothing here is a token, a reward pool or an emission schedule. The incentive
// is the chain's own storage accounting, which already works this way for every
// realm on gno.land; this realm only makes it legible. Reap and Compact are
// permissionless because the expiry predicate is checked on chain, so the
// worst a malicious reaper can do is waste their own gas.
//
// Two collaborators own the parts this realm does not:
//
//   - gno.land/p/moul/ulist/v1 stores the notes and owns compaction. Its
//     Delete is a soft delete that leaves a dead tree node behind, and its
//     Compact frees those nodes without moving any live index.
//   - gno.land/p/moul/x/storagecost/v0 owns the arithmetic: what a byte
//     refunds, and how many bytes a transaction must free to pay for itself.
//   - gno.land/p/moul/kit/ui/v0 owns display: the escaping, the length cap
//     and the address format. A note body is arbitrary bytes chosen by
//     whoever paid to post it and is rendered back to every reader, so it is
//     attacker-controlled input in a markdown slot. Render never emits a body
//     unescaped; ui.Excerpt is what makes that true, and it delegates to
//     p/nt/markdown/sanitize.
//
// The realm deliberately cannot see its own byte count. No stdlib call exposes
// a realm's locked storage, so every figure Render shows is an estimate from
// payload length. The authoritative numbers are the chain's, in the
// StorageDepositEvent and StorageUnlockEvent each transaction emits.
package reaper

import (
	"strings"

	"chain/runtime"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/ulist/v1"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/storagecost/v0"
	"gno.land/p/nt/ufmt/v0"
)

// gasWantedReap is the gas ceiling a reaping transaction is assumed to ask
// for, used only to price the advertised bounty. It is the measured cost of a
// ten-note reap rounded up; a caller reaping more notes should re-price with
// storagecost.EvaluateAtFloor directly rather than trust this.
const gasWantedReap int64 = 5_000_000

// maxBody caps a note so one poster cannot lock an unbounded deposit in a
// single call, which would also make the gas cost of reaping it unpredictable.
const maxBody = 4096

// Note is one posting. Body is what costs storage; the rest is bookkeeping
// that makes the incentive visible in Render.
type Note struct {
	Body    string
	Author  address
	Posted  int64 // block height
	Expires int64 // block height; reapable once ChainHeight passes it
}

// notes is append-addressed: an index is stable for the life of the realm,
// which is what lets Compact reclaim dead nodes without renumbering.
var notes = ulist.New()

// Post adds a note that becomes reapable ttl blocks from now, and locks the
// storage deposit for it against the caller.
//
// A ttl of zero is allowed and makes the note reapable immediately, which is
// the cheapest way to demonstrate the mechanism.
func Post(cur realm, body string, ttl int64) int {
	if body == "" {
		panic("reaper: empty note")
	}
	if len(body) > maxBody {
		panic(ufmt.Sprintf("reaper: note too long, %d bytes against a %d cap", len(body), maxBody))
	}
	if ttl < 0 {
		panic("reaper: negative ttl")
	}
	height := runtime.ChainHeight()
	notes.Append(&Note{
		Body:    body,
		Author:  cur.Previous().Address(),
		Posted:  height,
		Expires: height + ttl,
	})
	return notes.TotalSize() - 1
}

// Reap deletes up to limit expired notes and returns how many it deleted.
//
// Permissionless by design. The storage deposit freed goes to whoever signed
// this transaction, so a stranger keeping the board tidy is paid for it out of
// the deposits the posters locked. A note that has not expired is skipped, not
// refused, so a reaper never has to guess which indices are ripe.
//
// It walks from the highest index down, which is not cosmetic. In the backing
// list the oldest indices are the ancestors of the newest, so a node can only
// be freed once everything below it is dead. Reaping oldest-first with a
// binding limit therefore never creates a dead tail and leaves Compactable at
// zero, stranding the tree structure, which measures at roughly two thirds of
// what an entry costs. Reaping newest-first makes each batch immediately
// compactable. Every candidate is expired either way, so the order changes
// only who gets paid how much, and it is measured: see the ulist package doc.
func Reap(cur realm, limit int) int {
	if limit <= 0 {
		panic("reaper: limit must be positive")
	}
	height := runtime.ChainHeight()
	reaped := 0
	for i := notes.TotalSize() - 1; i >= 0 && reaped < limit; i-- {
		n, ok := noteAt(i)
		if !ok || n.Expires > height {
			continue
		}
		notes.MustDelete(i)
		reaped++
	}
	return reaped
}

// Compact frees the tree nodes that reaping left behind and returns how many.
//
// Also permissionless, and also paid the same way. It is a separate call
// because it is a separate economic decision, and a surprisingly large one: on
// chain, compacting a drained board returned about three times what deleting
// the notes themselves did, because a list node costs more than the note it
// carries. But it returns nothing at all while any live note sits below the
// dead ones, so the two calls are worth batching in that order: reap, then
// compact. Compactable says how much is actually there, for free.
func Compact(cur realm) int {
	return notes.Compact()
}

// Reapable counts the notes that have expired and not yet been reaped.
func Reapable() int {
	height := runtime.ChainHeight()
	count := 0
	total := notes.TotalSize()
	for i := 0; i < total; i++ {
		n, ok := noteAt(i)
		if ok && n.Expires <= height {
			count++
		}
	}
	return count
}

// Compactable reports how many dead tree nodes a Compact would free.
func Compactable() int { return notes.Compactable() }

// Live counts the notes still holding storage.
func Live() int { return notes.Size() }

// Bounty prices what is currently on the table for a reaper, at the default
// storage price and the floor gas price.
//
// The byte figure is an estimate from payload length, never the chain's own
// accounting. Treat it as an advertisement, not a settlement.
func Bounty() storagecost.Quote {
	height := runtime.ChainHeight()
	var payload int64
	total := notes.TotalSize()
	for i := 0; i < total; i++ {
		n, ok := noteAt(i)
		if ok && n.Expires <= height {
			payload += int64(len(n.Body))
		}
	}
	return storagecost.EvaluateAtFloor(storagecost.EstimateBytes(payload), gasWantedReap)
}

// noteAt reads index i, reporting whether a live note is there. A reaped or
// compacted index reads as absent.
func noteAt(i int) (*Note, bool) {
	v := notes.Get(i)
	if v == nil {
		return nil, false
	}
	n, ok := v.(*Note)
	return n, ok
}

func Render(path string) string {
	var b strings.Builder

	b.WriteString(md.H1("Reaper"))
	b.WriteString("\nA noticeboard whose garbage is a standing bounty. Posting a note locks a storage deposit. Once the note expires, anyone can delete it and the chain refunds that deposit **to whoever signs the deleting transaction**.\n\n")

	quote := Bounty()
	b.WriteString(md.H2("On the table right now"))
	b.WriteString("\n")

	reapable := Reapable()
	if reapable == 0 {
		b.WriteString("Nothing has expired. Every note here is still paid for.\n\n")
	} else {
		b.WriteString(md.BulletList([]string{
			ufmt.Sprintf("**%d expired notes**, about %d bytes of state", reapable, quote.Bytes),
			ufmt.Sprintf("refunds roughly **%s** to the reaper", storagecost.FormatGNOT(quote.Refund)),
			ufmt.Sprintf("against **%s** of gas at the floor price, break-even at %d bytes", storagecost.FormatGNOT(quote.Fee), quote.BreakEven),
			ufmt.Sprintf("verdict: **%s**", verdictWord(quote)),
		}))
		b.WriteString("\n")
		b.WriteString(ui.Action("Reap them", "Reap", "limit", "100") + "\n\n")
	}

	if dead := Compactable(); dead > 0 {
		b.WriteString(md.H2("Compaction available"))
		b.WriteString(ufmt.Sprintf("\n%d dead tree nodes are reclaimable. Compacting frees fewer bytes per unit of gas than reaping does, so it is worth doing in batches.\n\n%s\n\n",
			dead, ui.Action("Compact", "Compact")))
	}

	b.WriteString(md.H2("Board"))
	b.WriteString("\n")
	if notes.Size() == 0 {
		b.WriteString("Empty. " + ui.Action("Post the first note", "Post", "body", "hello", "ttl", "0") + "\n\n")
	} else {
		height := runtime.ChainHeight()
		rows := []string{}
		total := notes.TotalSize()
		for i := 0; i < total; i++ {
			n, ok := noteAt(i)
			if !ok {
				continue
			}
			state := ufmt.Sprintf("expires at %d", n.Expires)
			if n.Expires <= height {
				state = "**reapable**"
			}
			rows = append(rows, ufmt.Sprintf("`#%d` %s | %d bytes by %s, %s",
				i, summarize(n.Body), len(n.Body), ui.Addr(n.Author), state))
		}
		b.WriteString(md.BulletList(rows))
		b.WriteString("\n")
	}

	b.WriteString(md.HorizontalRule())
	b.WriteString("\nThe arithmetic is [p/moul/x/storagecost](/p/moul/x/storagecost/v0); the storage is [p/moul/ulist](/p/moul/ulist/v1), whose `Compact` reclaims dead nodes without moving a live index. Byte figures on this page are estimates from payload length: no stdlib call exposes a realm's real locked storage.\n")

	return b.String()
}

func verdictWord(q storagecost.Quote) string {
	if q.Worth() {
		return "worth " + storagecost.FormatGNOT(q.Net)
	}
	return "not worth the gas yet"
}

// summarize is the board's one-line view of a note.
//
// A body is whatever bytes a poster paid to store, so on the board it is
// attacker-controlled input in an inline markdown slot. ui.Excerpt owns both
// halves of that: the rune-boundary cut and the escaping, in the order that is
// safe. This realm shipped a hand-rolled version that did neither, and the
// replacement for it is one call.
func summarize(body string) string {
	const width = 48
	// Cosmetic, not a defense: "|" is the column separator of the row this
	// lands in. The escaper deliberately leaves pipes literal, which is right,
	// since a lone pipe cannot open a GFM table with no delimiter row.
	return ui.Excerpt(strings.ReplaceAll(body, "|", " "), width)
}

package reaper

import (
	"strings"
	"testing"
	"unicode/utf8"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/storagecost/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	poster = testutils.TestAddress("poster")
	// stranger never posts, it only deletes. The whole point of the realm is
	// that this is the address the chain pays.
	stranger = testutils.TestAddress("stranger")
)

// ttlFuture is the ttl used for a note that must not be reapable yet. It is a
// named constant because clear has to outrun it.
const ttlFuture = 1000

// clear empties the board so a test starts from a known state, whatever ran
// before it.
//
// gno resets the block height for each test function but keeps realm state, so
// a test that left an unexpired note behind cannot be cleaned up by a later
// test skipping heights: the later test's clock starts over. Every test that
// posts a future-dated note therefore drains it before returning, and clear
// asserts an empty board rather than trusting that.
//
// clear cannot reset TotalSize, which is append-addressed for the life of the
// realm, so tests assert on Live and Reapable and never on absolute indices.
func clear(cur realm, t *testing.T) {
	t.Helper()
	drain(cur)
	uassert.Equal(t, 0, Live())
	uassert.Equal(t, 0, Reapable())
}

// drain expires everything outstanding and reaps it.
func drain(cur realm) {
	testing.SkipHeights(ttlFuture + 1)
	testing.SetRealm(testing.NewUserRealm(stranger))
	for Reapable() > 0 {
		Reap(cross(cur), 1000)
	}
	Compact(cross(cur))
}

func TestPostLocksAndReapFrees(cur realm, t *testing.T) {
	clear(cur, t)

	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), "first", 0)
	Post(cross(cur), "second", 0)
	uassert.Equal(t, 2, Live())
	uassert.Equal(t, 2, Reapable())

	// A stranger who posted nothing may reap, and that is the point.
	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 2, Reap(cross(cur), 100))
	uassert.Equal(t, 0, Live())
	uassert.Equal(t, 0, Reapable())
}

func TestReapSkipsUnexpiredAndHonoursLimit(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))

	Post(cross(cur), "ripe one", 0)
	Post(cross(cur), "ripe two", 0)
	Post(cross(cur), "not yet", ttlFuture)
	uassert.Equal(t, 3, Live())
	uassert.Equal(t, 2, Reapable())

	// The limit caps the work, so a reaper can size a transaction to its gas.
	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 1, Reap(cross(cur), 1))
	uassert.Equal(t, 1, Reapable())

	// The unexpired note survives a reap that asks for everything.
	uassert.Equal(t, 1, Reap(cross(cur), 100))
	uassert.Equal(t, 0, Reapable())
	uassert.Equal(t, 1, Live())

	// Leave nothing behind: the next test's height starts over and could not
	// expire this note.
	drain(cur)
}

func TestReapOfNothingIsNotAnError(cur realm, t *testing.T) {
	clear(cur, t)
	// A bot that races another bot to the same notes must not revert, or it
	// loses its gas to an abort instead of merely earning nothing.
	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 0, Reap(cross(cur), 100))
}

func TestCompactFollowsReaping(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	for i := 0; i < 8; i++ {
		Post(cross(cur), "note", 0)
	}

	// Nothing is reclaimable until something has been reaped.
	uassert.Equal(t, 0, Compactable())

	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 8, Reap(cross(cur), 100))
	uassert.True(t, Compactable() > 0)

	freed := Compact(cross(cur))
	uassert.True(t, freed > 0)
	uassert.Equal(t, 0, Compactable())
	// Compacting twice is not an error, it just frees nothing.
	uassert.Equal(t, 0, Compact(cross(cur)))
}

func TestPostRejectsBadInput(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))

	uassert.AbortsWithMessage(t, cur, "reaper: empty note", func() {
		Post(cross(cur), "", 0)
	})
	uassert.AbortsWithMessage(t, cur, "reaper: negative ttl", func() {
		Post(cross(cur), "fine", -1)
	})
	// The cap keeps one call from locking an unbounded deposit.
	uassert.AbortsWithMessage(t, cur, "reaper: note too long, 4097 bytes against a 4096 cap", func() {
		Post(cross(cur), strings.Repeat("x", maxBody+1), 0)
	})
	uassert.AbortsWithMessage(t, cur, "reaper: limit must be positive", func() {
		Reap(cross(cur), 0)
	})
}

func TestBountyPricesWhatIsOnTheTable(cur realm, t *testing.T) {
	clear(cur, t)

	// An empty board advertises nothing, and must not claim a profit.
	empty := Bounty()
	uassert.Equal(t, int64(0), empty.Bytes)
	uassert.Equal(t, int64(0), empty.Refund)
	uassert.False(t, empty.Worth())

	testing.SetRealm(testing.NewUserRealm(poster))
	body := strings.Repeat("x", 1024)
	for i := 0; i < 10; i++ {
		Post(cross(cur), body, 0)
	}

	// Ten 1 KB notes, priced through the same estimate the library documents.
	q := Bounty()
	uassert.Equal(t, storagecost.EstimateBytes(10*1024), q.Bytes)
	uassert.Equal(t, storagecost.Refund(q.Bytes, storagecost.DefaultStoragePrice), q.Refund)
	uassert.True(t, q.Worth())

	// Once reaped, nothing is on the table.
	testing.SetRealm(testing.NewUserRealm(stranger))
	Reap(cross(cur), 100)
	uassert.Equal(t, int64(0), Bounty().Bytes)
}

func TestRenderShowsTheBountyAndTheReapLink(cur realm, t *testing.T) {
	clear(cur, t)

	// Empty board: an invitation, and no bounty claimed.
	out := Render("")
	uassert.True(t, strings.Contains(out, "# Reaper"), out)
	uassert.True(t, strings.Contains(out, "Nothing has expired"), out)
	uassert.True(t, strings.Contains(out, "Post the first note"), out)

	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), strings.Repeat("y", 1024), 0)

	out = Render("")
	uassert.True(t, strings.Contains(out, "1 expired notes"), out)
	uassert.True(t, strings.Contains(out, "refunds roughly **0.1894 GNOT**"), out)
	// The reap link must be a help link for the right function with the right
	// argument, or the button on the page does nothing useful. txlink builds
	// it relative to the current realm, so there is no path to get wrong.
	uassert.True(t, strings.Contains(out, "$help&func=Reap&limit=100"), out)
	// The author is named, in the house address format, which is what makes
	// "the poster paid" visible without 40 opaque characters per row.
	uassert.True(t, strings.Contains(out, ui.Addr(poster)), out)
	uassert.True(t, strings.Contains(out, "**reapable**"), out)

	// A long note is summarized rather than dumped into the table.
	uassert.True(t, strings.Contains(out, ui.Ellipsis), out)
	uassert.False(t, strings.Contains(out, strings.Repeat("y", 200)), "body should be truncated")
}

func TestRenderNeverEmitsTwoBlankLines(cur realm, t *testing.T) {
	// gno collapses two consecutive blank lines, so output containing them can
	// never be pinned by an Example. This test is what lets ExampleRender stay
	// meaningful.
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), "one", 0)
	Post(cross(cur), "two", ttlFuture)
	testing.SetRealm(testing.NewUserRealm(stranger))
	Reap(cross(cur), 1)

	for _, path := range []string{"", "anything"} {
		out := Render(path)
		uassert.False(t, strings.Contains(out, "\n\n\n"), "blank-line run in Render("+path+")")
	}

	drain(cur)
}

func TestReapWalksNewestFirstSoCompactionHasWork(cur realm, t *testing.T) {
	// The ordering is economic, not cosmetic: in the backing list the oldest
	// indices are the ancestors of the newest, so a partial reap that took the
	// oldest first would leave nothing compactable and strand the tree
	// structure, which costs more than the notes do.
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	for i := 0; i < 16; i++ {
		Post(cross(cur), "note", 0)
	}
	first := notes.TotalSize() - 16
	last := notes.TotalSize() - 1

	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 4, Reap(cross(cur), 4))

	// The four highest indices went, and the four lowest survived.
	uassert.Equal(t, nil, notes.Get(last))
	uassert.True(t, notes.Get(first) != nil)

	// Which is the whole point: there is something to compact after one batch.
	uassert.True(t, Compactable() > 0)

	drain(cur)
}

// TestSummarizeNeutralizesAnAttackerAuthoredBody is the regression test for a
// hole this realm shipped with: Render emitted a note body into the board
// after nothing but a ReplaceAll of "\n" and "|", so anyone who paid to post
// could put arbitrary markdown on a page every reader of the realm loads.
//
// The body is the one string here an attacker controls and the board is an
// INLINE slot, so sanitize.InlineText owns it. Each case asserts the dangerous
// SEQUENCE is dead and the readable text survived, rather than pinning the
// exact escaped bytes, which are the sanitizer's business and not this realm's.
func TestSummarizeNeutralizesAnAttackerAuthoredBody(t *testing.T) {
	cases := []struct {
		name  string
		body  string
		gone  []string // sequences that must not survive into the page
		kept  string   // the readable text, which must
	}{
		{
			// The payload that matters: a phishing link rendered as prose,
			// attributed by the page to the realm rather than to the poster.
			name: "inline link",
			body: "[Claim your 100 GNOT](https://evil.example/drain)",
			gone: []string{"](", "](https"},
			kept: "Claim your 100 GNOT",
		},
		{
			// An image is a beacon: it fires on load and hands the attacker
			// the IP of everyone who opened the board.
			name: "image beacon",
			body: "![x](https://evil.example/pixel.png)",
			gone: []string{"![", "]("},
			kept: "pixel",
		},
		{
			// gnoweb renders a set of <gno-...> components, and raw HTML
			// besides; a body that can open one can lay out the page.
			name: "gnoweb component and raw html",
			body: "<gno-columns><h5>Official notice</h5>",
			gone: []string{"<gno-", "<h5>", "</h5>"},
			kept: "Official notice",
		},
		{
			// The old ReplaceAll("\n", " ") stopped exactly this and nothing
			// else. Keep it dead: one newline ends the bullet item, and every
			// byte after it is top-level markdown.
			name: "break out of the list item",
			body: "ok\n# Reaper is deprecated, use /r/evil/reaper",
			gone: []string{"\n"},
			kept: "Reaper is deprecated",
		},
		{
			// Folding only "\n" left the other three line terminators open.
			name: "exotic line terminators",
			body: "ok\r\n- fake row\u2028- another\u2029- third",
			gone: []string{"\r", "\n", "\u2028", "\u2029"},
			kept: "fake row",
		},
		{
			// Invisible reordering: the bytes say one thing, the page shows
			// another, and a reader diffing the two sees nothing.
			name: "bidi and zero-width",
			body: "safe\u202enote\u200b\u202c",
			gone: []string{"\u202e", "\u200b", "\u202c"},
			kept: "safe",
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			out := summarize(tc.body)
			for _, bad := range tc.gone {
				uassert.False(t, strings.Contains(out, bad),
					tc.name+": a dangerous sequence survived into "+out)
			}
			uassert.True(t, strings.Contains(out, tc.kept),
				tc.name+": escaping ate the readable text: "+out)
			uassert.True(t, utf8.ValidString(out), tc.name+": invalid UTF-8: "+out)
		})
	}
}

// TestSummarizeEscapesAnUnbalancedBracket covers the cross-row case: a "[" in
// one note and a "]" in another used to let two cheap notes bracket every row
// between them into one link.
func TestSummarizeEscapesAnUnbalancedBracket(t *testing.T) {
	uassert.Equal(t, "\\[", summarize("["))
	uassert.Equal(t, "\\]", summarize("]"))
	uassert.Equal(t, "\\[", ui.Excerpt("[", 48))
}

// TestSummarizeCutsOnARuneBoundary pins the other half of the old bug: the
// truncation sliced at a byte offset, so a body of multi-byte characters put
// half a character on the page. One emoji in a note was enough.
func TestSummarizeCutsOnARuneBoundary(t *testing.T) {
	// The leading "x" puts byte 48, the old cut point, in the middle of a
	// 4-byte rune rather than on a boundary.
	out := summarize("x" + strings.Repeat("\U0001F33E", 60))
	uassert.True(t, utf8.ValidString(out), "cut mid-rune: "+out)
	uassert.True(t, strings.HasSuffix(out, ui.Ellipsis), "long body should be elided: "+out)

	// A short body comes back whole, with no elision and nothing to escape.
	short := summarize("plain note")
	uassert.Equal(t, "plain note", short)
}

// TestRenderEscapesTheBoard is the end-to-end half: the sanitizer is only
// worth anything if Render is what calls it, and the board is the one place a
// stranger's bytes reach the page.
func TestRenderEscapesTheBoard(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), "[Claim 100 GNOT](https://evil.example)\n# Official", 0)

	out := Render("")
	uassert.False(t, strings.Contains(out, "](https://evil.example)"), out)
	uassert.False(t, strings.Contains(out, "\n# Official"), out)
	// The note stays legible, just inert: the text survives, the chrome does not.
	uassert.True(t, strings.Contains(out, "Claim 100 GNOT"), out)
	uassert.True(t, utf8.ValidString(out), "Render emitted invalid UTF-8")

	testing.SetRealm(testing.NewUserRealm(stranger))
	Reap(cross(cur), 100)
	Compact(cross(cur))
}

package crews

import (
	"strconv"
	"strings"
	"testing"
)

// Finding 325-cost-at-caps-1. A crew's page rendered every proposal the crew
// had ever had. Proposing is open to every member and nothing deletes one, so
// the cost every reader of that page paid grew without a bound anybody
// controls.
//
// Both comparison points are above the cap on purpose: comparing a count below
// it with one above measures the cap arriving, not the page being bounded.
func TestACrewPageIsBoundedByWhatItShows(cur realm, t *testing.T) {
	reset()
	id := create(cur, alice, 1000000, "the crew")

	for i := 0; i < 40; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		Propose(cross(cur), id, "proposal number "+strconv.Itoa(i))
	}
	small := Render("crew/" + strconv.FormatInt(id, 10))

	for i := 40; i < 200; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		Propose(cross(cur), id, "proposal number "+strconv.Itoa(i))
	}
	big := Render("crew/" + strconv.FormatInt(id, 10))

	rowsSmall := strings.Count(small, "\n|")
	rowsBig := strings.Count(big, "\n|")
	if rowsSmall == 0 {
		t.Fatal("no table rows rendered at all, so this test is measuring nothing")
	}
	if rowsBig > rowsSmall {
		t.Errorf("the crew page grew from %d rows to %d when the proposals went from 40 to 200: "+
			"every reader pays for every proposal the crew has ever had", rowsSmall, rowsBig)
	}
}

// Package crews is small-group coordination you can create in one
// transaction: three to fifteen people with a shared pot, a way to decide, and
// a way to leave with their share.
//
// It is the chain wiring for [gno.land/p/moul/x/social/crew], which holds the
// share math and the proposal state. This realm reads the caller, reads the
// coins attached to the call, asks the engine, and renders the result.
//
//	Create    pay in, and you are the crew's first member
//	Join      pay in at what a share is worth NOW, not at what it cost them
//	Fund      pay in and mint nothing, so every existing share is worth more
//	Propose   any member opens an advisory question
//	Vote      weighted by the shares you hold, changeable while it is open
//	Close     anyone, once the deadline has gone by
//	Ragequit  burn your shares, be credited your slice, leave
//	Withdraw  collect what you were credited
//
// # The shares are the token
//
// There is no second asset to issue. A share is the vote weight and the claim
// on the treasury at the same moment, minted by paying in and burned by
// leaving, so nothing about it is decorative and nobody has to be persuaded it
// is worth something. v0 keeps the shares as an internal ledger rather than one
// GRC20 per crew, because a GRC20 per crew means a realm per crew. A
// transferable share belongs in [gno.land/p/moul/x/social/coin], the sibling
// that refuses to exist until its mint rule, sink and buyer are declared; this
// realm does not import it.
//
// # The custody caveat, which is real
//
// ONE realm address holds EVERY crew's treasury, with per-crew accounting
// inside it. The chain sees one balance; which crew owns which part of it is a
// number in this realm's state. So a bug in the accounting is a bug across
// crews, not inside one: an arithmetic error that over-credits one crew's
// ragequit pays it out of another crew's money, and nothing at the bank layer
// would refuse that transfer.
//
// The fix is the instance-per-realm pattern (EFFECTIVE_GNO.md section 1.4): one
// realm per crew, each holding its own coins at its own address, with this
// package as the shared engine. That is v1. It is not v0 because deploying a
// realm per crew is a publish per crew, which is the opposite of "create it in
// one transaction", and the whole product claim here is the one transaction.
//
// # Payouts are pulled
//
// Nothing is ever pushed. A ragequit credits an internal ledger and the leaver
// calls [Withdraw] themselves, so one address that cannot be paid cannot wedge
// anybody else, and the credit is zeroed before the coins move.
package crews

import (
	"strconv"

	"chain"
	"chain/banker"
	"chain/runtime"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/envelope/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/social/crew/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/xmath/v1"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from the runtime, because every
// plain read this realm exports reports its CALLER and would build every link
// against the wrong realm.
const realmPath = "gno.land/r/moul/x/social/crews/v0"

// denom is the only coin a crew holds. ugnot and nothing else: a treasury that
// can hold several denominations needs a per-denomination share price, which is
// a different product.
const denom = "ugnot"

// IndexCrews is how many crews the index page lists.
const IndexCrews = 20

// IndexProposals is how many of a crew's proposals its page lists.
//
// Finding 325-cost-at-caps-1: the page rendered every proposal a crew had ever
// had. Proposing is open to every member and nothing deletes one, so the cost
// every reader pays grew without a bound anybody controls.
const IndexProposals = 20

// crews holds every crew, every proposal and the credit ledger. A redeploy
// wipes it, which is the trade gnomod.toml's private = true makes: see the
// comment there.
var crews = crew.New()

// Create opens a crew and makes the caller its first member.
//
// Send ugnot with the call: the founder's shares are bought out of it at
// crew.InitialPricePerShare, and the whole amount, remainder included, becomes
// the treasury. Returns the new crew's id.
func Create(cur realm, name string) int64 {
	// Both checks have to be here and not behind a helper. cur.IsCurrent()
	// before cur.Previous() is the realm-token rule; IsUserCall before the
	// envelope read is the payment one, because the envelope reports what
	// the SIGNER attached to the transaction and not what reached this
	// realm. Without it a realm the user called keeps the coins and calls
	// in here as many times as it likes, every call reading the same send.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	amount := envelope.RequireAtLeast(denom, crew.InitialPricePerShare)

	id, err := crews.Create(name, who, amount, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Create",
		"crew", id.String(),
		"founder", who.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return int64(id)
}

// Join mints the caller shares at what a share is worth right now and adds what
// they sent to the treasury. Returns the shares minted.
//
// The price is amount * totalShares / treasury, rounded down, so somebody
// joining a crew that has tripled its money pays three times what the founders
// did. Send at least the crew page's join price, treasury / totalShares rounded
// up, or there is no whole share to mint.
func Join(cur realm, crewID int64) int64 {
	// The two guards every payable call needs; see Create.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	id := store.ID(crewID)
	c, ok := crews.Get(id)
	if !ok {
		panic(crew.ErrNoCrew.Error())
	}
	amount := envelope.RequireAtLeast(denom, joinPrice(c))

	shares, err := crews.Join(id, who, amount)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Join",
		"crew", id.String(),
		"member", who.String(),
		"amount", strconv.FormatInt(amount, 10),
		"shares", strconv.FormatInt(shares, 10),
	)
	return shares
}

// joinPrice is the least a joiner can send and still be minted a share: the
// floor Join's envelope guard enforces, and the price a crew page quotes.
//
// The engine mints amount * totalShares / treasury, rounded down, so one whole
// share needs treasury / totalShares rounded UP. crew.Crew.PricePerShare rounds
// down, which is one ugnot short whenever the treasury is not an exact multiple
// of the share count, the ordinary state after any Fund: a joiner paying the
// quoted price passed the guard and then reverted on "buys no whole share".
// That method lives in a published package and cannot change in place, so the
// rule is here, next to the only guard that uses it. A crew nobody holds a
// share in is back at the opening price, the same branch Join takes.
func joinPrice(c *crew.Crew) int64 {
	if c.TotalShares == 0 || c.Treasury == 0 {
		return crew.InitialPricePerShare
	}
	return xmath.MulDivUp(1, c.Treasury, c.TotalShares)
}

// Fund adds what the caller sent to a crew's treasury and mints nothing, so
// every existing share is worth more afterwards.
//
// It is how revenue, a grant or a member topping the pot up arrives. Anyone may
// fund any crew, member or not: there is no way to refuse a transfer on this
// chain anyway, and pretending otherwise would only move the donation to a bank
// send the realm cannot account for.
func Fund(cur realm, crewID int64) int64 {
	// The two guards every payable call needs; see Create.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	amount := envelope.RequireAtLeast(denom, 1)

	if err := crews.Fund(store.ID(crewID), amount); err != nil {
		panic(err.Error())
	}
	chain.Emit("Fund",
		"crew", store.ID(crewID).String(),
		"from", who.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return amount
}

// Propose opens an advisory question on a crew. Any member may propose, and it
// stays open for crew.VoteBlocks blocks. Returns the proposal's id.
//
// A proposal EXECUTES NOTHING. Passing one records that the crew agreed by
// share weight, and moves no coins, changes no membership and binds no code.
// Executing a payout is the next step and it is not in v0.
func Propose(cur realm, crewID int64, text string) int64 {
	who := caller(cur)
	pid, err := crews.Propose(store.ID(crewID), who, text, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Propose",
		"crew", store.ID(crewID).String(),
		"proposal", pid.String(),
		"author", who.String(),
	)
	return int64(pid)
}

// Vote records the caller's ballot, weighted by the shares they hold at this
// moment. One ballot per member, changeable while the proposal is open.
func Vote(cur realm, proposalID int64, yes bool) {
	who := caller(cur)
	pid := store.ID(proposalID)
	if err := crews.Vote(pid, who, yes, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	chain.Emit("Vote",
		"proposal", pid.String(),
		"voter", who.String(),
		"yes", strconv.FormatBool(yes),
	)
}

// Close records a proposal as passed or failed once its deadline has gone by,
// and returns which. Anyone may call it: closing is bookkeeping, not authority.
func Close(cur realm, proposalID int64) bool {
	pid := store.ID(proposalID)
	passed, err := crews.Close(pid, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Close", "proposal", pid.String(), "passed", strconv.FormatBool(passed))
	return passed
}

// Ragequit burns every share the caller holds, credits them their pro-rata
// slice of the treasury and removes them from the crew. Returns the amount
// credited, which [Withdraw] collects.
//
// Nobody has to agree. That is what makes a share mean something: the exit is
// priced by the same number that votes, and a member outvoted on everything can
// still leave with what they put in plus their part of what the crew built.
func Ragequit(cur realm, crewID int64) int64 {
	who := caller(cur)
	id := store.ID(crewID)
	shares, amount, err := crews.Ragequit(id, who)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Ragequit",
		"crew", id.String(),
		"member", who.String(),
		"shares", strconv.FormatInt(shares, 10),
		"amount", strconv.FormatInt(amount, 10),
	)
	return amount
}

// Withdraw sends the caller everything they have been credited, and returns it.
//
// The credit is zeroed before the coins move, so a reentrant call finds nothing
// left to take. Nothing in this realm ever pushes value: one address that
// cannot be paid must not be able to wedge everybody else.
func Withdraw(cur realm) int64 {
	who := caller(cur)
	amount, err := crews.Withdraw(who)
	if err != nil {
		panic(err.Error())
	}

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), who, chain.NewCoins(chain.NewCoin(denom, amount)))

	chain.Emit("Withdraw", "payee", who.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Get returns a crew's name, the height it was created at, how many members it
// has, its total shares and its treasury in ugnot.
//
// Flat values rather than the crew itself: handing out a pointer to live state
// is a mutation handle nothing checks, and a struct is not something a wallet
// can decode anyway.
func Get(crewID int64) (string, int64, int, int64, int64) {
	c, ok := crews.Get(store.ID(crewID))
	if !ok {
		return "", 0, 0, 0, 0
	}
	return c.Name, c.CreatedAt, c.MemberCount(), c.TotalShares, c.Treasury
}

// Count is how many crews exist.
func Count() int { return crews.Len() }

// SharesOf is how many shares who holds in a crew.
func SharesOf(crewID int64, who address) int64 {
	c, _ := crews.Get(store.ID(crewID))
	return c.SharesOf(who)
}

// MemberCount is how many people are in a crew.
func MemberCount(crewID int64) int {
	c, _ := crews.Get(store.ID(crewID))
	return c.MemberCount()
}

// Treasury is what a crew holds, in ugnot. The coins themselves sit at this
// realm's single address: see the package doc on custody.
func Treasury(crewID int64) int64 {
	c, _ := crews.Get(store.ID(crewID))
	if c == nil {
		return 0
	}
	return c.Treasury
}

// ValuePerShare is what one of a crew's shares is worth in ugnot, rounded down.
func ValuePerShare(crewID int64) int64 {
	c, _ := crews.Get(store.ID(crewID))
	return c.ValuePerShare()
}

// ProposalOf returns a proposal's crew, author, text, deadline and whether it
// has been closed and passed.
func ProposalOf(proposalID int64) (int64, address, string, int64, bool, bool) {
	p, ok := crews.Proposal(store.ID(proposalID))
	if !ok {
		return 0, "", "", 0, false, false
	}
	return int64(p.CrewID), p.Author, p.Text, p.Deadline, p.Closed, p.Passed
}

// Tally is a proposal's share-weighted yes and no.
func Tally(proposalID int64) (int64, int64) {
	p, ok := crews.Proposal(store.ID(proposalID))
	if !ok {
		return 0, 0
	}
	return p.Yes, p.No
}

// CreditOf is what an address can withdraw right now, in ugnot.
func CreditOf(who address) int64 { return crews.CreditOf(who) }

// TotalOwed is every outstanding credit, which is the part of this realm's
// balance that belongs to people who have already left.
func TotalOwed() int64 { return crews.TotalOwed() }

// caller is the address that called us, checked the one way that is safe.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	return cur.Previous().Address()
}

package crews

import (
	"strconv"
	"strings"
	"testing"

	"chain"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/social/crew/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

// The price a crew page shows a joiner, and the floor Join's envelope guard
// enforces, must both be exactly the least amount that mints a whole share.
//
// Join mints amount * totalShares / treasury, rounded down, so that amount is
// treasury / totalShares rounded UP. Rounded down instead, it is one ugnot
// short whenever the treasury is not an exact multiple of the share count,
// which is the ordinary state after any Fund: the page quotes a price, the
// guard accepts it, and the join reverts on "buys no whole share".
//
// The table is over that rule, not over one input: awkward remainders where
// floor and ceiling differ, exact multiples where they must not, and a crew
// everybody left, where the opening price applies.
func TestTheShownPriceBuysAShareAndOneLessIsRefusedByTheGuard(cur realm, t *testing.T) {
	cases := []struct {
		name   string
		create int64 // what the founder pays in, at the opening price
		fund   int64 // then funded with this, which mints nothing
		leave  bool  // then the founder ragequits, leaving an empty crew
		want   int64 // the least amount that mints one share
	}{
		{"treasury 3001 over 2 shares", 2000, 1001, false, 1501},
		{"treasury 3001 over 3 shares", 3000, 1, false, 1001},
		{"ten GNOT and seven ugnot over 10000 shares", tenGNOT, 7, false, 1001},
		{"ten GNOT and 999 ugnot over 10000 shares", tenGNOT, 999, false, 1001},
		{"exact multiple at the opening price", tenGNOT, 0, false, 1000},
		{"exact multiple after doubling", tenGNOT, tenGNOT, false, 2000},
		{"a single share", 1000, 0, false, 1000},
		{"everybody left", 1000, 0, true, crew.InitialPricePerShare},
	}
	for _, tc := range cases {
		reset()
		id := create(cur, alice, tc.create, "crew")
		if tc.fund > 0 {
			fund(cur, carol, tc.fund, id)
		}
		if tc.leave {
			testing.SetRealm(testing.NewUserRealm(alice))
			Ragequit(cross(cur), id)
		}

		// The oracle, independent of the code under test: the least a with
		// a * shares >= treasury, or the opening price when nobody holds one.
		_, _, _, shares, treasury := Get(id)
		oracle := crew.InitialPricePerShare
		if shares > 0 && treasury > 0 {
			oracle = treasury / shares
			if treasury%shares != 0 {
				oracle++
			}
		}
		urequire.Equal(t, tc.want, oracle, tc.name+": the table agrees with the rule")

		page := Render("crew/" + strconv.FormatInt(id, 10))
		uassert.Equal(t, tc.want, shownPrice(t, page),
			tc.name+": the page quotes what buys a share: "+page)

		// One ugnot under it is refused by the envelope guard, which names the
		// real price, rather than by Join after the guard let it through.
		testing.IssueCoins(realmAddr, chain.Coins{{denom, tc.want - 1}})
		testing.SetOriginSend(chain.Coins{{denom, tc.want - 1}})
		testing.SetRealm(testing.NewUserRealm(bob))
		uassert.AbortsContains(t, cur, "costs at least "+strconv.FormatInt(tc.want, 10)+denom,
			func() { Join(cross(cur), id) }, tc.name+": the guard refuses one ugnot short")

		// Exactly the quoted price buys exactly one share.
		got := join(cur, bob, tc.want, id)
		uassert.Equal(t, int64(1), got, tc.name+": the quoted price mints one share")
	}
}

// shownPrice reads the price cell of a crew page's summary table, the first
// row after the header that starts with "| members", in ugnot. It is keyed on
// the row's position, not the column's title, so it reads the same cell
// whatever that column is called.
func shownPrice(t *testing.T, page string) int64 {
	lines := strings.Split(page, "\n")
	for i, l := range lines {
		if !strings.HasPrefix(l, "| members") {
			continue
		}
		urequire.True(t, i+2 < len(lines), "the summary table has a row: "+page)
		cells := strings.Split(lines[i+2], "|")
		urequire.Equal(t, 6, len(cells), "four cells: "+lines[i+2])
		return parseGNOT(t, strings.TrimSpace(cells[4]))
	}
	t.Fatalf("no summary table on the crew page: %s", page)
	return 0
}

// parseGNOT turns num.GNOTf's "1.0015 GNOT" back into ugnot.
func parseGNOT(t *testing.T, s string) int64 {
	urequire.True(t, strings.HasSuffix(s, " GNOT"), "a GNOT amount: "+s)
	s = strings.TrimSuffix(s, " GNOT")
	whole, frac := s, ""
	if i := strings.Index(s, "."); i >= 0 {
		whole, frac = s[:i], s[i+1:]
	}
	urequire.True(t, len(frac) <= 6, "at most six decimals: "+s)
	frac += strings.Repeat("0", 6-len(frac))
	w, err := strconv.ParseInt(whole, 10, 64)
	urequire.NoError(t, err, s)
	f, err := strconv.ParseInt(frac, 10, 64)
	urequire.NoError(t, err, s)
	return w*1000000 + f
}

package crews

import (
	"strconv"

	"chain/runtime"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/num/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/realmpath/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/social/crew/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/xmath/v1"
)

// Render routes three views: the index, one crew, and one proposal.
func Render(path string) string {
	req := realmpath.Parse(path)

	switch req.PathPart(0) {
	case "":
		return renderIndex()
	case "crew":
		return renderCrew(req.PathPart(1))
	case "proposal":
		return renderProposal(req.PathPart(1))
	default:
		return md.H1("Not found") + "No such view: " + ui.Inline(req.Path)
	}
}

func renderIndex() string {
	out := md.H1("Crews")
	out += "Three to fifteen people with a shared pot, a way to decide, and a way to " +
		"leave with their share. One transaction to start one.\n\n"

	t := ui.NewTable("crews", "proposals", "owed to people who left")
	t.Row(
		strconv.Itoa(crews.Len()),
		strconv.Itoa(crews.ProposalCount()),
		num.GNOTf(crews.TotalOwed()),
	)
	out += t.String()

	out += md.H2("The crews")
	out += crewTable(crews.List(IndexCrews))

	out += "\n" + ui.Action("Start a crew", "Create", "name", "") + "\n"

	out += md.H2("How a share works")
	out += md.BulletList([]string{
		"A share is the vote weight and the claim on the treasury at once. There is no second token.",
		"Joining mints shares at what a share is worth NOW: " +
			md.InlineCode("amount * totalShares / treasury") +
			", rounded down, so a late joiner cannot buy into value the others built.",
		"Ragequitting burns every share you hold and credits you " +
			md.InlineCode("shares * treasury / totalShares") +
			", rounded down. Nobody has to agree.",
		"Both round in the crew's favour. The last member out holds every share, " +
			"so the treasury still empties to the last ugnot.",
		"A proposal is advisory text. Passing one records agreement and executes nothing.",
	})

	out += md.H2("Custody")
	out += "One realm address holds every crew's treasury, with per-crew accounting " +
		"inside. A bug in that accounting is a bug across crews, not inside one. " +
		"The fix is one realm per crew, and it is v1.\n"

	return out
}

func renderCrew(raw string) string {
	id, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Crews") + "Not a crew id: " + ui.Inline(raw)
	}
	c, found := crews.Get(id)
	if !found {
		return md.H1("Crews") + "No crew #" + id.String()
	}

	out := md.H1(ui.Inline(c.Name))
	out += md.Italic("crew #"+id.String()+" · opened at block "+
		strconv.FormatInt(c.CreatedAt, 10)) + "\n\n"

	t := ui.NewTable("members", "shares", "treasury", "to join")
	t.Row(
		strconv.Itoa(c.MemberCount())+" of "+strconv.Itoa(crew.MaxMembers),
		strconv.FormatInt(c.TotalShares, 10),
		num.GNOTf(c.Treasury),
		num.GNOTf(joinPrice(c)),
	)
	out += t.String()

	out += md.H2("Members")
	if c.MemberCount() == 0 {
		out += ui.Empty("Everybody has left. The next member in pays the opening price again.")
	} else {
		m := ui.NewTable("member", "shares", "weight", "worth")
		for _, who := range c.Members() {
			shares := c.SharesOf(who)
			m.Row(
				ui.Addr(who),
				strconv.FormatInt(shares, 10),
				num.Pct(xmath.MulDiv(shares, 10000, c.TotalShares)),
				num.GNOTf(xmath.MulDiv(shares, c.Treasury, c.TotalShares)),
			)
		}
		out += m.String()
	}

	out += md.H2("Proposals")
	out += proposalTable(c.Proposals())
	out += "\nA proposal is advisory text. Passing one records that the crew agreed " +
		"by share weight, and executes nothing.\n"

	out += "\n" + ui.Join(" · ",
		ui.Action("Join", "Join", "crewID", id.String()),
		ui.Action("Fund", "Fund", "crewID", id.String()),
		ui.Action("Propose", "Propose", "crewID", id.String(), "text", ""),
		ui.Action("Ragequit", "Ragequit", "crewID", id.String()),
	) + "\n"
	return out
}

func renderProposal(raw string) string {
	pid, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Crews") + "Not a proposal id: " + ui.Inline(raw)
	}
	p, found := crews.Proposal(pid)
	if !found {
		return md.H1("Crews") + "No proposal #" + pid.String()
	}

	out := md.H1("Proposal #" + pid.String())
	out += md.Blockquote(ui.Inline(p.Text)) + "\n"

	crewName := "crew #" + p.CrewID.String()
	if c, ok := crews.Get(p.CrewID); ok {
		crewName = c.Name
	}
	out += md.Italic("by "+ui.Addr(p.Author)+" · in "+
		md.Link(ui.ShortN(crewName, crew.ExcerptLen, 0), crewURL(p.CrewID))) + "\n\n"

	now := runtime.ChainHeight()
	t := ui.NewTable("state", "yes", "no", "voters")
	t.Row(
		state(p, now),
		strconv.FormatInt(p.Yes, 10),
		strconv.FormatInt(p.No, 10),
		strconv.Itoa(p.Voters()),
	)
	out += t.String()

	if p.Open(now) {
		out += "\n" + ui.Join(" · ",
			ui.Action("Vote yes", "Vote", "proposalID", pid.String(), "yes", "true"),
			ui.Action("Vote no", "Vote", "proposalID", pid.String(), "yes", "false"),
		) + "\n"
	} else if !p.Closed {
		out += "\n" + ui.Action("Close it", "Close", "proposalID", pid.String()) + "\n"
	}
	return out
}

// crewTable lists crews, newest first.
func crewTable(items []crew.Listing) string {
	t := ui.NewTable("crew", "members", "shares", "treasury")
	for _, it := range items {
		t.Row(
			// ShortN truncates without escaping and md.Link escapes what it
			// is given: ui.Inline here would escape twice and render the
			// backslashes. A pipe is what md.Link's escaper does NOT cover,
			// which is why crew.ValidName refuses one at write time.
			md.Link(ui.ShortN(it.Crew.Name, crew.ExcerptLen, 0), crewURL(it.ID)),
			strconv.Itoa(it.Crew.MemberCount()),
			strconv.FormatInt(it.Crew.TotalShares, 10),
			num.GNOTf(it.Crew.Treasury),
		)
	}
	return t.OrEmpty("No crews yet.")
}

// proposalTable lists a crew's proposals, newest first.
//
// The link title is the id and not the text, which is the opposite of
// crewTable and deliberate: a proposal's text is free prose and may contain a
// pipe, md.Link's escaper leaves pipes alone, and a pipe in a link title inside
// a table cell opens a column. So the chrome carries the link and the prose
// goes through ui.Cell, which is the escaper that knows it is in a table.
func proposalTable(ids []store.ID) string {
	now := runtime.ChainHeight()
	// Finding 325-cost-at-caps-1: this rendered every proposal a crew has
	// ever had, and proposing is open to every member with no delete path.
	// Newest first already, so the bound is on where the walk stops.
	total := len(ids)
	stop := 0
	if total > IndexProposals {
		stop = total - IndexProposals
	}
	t := ui.NewTable("#", "proposal", "state", "yes", "no")
	for i := total - 1; i >= stop; i-- {
		p, ok := crews.Proposal(ids[i])
		if !ok {
			continue
		}
		t.Row(
			md.Link("#"+ids[i].String(), proposalURL(ids[i])),
			// Cut on a rune boundary first, escape once after: escaping
			// first and cutting after can strand a lone backslash.
			ui.Cell(ui.ShortN(p.Text, crew.ExcerptLen, 0)),
			state(p, now),
			strconv.FormatInt(p.Yes, 10),
			strconv.FormatInt(p.No, 10),
		)
	}
	out := t.OrEmpty("Nothing has been proposed yet.")
	if total > IndexProposals {
		out += md.Italic("Showing the newest "+strconv.Itoa(IndexProposals)+" of "+
			strconv.Itoa(total)+" proposals.") + "\n"
	}
	return out
}

// state is the one word a proposal is in at height now.
func state(p *crew.Proposal, now int64) string {
	switch {
	case p.Open(now):
		return "open until " + strconv.FormatInt(p.Deadline, 10)
	case !p.Closed:
		return "awaiting a close"
	case p.Passed:
		return "passed"
	default:
		return "failed"
	}
}

// crewURL is the gnoweb path of one crew.
func crewURL(id store.ID) string { return realmURL() + ":crew/" + id.String() }

// proposalURL is the gnoweb path of one proposal.
func proposalURL(id store.ID) string { return realmURL() + ":proposal/" + id.String() }

// realmURL is this realm's gnoweb path. The chain domain is the first element
// of a package path and a gnoweb path is the rest of it, so this is a prefix
// strip and not a hostname the realm has to know.
func realmURL() string {
	for i := 0; i < len(realmPath); i++ {
		if realmPath[i] == '/' {
			return realmPath[i:]
		}
	}
	return "/" + realmPath
}

// Package curated is a list anyone can get onto by locking a deposit, and
// anyone can try to get somebody else off by matching that deposit with a bond.
// The loser of the challenge pays the winner.
//
// It is the registry member of a family of small social apps: a list is the
// thing every other one of them eventually needs, and a list is only worth
// reading if being on it cost something.
//
//	Apply(key, url, description)  -send 1000000ugnot   list it, immediately
//	Challenge(key)                -send <the deposit>  object to it
//	Vote(key, keep)                                    while the window is open
//	Resolve(key)                                       anyone, after it closes
//	Unlist(key)                                        the owner, if unchallenged
//	Withdraw()                                         collect what you won
//
// # Money in, money out
//
// Coins arrive in the envelope of a call and sit at this realm's address. They
// never leave by being pushed: a payout is a credit in a ledger and the payee
// calls [Withdraw] for their own. A realm that looped over winners and sent to
// each one would fail entirely when one of them could not be paid, and would
// hand a griefer a cheap denial of service for the price of one entry.
//
// Every ugnot here is therefore either backing a live entry or an open
// challenge, or already assigned to somebody. The realm's own tests assert
// exactly that against the chain balance.
//
// # Voting is sybil-prone, and the bonds are GNOT
//
// [Vote] is one address, one vote, unweighted, and an address is free. Read a
// resolution as "nobody with a stake objected enough", never as a verdict.
// Gating a vote on something harder to manufacture is a different problem with
// its own realm behind it, r/moul/x/social/vouch, a sibling in this family.
//
// Bonds are GNOT and not a token of this list's own: see the README on why
// that is the only answer available at v0 and what would change it.
//
// # What v0 does not do, in the order it should be fixed
//
//  1. Voters are paid nothing. Voting costs gas and returns nothing, so the
//     only two addresses with a reason to vote are the ones with money on the
//     outcome. A share of the loser's stake for the winning side is the
//     standard answer and the first thing to add.
//  2. There is no application period: [Apply] lists immediately.
//  3. A challenge cannot be withdrawn and a vote cannot be changed.
package curated

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strconv"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/envelope/v0"
	cu "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/social/curated/v0"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. Render builds its links from it rather than from
// unsafe.CurrentRealm(), which in a plain read reports the CALLER.
const realmPath = "gno.land/r/moul/x/social/curated/v0"

const (
	// Denom is what a deposit and a bond are paid in. Native coins, so the
	// amounts are real to a challenger before this list is worth anything.
	Denom = "ugnot"

	// Deposit is what listing costs, and therefore also what challenging one
	// of today's entries costs. One GNOT: enough to make a thousand junk
	// entries a real expense, cheap enough that one honest entry is not a
	// decision.
	Deposit = int64(1000000)

	// ChallengeBlocks is how long a challenge takes to resolve. Long enough
	// for a reader who is not watching the chain to notice and vote, short
	// enough that an entry is not held hostage.
	ChallengeBlocks = int64(1000)
)

// list is every entry and the credit ledger behind them. A redeploy would wipe
// it while leaving the coins at the address, which is what the note in
// gnomod.toml is about.
var list = cu.New(Deposit, ChallengeBlocks)

// Apply lists an entry under key, in exchange for exactly [Deposit] ugnot.
//
// The entry is on the list the moment this returns: there is no application
// period in v0, and the check on a bad entry is that anybody can challenge it.
// The deposit comes back through [Unlist] and [Withdraw] if nobody ever does.
//
// key is a slug: lowercase ASCII letters, digits, '-', '_' and '.', starting
// alphanumeric. A key whose entry was removed is free to apply for again.
func Apply(cur realm, key, url, description string) {
	// Both checks are inlined rather than hidden behind caller(), and in this
	// order. cur.IsCurrent() before cur.Previous() is the realm-token rule;
	// IsUserCall before the envelope read is the payment one, because the
	// envelope reports what the SIGNER attached to the transaction and not
	// what reached this realm. Without it a realm the user called keeps the
	// coins and calls in here as often as it likes, every call reading the
	// same send: that is r/moul/grant Fund, which recorded 5 donations of
	// 1 GNOT from one 1 GNOT send with nothing in the treasury.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("curated: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	paid := envelope.RequireExactly(Denom, Deposit)
	if err := list.Apply(key, url, description, who, paid, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	chain.Emit("Apply", "key", key, "owner", who.String(),
		"deposit", strconv.FormatInt(paid, 10))
}

// Challenge objects to an entry, in exchange for a bond equal to that entry's
// own deposit, and opens a vote that closes [ChallengeBlocks] blocks later.
//
// An owner cannot challenge their own entry: it would cost them nothing and
// would make the entry immune to a real challenge for the whole window.
func Challenge(cur realm, key string) {
	// The two guards every payable call needs, inlined; see Apply.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("curated: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	// The bond is read before the envelope is, so somebody who attaches coins
	// to a challenge of something unchallengeable is told which of the two is
	// wrong.
	bond, ok := list.BondFor(key)
	if !ok {
		panic("curated: " + key + " is not an entry that can be challenged")
	}
	envelope.RequireExactly(Denom, bond)
	if err := list.Challenge(key, who, bond, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	c, _ := list.ChallengeOf(key)
	chain.Emit("Challenge", "key", key, "by", who.String(),
		"bond", strconv.FormatInt(bond, 10),
		"deadline", strconv.FormatInt(c.Deadline, 10))
}

// Vote takes a side on an open challenge: keep the entry, or remove it.
//
// One address, one vote, unweighted, and it cannot be changed. An address is
// free, so this is cheap to manufacture; see the package doc.
func Vote(cur realm, key string, keep bool) {
	who := caller(cur)
	if err := list.Vote(key, who, keep, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	chain.Emit("Vote", "key", key, "by", who.String(), "keep", strconv.FormatBool(keep))
}

// Resolve closes a challenge whose window has passed. Anyone may call it, so
// neither party can stall the other by sitting still.
//
// A majority of keep votes keeps the entry and credits its owner the bond.
// Otherwise the entry is removed and the challenger is credited the bond plus
// the deposit. A tie, including nobody voting at all, keeps the entry: the
// incumbent is the one already at risk, so a challenge that convinced nobody
// loses, which is what makes being wrong cost something.
func Resolve(cur realm, key string) {
	who := caller(cur)
	out, err := list.Resolve(key, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Resolve", "key", key,
		"kept", strconv.FormatBool(out.Kept),
		"winner", out.Winner.String(),
		"amount", strconv.FormatInt(out.Amount, 10),
		"keep", strconv.FormatInt(out.Keep, 10),
		"remove", strconv.FormatInt(out.Remove, 10),
		"by", who.String())
}

// Unlist takes the caller's own entry off the list and credits them the
// deposit back, which [Withdraw] then pays out.
//
// It is refused while a challenge is open: an owner who could walk away
// mid-challenge would be risking nothing, which is the one thing the deposit
// exists to prevent.
func Unlist(cur realm, key string) {
	who := caller(cur)
	if err := list.Unlist(key, who); err != nil {
		panic(err.Error())
	}
	chain.Emit("Unlist", "key", key, "owner", who.String())
}

// Withdraw pays the caller everything credited to them and returns it.
//
// This is the only way coins leave the realm. The credit is zeroed before the
// transfer, so a reentrant call finds nothing left to take.
func Withdraw(cur realm) int64 {
	who := caller(cur)
	amount, err := list.Withdraw(who)
	if err != nil {
		panic(err.Error())
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), who, chain.NewCoins(chain.NewCoin(Denom, amount)))

	chain.Emit("Withdraw", "to", who.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Get returns what is known about an entry: its URL, its description, its
// owner, the deposit behind it, the height it was listed at, and its state,
// which is one of "listed", "challenged" or "removed".
//
// A key that was never applied for reads as the zero value with an empty
// state, which is how a caller tells it from a removed one.
func Get(key string) (url, description string, owner address, deposit, at int64, state string) {
	e, ok := list.Get(key)
	if !ok {
		return "", "", "", 0, 0, ""
	}
	return e.URL, e.Description, e.Owner, e.Deposit, e.At, e.State.String()
}

// Count is how many entries are on the list right now. A challenged entry
// counts: a challenge is an objection, not a verdict.
func Count() int { return list.Count() }

// Listed is every key on the list, oldest first.
func Listed() []string {
	entries := list.Listed()
	out := make([]string, 0, len(entries))
	for _, e := range entries {
		out = append(out, e.Key)
	}
	return out
}

// IsListed reports whether key is on the list right now.
func IsListed(key string) bool { return list.IsListed(key) }

// ChallengeOf returns the open challenge against key: who opened it, the bond
// they put up, the height voting closes at, the two vote counts, and whether
// there is one at all.
func ChallengeOf(key string) (challenger address, bond, deadline, keep, remove int64, open bool) {
	c, ok := list.ChallengeOf(key)
	if !ok {
		return "", 0, 0, 0, 0, false
	}
	return c.Challenger, c.Bond, c.Deadline, c.Keep, c.Remove, true
}

// CreditOf is what who can collect with [Withdraw] right now.
func CreditOf(who address) int64 { return list.CreditOf(who) }

// caller is the address that called us, checked the one way that is safe.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	return cur.Previous().Address()
}

package curated

import (
	"strings"
	"testing"

	"chain"
	"chain/banker"
	"chain/runtime"

	cu "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/social/curated/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

var realmAddr = chain.PackageAddress(realmPath)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
	dave  = testutils.TestAddress("dave")
)

// reset clears realm state. Realm globals live for the whole test binary, so
// every entry, challenge and credit a later test reads starts here. The BANK
// does not carry over the same way, which is why every balance is asserted in
// the test that issued it.
func reset() {
	list = cu.New(Deposit, ChallengeBlocks)
}

// pay credits the realm the way a real transaction would: the runtime deposits
// the envelope at the realm's address, then OriginSend reports it to the
// crossing function.
func pay(amount int64) {
	testing.IssueCoins(realmAddr, chain.Coins{{Denom, amount}})
	testing.SetOriginSend(chain.Coins{{Denom, amount}})
}

// apply lists an entry as who. It crosses immediately after SetRealm, which is
// what makes the account switch take: a helper that sets the realm and does
// not itself cross is silently ignored.
func apply(cur realm, who address, key, url, description string) {
	pay(Deposit)
	testing.SetRealm(testing.NewUserRealm(who))
	Apply(cross(cur), key, url, description)
}

// challenge objects to an entry as who, bonding what that entry's deposit was.
func challenge(cur realm, who address, key string) {
	_, _, _, bond, _, _ := Get(key)
	pay(bond)
	testing.SetRealm(testing.NewUserRealm(who))
	Challenge(cross(cur), key)
}

// balance is what addr holds on chain right now.
func balance(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoins(addr).AmountOf(Denom)
}

func TestApplyTakesExactlyTheDepositAndListsAtOnce(cur realm, t *testing.T) {
	reset()

	// Underpaying and overpaying are both refused: a realm that silently kept
	// the excess would have invented a fee nobody agreed to.
	pay(Deposit - 1)
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "costs exactly", func() {
		Apply(cross(cur), "gnoswap", "https://gnoswap.io", "an AMM")
	})
	pay(Deposit + 1)
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "costs exactly", func() {
		Apply(cross(cur), "gnoswap", "https://gnoswap.io", "an AMM")
	})
	uassert.Equal(t, 0, Count())

	apply(cur, alice, "gnoswap", "https://gnoswap.io", "an AMM on gno.land")

	url, description, owner, deposit, at, state := Get("gnoswap")
	uassert.Equal(t, "https://gnoswap.io", url)
	uassert.Equal(t, "an AMM on gno.land", description)
	uassert.Equal(t, alice.String(), owner.String())
	uassert.Equal(t, Deposit, deposit)
	uassert.Equal(t, runtime.ChainHeight(), at)
	uassert.Equal(t, "listed", state)

	uassert.True(t, IsListed("gnoswap"))
	uassert.Equal(t, 1, Count())
	urequire.Equal(t, 1, len(Listed()))
	uassert.Equal(t, "gnoswap", Listed()[0])

	// A key that was never applied for reads as the empty state.
	_, _, _, _, _, state = Get("nothing")
	uassert.Equal(t, "", state)
	uassert.False(t, IsListed("nothing"))
}

